  ["_CeladonMart2FCurrentFloorSignText"] = "Spitzen-Items für\nTRAINER!\f2F: TRAINER-\n    MARKT",
  ["_CeladonMart2FGirlText"] = "Für lange Touren\nsolltest du BELE-\vBER kaufen.",
  ["_CeladonMart2FMiddleAgedManText"] = "SUPSCHAB hält\nschwache POKéMON\vfern...\fHmm, ein stärkeres\nSCHABAB eben!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "TM18 ist KONTER!\nNicht der Tresen,\van dem ich lehne!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Dein Beutel ist\nvoller Items!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Oh, hi! Ich habe\nPOKéMON endlich\vdurchgespielt!\fNoch nicht fertig?\nDas hilft dir\vvielleicht!",
  ["_CeladonMart3FCurrentFloorSignText"] = "3F: TV-SPIELE",
  ["_CeladonMart3FFightingGameText"] = "Ein Prügelspiel!\nSieht hart aus!",
  ["_CeladonMart3FGameBoyKid1Text"] = "Gefangene POKéMON\nwerden mit ID-Nr.\vund OT registriert\v- dem Namen ihres\vFängers!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Super!\fMein Kumpel\ntauscht sein\vGARSTELLA für\vmein GEOROK!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Komm, GEOROK!\fIch liebe GEOROK!\nIch sammle sie!\fHäh?\fGEOROK wurde zu\neinem anderen\vPOKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Getauschte POKéMON\nerkennst du an\vihrer ID-Nummer!",
  ["_CeladonMart3FPokemonPosterText"] = "Rot und Blau!\nBeides POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Ein Puzzlespiel!\nMacht süchtig!",
  ["_CeladonMart3FRPGText"] = "Ein RPG! Dafür\nist keine Zeit!",
  ["_CeladonMart3FSNESText"] = "Ein SNES!",
  ["_CeladonMart3FSportsGameText"] = "Ein Sportspiel!\nWas für Papa!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Sag es mit einem\nGeschenk!\f4F: GESCHENKE\fEntwicklungs-\nAktion! Element-\vSTEINE im Angebot!",
  ["_CeladonMart4FSuperNerdText"] = "Ich hole eine\nPOKéPUPPE für\vmeine Freundin!",
  ["_CeladonMart4FYoungsterText"] = "Ich weiß was Nütz-\nliches:\fVor wilden POKéMON\nkannst du fliehen,\vwenn du sie mit\veiner POKéPUPPE\vablenkst!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5F: DROGERIE",
  ["_CeladonMart5FGentlemanText"] = "Stärkungsmittel\nfür POKéMON gibt\ves nur hier.\fKALZIUM steigert\ndie SPEZIAL-Werte.\fCARBON steigert\ndie INITIATIVE.",
  ["_CeladonMart5FSailorText"] = "Ich brauche Stär-\nkungsmittel.\fPROTEIN erhöht den\nANGRIFF.\fEISEN erhöht die\nVERTEIDIGUNG!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "DACHTERRASSE:\nGETRÄNKEAUTOMATEN",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ich habe Durst!\nIch will was\vtrinken!\fIhr etwas zu\ntrinken geben?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Welches Getränk\ngibst du ihr?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Nein danke!\nIch habe doch\vkeinen Durst!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ich habe Durst!\nIch will was\vtrinken!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Du hast keinen\nPlatz dafür!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} erhält\nTM49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\f{RAM:wStringBuffer} enthält\nEISSTRAHL!\fEr kann das Ziel\nmanchmal ein-\vfrieren!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\f{RAM:wStringBuffer} enthält\nSTEINHAGEL!\fEr kann das Ziel\nmanchmal er-\vschrecken!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\fTM49 enthält\nTRIPLETTE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Juhu!\fTAFELWASSER!\fDanke!\fDafür bekommst du\ndas von mir!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Juhu!\fLIMONADE!\fDanke!\fDafür bekommst du\ndas von mir!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Juhu!\fSPRUDEL!\fDanke!\fDafür bekommst du\ndas von mir!",
  ["_CeladonMartRoofSuperNerdText"] = "Meine Schwester\nist tatsächlich\vTRAINERIN.\fAber sie ist so\nkindisch, sie\vmacht mich irre!",
  ["_CeladonPokecenterBeautyText"] = "Ich bin den RADWEG\nvon FUCHSANIA aus\vhochgefahren!",
  ["_CeladonPokecenterGentlemanText"] = "Die POKéFLÖTE\nweckt POKéMON mit\veinem Ton, den nur\vsie hören können!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "Der ANGRIFF aller\nPOKéMON steigt\vetwas.\fAußerdem kannst du\njederzeit BLITZ\veinsetzen.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "POKéMON bis L30\ngehorchen dir.\fHöhere werden\naufsässig!\fAußerdem kannst du\nZERSCHNEIDER auch\vaußerhalb von\vKämpfen nutzen.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Alle POKéMON\ngehorchen dir!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "POKéMON bis L70\ngehorchen dir.\fHöhere werden\naufsässig!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "POKéMON-ORDEN be-\nsitzen nur fähige\vTRAINER.\fDu hast mindestens\neinen, wie ich\vsehe.\fDiese ORDEN bergen\nerstaunliche Ge-\vheimnisse!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Besuch mich, wann\nimmer du magst.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Nun denn...\fWelchen der 8\nORDEN soll ich\verklären?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "POKéMON bis L50\ngehorchen dir.\fHöhere werden\naufsässig!\fAußerdem kannst du\nSTÄRKE außerhalb\vvon Kämpfen\vnutzen.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "Die VERTEIDIGUNG\naller POKéMON\vsteigt etwas.\fAußerdem kannst du\nSURFER außerhalb\vvon Kämpfen\vnutzen.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "Die INITIATIVE\naller POKéMON\vsteigt etwas.\fAußerdem kannst du\nFLIEGEN außerhalb\vvon Kämpfen\vnutzen.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Die SPEZIAL-Werte\ndeiner POKéMON\vsteigen etwas.",
  ["_CeruleanCityBikeShopSign"] = "Durch Gras und\nHöhlen ohne Mühe!\vFAHRRADLADEN",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "LAHMUS, schlag zu!\nNein! Wieder\vdanebengehauen!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "OK, LAHMUS!\nULTRASCHALL!\vKomm, LAHMUS,\vpass doch auf!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "LAHMUS, PANZER-\nSCHUTZ! Nein!\vFalsch!\fPOKéMON sind so\nschwer zu lenken!\fDer Gehorsam dei-\nner POKéMON hängt\vvon deinem Können\vals TRAINER ab!",
  ["_CeruleanCityCooltrainerF2Text"] = "Ich will ein\nknallrotes RAD!\fEs bleibt daheim,\ndamit es nicht\vschmutzig wird!",
  ["_CeruleanCityCooltrainerMText"] = "Auch TRAINER?\nSammeln, kämpfen -\vein hartes Leben.",
  ["_CeruleanCityGuardText"] = "Die Leute hier\nwurden beraubt.\fSicher steckt TEAM\nROCKET hinter\vdieser üblen Tat!\fSelbst die POLIZEI\nhat Mühe mit den\vROCKETs!",
  ["_CeruleanCityGymSign"] = "AZURIA CITY\nPOKéMON-ARENA\vLEITERIN: MISTY\fDie freche\nMeerjungfrau!",
  ["_CeruleanCityRivalDefeatedText"] = "He!\nGanz ruhig!\vDu hast gewonnen!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: He,\nrate mal!\fIch war bei BILL\nund er zeigte mir\vseine seltenen\vPOKéMON!\fDas hat meinen\nPOKéDEX ordent-\vlich gefüllt!\fBILL ist als POKé-\nMANIAC weltweit\vbekannt!\fEr erfand das\nPOKéMON-Lager-\vsystem am PC!\fDu nutzt sein\nSystem, also dank\vihm mal!\fIch mach mich\nwieder auf!\vBis später!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Yo!\n{PLAYER}!\fDu krebst immer\nnoch hier herum?\fMir geht's prima!\nIch habe viele\vstarke und clevere\vPOKéMON gefangen!\fZeig mal, was du\ngefangen hast,\v{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh! Gegen mein\nGenie hast du\vkeine Chance!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\fIch mache mich\nbesser davon!\vTschüss!",
  ["_CeruleanCityRocketIGiveUpText"] = "Halt!\nIch gebe auf! Ich\vgehe freiwillig!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Ich gebe die\ngeklaute TM\vzurück!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} erhält\nTM28 zurück!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Mach Platz dafür!\fIch kann erst weg,\nwenn du sie hast!",
  ["_CeruleanCityRocketText"] = "He! Bleib draußen!\nDas ist nicht dein\vGarten! Häh? Ich?\fIch bin nur ein\nunschuldiger Pas-\vsant! Glaubst du\vmir etwa nicht?",
  ["_CeruleanCitySignText"] = "AZURIA CITY\nEine mysteriöse,\vblaue Aura umgibt\vdie Stadt",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "LAHMUS ignoriert\ndie Befehle...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "LAHMUS gammelt\nnur herum...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "LAHMUS macht ein\nNickerchen...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "LAHMUS schaut\nweg...",
  ["_CeruleanCitySuperNerd1Text"] = "Der Busch vor dem\nLaden ist im Weg.\fVielleicht gibt es\neinen Weg drum-\vherum.",
  ["_CeruleanCitySuperNerd2Text"] = "Du erstellst ein\nPOKéMON-Lexikon?\fDas klingt\namüsant.",
  ["_CeruleanCitySuperNerd3Text"] = "Dies ist die\nAZURIA-HÖHLE!\fDort leben\nschrecklich starke\vPOKéMON!\fNur der Champ der\nPOKéMON-LIGA darf\vhinein!",
  ["_CeruleanCityTrainerTipsText"] = "TRAINER-TIPPS\fDrücke B während\nder Entwicklung,\vum sie ganz\vabzubrechen.",
  ["_CeruleanGymAfterBattleText1"] = "Nur im Kampf gegen\nandere TRAINER\vsiehst du, wie gut\vdu wirklich bist.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY wird immer\nbesser!\fSie verliert nicht\ngegen jemanden wie\vdich!",
  ["_CeruleanGymBattleText1"] = "Ich bin gut genug\nfür dich!\fMISTY kann warten!",
  ["_CeruleanGymBattleText2"] = "Platsch!\fIch bin zuerst\ndran! Los geht's!",
  ["_CeruleanGymEndBattleText1"] = "Du hast mich\nüberwältigt!",
  ["_CeruleanGymEndBattleText2"] = "Das kann\nnicht sein!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Du hast MISTY be-\nsiegt! Was habe\vich gesagt?\fDu und ich, wir\nsind ein verdammt\vgutes Team!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Yo! Champ in spe!\fHier mein Tipp!\fMISTY ist ein\nProfi für Wasser-\vPOKéMON!\fPflanzen-POKéMON\nsaugen ihnen das\vWasser ab!\fOder brutzle sie\nmit Elektro-\vAttacken!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "Mit dem QUELLORDEN\ngehorchen POKéMON\vbis L30!\fSogar die von\nanderen TRAINERN!\fUnd du kannst nun\njederzeit ZER-\vSCHNEIDER nutzen!\fDamit fällst du\nkleine Büsche und\vöffnest neue Wege!\fNimm auch meine\nLieblings-TM!",
  ["_CeruleanGymMistyPreBattleText"] = "Hi, ein neues\nGesicht!\fWer Profi werden\nwill, braucht eine\vPOKéMON-Strategie!\fWie gehst du beim\nFangen von POKéMON\vvor?\fMeine Taktik ist\nder Vollangriff\vmit Wasser-\vPOKéMON!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Wow!\nDu bist zu stark!\fNa gut!\fDu bekommst den\nQUELLORDEN als\vBeweis deines\vSieges!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} erhält\nTM11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "TM11 enthält\nBLUBBSTRAHL!\fBring sie einem\nWasser-POKéMON\vbei!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Mach lieber Platz\ndafür!",
  ["_CeruleanMartCooltrainerFText"] = "Kennst du SONDER-\nBONBONS?\fSie sollen POKéMON\num einen Level\vsteigen lassen!",
  ["_CeruleanMartCooltrainerMText"] = "SCHABAB hält Käfer\nund schwache\vPOKéMON fern.\fSetz dein stärks-\ntes POKéMON an die\vSpitze der Liste!",
  ["_CeruleanPokecenterGentlemanText"] = "Kennst du BILL?\fAlle nennen ihn\neinen POKéMANIAC!\fIch glaube, die\nLeute sind nur\vneidisch auf ihn.\fWer prahlt nicht\ngern mit seinen\vPOKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL hat viele\nPOKéMON!\fEr sammelt auch\nseltene!",
  ["_CeruleanPokecenterSuperNerdText"] = "Dieser BILL!\fEr tut angeblich\nalles für seltene\vPOKéMON!",
  ["_CeruleanTradeHouseGrannyText"] = "Mein Mann tauscht\ngern POKéMON.\fBist du Sammler,\ntausch doch bitte\vmit ihm!",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Diese elenden\nROCKETs!\fSchau, was sie an-\ngerichtet haben!\fSie stahlen eine\nTM, die POKéMON\vSCHAUFLER lehrt!\fDie hat mich ein\nVermögen gekostet!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Was weg ist, ist\nweg!\fIch bringe DIGDA\ndas Graben nun\vohne TM bei!",
  ["_CeruleanTrashedHouseGirlText"] = "TEAM ROCKET führt\nmit dem Graben\vsicher nichts\vGutes im Schilde!",
  ["_CeruleanTrashedHouseWallHoleText"] = "TEAM ROCKET ließ\neinen Ausgang\vzurück!",
  ["_ChampionsRoomOakComeWithMeText"] = "EICH: {PLAYER}!\fDu weisst, dass\ndein Sieg nicht\vallein dein Ver-\vdienst war!\fDas Band zwischen\ndir und deinen\vPOKéMON ist wun-\vderbar!\f{PLAYER}!\nKomm mit mir!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "EICH: Du hast ge-\nwonnen! Glück-\vwunsch!\fDu bist der neue\nChamp der POKéMON-\vLIGA!\fDu bist so ge-\nwachsen, seit du\vmit {RAM:wNameBuffer}\vlosgezogen bist!\f{PLAYER}, du bist\nnun erwachsen!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "EICH: {RIVAL}! Ich\nbin enttäuscht!\fIch kam, als ich\nhörte, dass du die\vTOP VIER besiegt\vhast!\fDoch als ich an-\nkam, hattest du\vschon verloren!\f{RIVAL}! Weisst du,\nwarum du verloren\vhast?\fDu hast vergessen,\ndeine POKéMON mit\vLiebe und Ver-\vtrauen zu behan-\vdeln!\fOhne das wirst du\nnie wieder Champ!",
  ["_ChampionsRoomOakText"] = "EICH: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Warum?\nWarum verlor ich?\fIch machte doch\nnie Fehler beim\vTraining...\fVerflixt! Du bist\nder neue Champ der\vPOKéMON-LIGA!\fAuch wenn ich es\nungern zugebe.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: He!\fIch habe mich auf\ndich gefreut,\v{PLAYER}!\fMein Rivale muss\nstark sein, damit\vich fit bleibe!\fFür den POKéDEX\nsuchte ich überall\vstarke POKéMON!\fIch stellte Teams\nzusammen, die je-\vden POKéMON-Typ\vschlagen!\fUnd jetzt!\fIch bin der Champ\nder POKéMON-LIGA!\f{PLAYER}! Weisst du,\nwas das heisst?\fIch sage es dir!\fIch bin der bes-\nte TRAINER der\vWelt!",
  ["_ChanseyDexEntry"] = "Ein seltenes,\nscheues POKéMON.\nEs soll dem Glück\fbringen, der es\nfangen kann",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Speit Feuer, heiß\ngenug, um Felsen\nzu schmelzen.\fLöst manchmal un-\ngewollt Wald-\nbrände aus",
  ["_CharmanderDexEntry"] = "Bevorzugt heiße\nOrte. Bei Regen\nsoll Dampf aus\fseiner Schwanz-\nspitze auf-\nsteigen",
  ["_CharmeleonDexEntry"] = "Schwingt seinen\nFeuerschweif und\ntreibt so die\fTemperatur uner-\nträglich in die\nHöhe",
  ["_ChooseABoxText"] = "Wähle eine\nPOKéMON-BOX.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FEUERSTURM ist die\nultimative Feuer-\vattacke!\fVergeude sie nicht\nan Wasser-POKéMON!",
  ["_CinnabarGymBlainePreBattleText"] = "Hah!\fIch bin PYRO, der\nLEITER der ZINNO-\vBER-ARENA!\fMeine Feuer-POKé-\nMON äschern alle\vHerausforderer\vein!\fHah! Hast du\nFEUERHEILER dabei?",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Ich bin ausge-\nbrannt!\fDu hast den VUL-\nKANORDEN verdient!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\fTM38 enthält\nFEUERSTURM!\fBring sie Feuer-\nPOKéMON bei!\fGLUTEXO oder\nPONITA wären gute\vKandidaten!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Mach Platz für\nmein Geschenk!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Hah!\fDer VULKANORDEN\nsteigert die SPE-\vZIAL-Werte deiner\vPOKéMON!\fHier, das kannst\ndu auch haben!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Du hast\nden Feuerkopf\vbesiegt!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Yo! Champ in spe!\fDer hitzige PYRO\nist ein Profi für\vFeuer-POKéMON!\fDämpfe ihn mit\nWasser!\fNimm besser ein\npaar FEUERHEILER\vmit!",
  ["_CinnabarGymQuizCorrectText"] = "Absolut richtig!\fDu darfst weiter!",
  ["_CinnabarGymQuizIncorrectText"] = "Sorry! Falsche\nAntwort!",
  ["_CinnabarGymQuizIntroText"] = "POKéMON-Quiz!\fBei richtiger Ant-\nwort öffnet sich\vdie Tür zum nächs-\vten Raum!\fBei falscher war-\ntet ein TRAINER!\fWillst du deine\nPOKéMON für den\vARENALEITER scho-\vnen...\fDann antworte\nrichtig! Los!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Feuer, genauer\ngesagt Verbren-\vnung...\fBla, bla, bla,\nbla...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Weisst du, wie heiß\nPOKéMON-Feueratem\vwerden kann?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Autsch!\nHeiß, heiß, heiß!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Ich kann es nicht\nlassen, fremde\vPOKéMON zu klauen!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ich war ein Dieb,\naber als TRAINER\vwurde ich ehrlich!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Ich\ngebe auf!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Meine Theorien\nsind dir zu kom-\vpliziert!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Du kannst nicht\ngewinnen! Ich habe\vPOKéMON studiert!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Wääh!\nMeine Studien!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Gäbe es doch ein\nDieb-POKéMON!\vDas würde ich\vnehmen!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Ich mag einfach\nFeuer-POKéMON!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Zu heiß\nfür mich!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "PYRO hatte sich in\nden Bergen ver-\virrt, als ein\vVogel aus Feuer\verschien.\fSein Licht führte\nPYRO sicher ins\vTal!",
  ["_CinnabarGymSuperNerd5BattleText"] = "Ich weiß, warum\nPYRO TRAINER\vwurde!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Aua!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "Wir Feuer-Fans\nlieben PONITA und\vVULNONA!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Ich war in vielen\nARENEN, aber diese\vist die beste!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Uff!\nZu heiß!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "Wasser schlägt\nFeuer! Aber Feuer\vschmilzt Eis-\vPOKéMON!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Feuer ist schwach\ngegen H2O!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Oh!\nAusgelöscht!",
  ["_CinnabarIslandDoorIsLockedText"] = "Die Tür ist\nverschlossen...",
  ["_CinnabarIslandGamblerText"] = "Forscher machen\nExperimente im\vausgebrannten\vGebäude.",
  ["_CinnabarIslandGirlText"] = "PYRO, der ARENA-\nLEITER, ist ein\vKauz, der seit\vJahrzehnten hier\vlebt.",
  ["_CinnabarIslandGymSignText"] = "ZINNOBERINSEL\nPOKéMON-ARENA\vLEITER: PYRO\fDer hitzköpfige\nQuizmaster!",
  ["_CinnabarIslandPokemonLabSignText"] = "POKéMON-LABOR",
  ["_CinnabarIslandSignText"] = "ZINNOBERINSEL\nFeurige Stadt der\vbrennenden Wünsche",
  ["_CinnabarLabFishingGuruText"] = "Wir erforschen\nhier POKéMON.\fOft bringt man uns\nseltene POKéMON\vzur Untersuchung.",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "Aiyah! Du kommen\nwieder!",
