  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "Ich brauchen etwas\nZeit!\fDu gehen solange\nspazieren!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "Ich brauchen etwas\nZeit!\fDu gehen solange\nspazieren!",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "Nein! Ist schade!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Das ist\n{RAM:wNameBuffer}!\fIst Fossil von\n{RAM:wStringBuffer}, ein\vPOKéMON, das schon\vausgestorben ist!\fMeine Maschine\nmacht es wieder\vlebendig!",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "So! Du schnell\ngeben mir das!\f{PLAYER} übergibt\n{RAM:wNameBuffer}!",
