  ["_CinnabarLabMeetingRoomSignText"] = "POKéMON-LABOR\nKonferenzraum",
  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "Ein bernstein-\nfarbenes Rohr!",
  ["_CinnabarLabMetronomeRoomPCText"] = "Eine E-Mail-Nach-\nricht!\f...\fDie 3 legendären\nVogel-POKéMON:\vARKTOS, ZAPDOS\vund LAVADOS.\fIhr Aufenthaltsort\nist unbekannt.\fWir erkunden bald\ndie Höhle nahe\vAZURIA.\fVon: POKéMON-\nFORSCHERTEAM\f...",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tick-tick-tick!\nDas ist ein METRO-\vNOM!\fEs bringt POKéMON\ndazu, unbekannte\vAttacken zu\vnutzen!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Dein Beutel ist\nzum Bersten voll!",
