  ["_FuchsiaCitySlowpokeSignText"] = "Name: FLEGMON\fFreundlich und\nsehr langsam.",
  ["_FuchsiaCityVoltorbSignText"] = "Name: VOLTOBAL\fSieht aus wie ein\nPOKéBALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "SAFARI-ZONE\nHAUS des AUFSEHERS",
  ["_FuchsiaCityYoungster1Text"] = "Warst du schon im\nSAFARI-SPIEL?\vManche POKéMON\vfängt man nur da.",
  ["_FuchsiaCityYoungster2Text"] = "Der Itemball da\ndrin ist in Wahr-\vheit ein POKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Hallo,\n{PLAYER}!\fBeißen die Fische\ngut an?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh nein!\fDu hast keinen\nPlatz für mein\vGeschenk!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Prima! Du gefällst\nmir!\fNimm dies und\nangle damit!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Ich bin der ältere\nBruder des ANGEL-\vGURUS!\fIch liiiebe das\nAngeln!\fAngelst du auch\ngerne?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Wie\nenttäuschend...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "Erstaunlich, dass\nNinja selbst heute\vnoch furchteinflö-\vßend sind!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Yo! Champion in\nspe!\fDie FUCHSANIA-\nARENA ist voller\vunsichtbarer\vWände!\fKOGA scheint nah,\ndoch der Weg ist\vversperrt!\fFinde die Lücken\nin den Wänden, um\vihn zu erreichen!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Fwahahaha!\fEin Kind wie du\nwagt es, mich\vherauszufordern?\fNun gut, ich zeige\ndir den wahren\vSchrecken eines\vNinja-Meisters!\fSpüre die Ver-\nzweiflung durch\vGift- und Schlaf-\vtechniken!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Durch TOXIN leiden\nPOKéMON im Kampf\vimmer mehr und\vmehr!\fEs wird deine\nGegner das Fürch-\vten lehren!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Humph!\nDu hast dich als\vwürdig erwiesen!\fHier! Nimm den\nSEELENORDEN!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Mit dem SEELEN-\nORDEN steigt die\vVERTEIDIGUNG\vdeiner POKéMON!\fAußerdem kannst du\nnun außerhalb des\vKampfes SURFER\vnutzen!\fAh! Nimm auch\nnoch dies!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\fTM06 enthält\nTOXIN!\fEine Geheimtech-\nnik, über 400\vJahre alt!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Mach Platz dafür,\nKind!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Du verbindest\nKraft mit Köpf-\vchen? Gute\vStrategie!",
  ["_FuchsiaGymRocker1BattleText"] = "Stärke ist nicht\nalles bei POKéMON!\fStrategie zählt!\fIch zeige dir, wie\nStrategie rohe\vKraft besiegt!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Was?\nAußergewöhnlich!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Ich trainiere\nweiter unter KOGA,\vmeinem Ninja-\vMeister!",
  ["_FuchsiaGymRocker2BattleText"] = "Ich wollte Ninja\nwerden, also trat\vich dieser ARENA\vbei!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Ich bin\nerledigt!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Ich mag Gift- und\nSchlaftechniken,\vsie wirken lange\vnach!",
  ["_FuchsiaGymRocker3BattleText"] = "Besiege erst mal\nmeine Spezial-\vtechniken!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Du hast\nmich reingelegt!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Beeindruckend!\nHier ein Tip!\fSuche genau nach\nLücken in den un-\vsichtbaren Wänden!",
  ["_FuchsiaGymRocker4BattleText"] = "Stopp, halt!\fFrustrieren dich\nunsere unsicht-\vbaren Wände?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Wow!\nEr hat's drauf!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "Ich muss noch viel\nlernen!",
  ["_FuchsiaGymRocker5BattleText"] = "Auch ich lerne den\nWeg des Ninja bei\vMeister KOGA!\fNinja nutzen seit\njeher Tiere!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Auuu!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Wo Licht ist, da\nist auch Schatten!\fLicht und Schat-\nten! Was wählst\vdu?",
  ["_FuchsiaGymRocker6BattleText"] = "Meister KOGA ent-\nstammt einer alten\vNinja-Familie!\fWo kommst du denn\nher?",
  ["_FuchsiaGymRocker6EndBattleText"] = "Ich ließ\ndie Bälle fallen!",
  ["_FuchsiaMartCooltrainerFText"] = "Kennst du X-TEMPO?\nEs macht POKéMON\vim Kampf\vschneller!",
  ["_FuchsiaMartMiddleAgedManText"] = "Hast du eine\nSAFARI-ZONEN-\vFlagge?\fOder Karten und\nKalender?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Wir nennen den\nAUFSEHER FLEGMON.\fEr und FLEGMON\ngucken beide so\vabwesend!",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "FLEGMON weiß sehr\nviel über POKéMON!\fEr hat sogar Fos-\nsilien seltener,\vausgestorbener\vPOKéMON!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "FLEGMON kam vor-\nbei, aber ich ver-\vstand ihn nicht.\fEr hat wohl ein\nSprachproblem!",
  ["_FuchsiaPokecenterCooltrainerFText"] = "Westlich von VER-\nTANIA CITY ist ein\vschmaler Pfad.\fEr führt zum Sitz\nder POKéMON-LIGA.\vSie verwaltet\valle TRAINER.",
  ["_FuchsiaPokecenterRockerText"] = "Mit nur einem\nstarken POKéMON\vgewinnst du nicht.\fEs ist mühsam,\ndoch trainiere\valle gleichmäßig.",
  ["_FullHealText"] = "{RAM:wNameBuffer}\nist wieder gesund!",
  ["_FullyParalyzedText"] = "{USER}\nist paralysiert!",
  ["_GainedText"] = "{RAM:wNameBuffer} erhält\n",
  ["_GameCornerBeauty1Text"] = "Willkommen!\fNebenan kannst du\ndeine Münzen ge-\vgen tolle Preise\vtauschen.",
  ["_GameCornerBeauty2Text"] = "Ich glaube, die\nAutomaten haben\vverschiedene\vGewinnchancen.",
  ["_GameCornerClerk1CantAffordTheCoinsText"] = "Du kannst dir die\nMünzen nicht\vleisten!",
  ["_GameCornerClerk1CoinCaseIsFullText"] = "Ups! Dein\nMÜNZKORB ist voll.",
  ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "Willkommen in der\nROCKET-SPIELHALLE!\fBrauchst du\nSpielmünzen?\f50 Münzen für\n¥1000. Möchtest\vdu welche?",
  ["_GameCornerClerk1DontHaveCoinCaseText"] = "Du hast keinen\nMÜNZKORB!",
  ["_GameCornerClerk1PleaseComePlaySometimeText"] = "Nein? Komm doch\nmal zum Spielen!",
  ["_GameCornerClerk1ThanksHereAre50CoinsText"] = "Danke! Hier sind\ndeine 50 Münzen!",
  ["_GameCornerClerk2INeedMoreCoinsText"] = "Mist! Ich brauche\nmehr Münzen für\vmein Wunsch-\vPOKéMON!",
  ["_GameCornerClerk2Received20CoinsText"] = "{PLAYER} erhält\n20 Münzen!",
  ["_GameCornerClerk2WantSomeCoinsText"] = "Was gibt's?\nWillst du Münzen?",
  ["_GameCornerClerk2YouHaveLotsOfCoinsText"] = "Du hast doch\nviele Münzen!",
  ["_GameCornerCoinCaseText"] = "Du brauchst einen\nMÜNZKORB!",
  ["_GameCornerFishingGuruDontNeedMyCoinsText"] = "Du brauchst meine\nMünzen nicht!",
  ["_GameCornerFishingGuruReceived10CoinsText"] = "{PLAYER} erhält\n10 Münzen!",
  ["_GameCornerFishingGuruWantToPlayText"] = "Na, Kind, willst\ndu spielen?",
  ["_GameCornerFishingGuruWinsComeAndGoText"] = "Glück kommt\nund geht.",
  ["_GameCornerGamblerText"] = "Spielen ist ris-\nkant! Man wird so\vleicht süchtig!",
  ["_GameCornerGentlemanCloselyWatchTheReelsText"] = "Der Trick ist, die\nWalzen genau zu\vbeobachten!",
  ["_GameCornerGentlemanReceived20CoinsText"] = "{PLAYER} erhält\n20 Münzen!",
  ["_GameCornerGentlemanThrowingMeOffText"] = "He, was? Du\nbringst mich raus!\vHier, ein paar\vMünzen, schieb ab!",
  ["_GameCornerGentlemanYouGotYourOwnCoinsText"] = "Du hast doch\neigene Münzen!",
  ["_GameCornerGymGuideChampInMakingText"] = "He!\fDu hast Besseres\nzu tun, Champion\vin spe!\fERIKA leitet die\nPRISMANIA-ARENA!\vSie setzt Pflan-\vzen-POKéMON ein!\fSie wirkt sanft,\ndoch laß dich\vnicht täuschen!",
  ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "Hier gibt es sel-\ntene POKéMON im\vTausch gegen\vMünzen.\fAber ich gewinne\neinfach nie!",
  ["_GameCornerMiddleAgedMan1Text"] = "Behalt das für\ndich.\fMan munkelt, TEAM\nROCKET betreibe\vdiesen Laden.",
  ["_GameCornerMiddleAgedWomanText"] = "Ich amüsiere mich\nprächtig!",
  ["_GameCornerNoCoinsText"] = "Du hast keine\nMünzen!",
  ["_GameCornerOopsForgotCoinCaseText"] = "Ups! MÜNZKORB\nvergessen!",
  ["_GameCornerOutOfOrderText"] = "AUSSER BETRIEB\nKaputt.",
  ["_GameCornerOutToLunchText"] = "MITTAGSPAUSE\nReserviert.",
  ["_GameCornerPosterSwitchBehindPosterText"] = "He!\fEin Schalter hin-\nterm Poster!?\vDrücken wir ihn!",
  ["_GameCornerPrizeRoomBaldingGuyText"] = "Dieses PORYGON\nhätte ich gerne!\fAber am Automaten\ngewinnt man kaum!",
  ["_GameCornerPrizeRoomGamblerText"] = "Heute habe ich\nrichtig abgeräumt!",
  ["_GameCornerRocketAfterBattleText"] = "Unser Versteck\nfliegt noch auf!\vIch muss es dem\vBOSS melden!",
  ["_GameCornerRocketBattleEndText"] = "Verflixt!",
  ["_GameCornerRocketImGuardingThisPosterText"] = "Ich bewache dieses\nPoster!\vVerschwinde, sonst\vknallt's!",
  ["_GameCornerSomeonesKeysText"] = "Schlüssel! Der Be-\nsitzer kommt wohl\vzurück.",
  ["_GameOverText"] = "ANSAGE: Dein\nSAFARI-SPIEL ist\vvorbei!",
  ["_GameSavedText"] = "{PLAYER} hat das\nSpiel gespeichert!",
  ["_GastlyDexEntry"] = "Fast unsichtbar.\nDieses gasförmige\nPOKéMON hüllt\fOpfer ein und\nschläfert sie un-\nbemerkt ein",
  ["_GengarDexEntry"] = "Bei Vollmond ahmt\nes gern die Schat-\nten von Menschen\fnach und lacht\nüber deren\nSchrecken",
  ["_GeodudeDexEntry"] = "Lebt auf Feldern\nund in Bergen.\nMan hält es oft\ffür einen Felsen\nund stolpert\ndarüber",
  ["_GetDexRatedText"] = "Soll ich deinen\nPOKéDEX bewerten?",
  ["_GetOutText"] = "GEIST: Geh weg...\nGeh weg...",
  ["_GetmText"] = "Fang ihn! ",
  ["_GettingPumpedText"] = "{USER}\npumpt sich auf!",
  ["_GhostCantBeIDdText"] = "Mist! Der GEIST\nist nicht zu iden-\vtifizieren!",
  ["_GloomDexEntry"] = "Die Flüssigkeit\naus seinem Maul\nist kein Speichel,\fsondern Nektar,\nder Beute\nanlockt",
  ["_GoText"] = "Los! ",
  ["_GolbatDexEntry"] = "Hat es zugebissen,\nsaugt es Energie,\nbis es selbst zu\fschwer zum\nFliegen\nist",
  ["_GoldeenDexEntry"] = "Seine Schwanzflos-\nse wogt wie ein\nBallkleid. Daher\fnennt man es auch\ndie Königin des\nWassers",
  ["_GolduckDexEntry"] = "Schwimmt oft ele-\ngant an Seeufern.\nEs wird oft mit\fdem japanischen\nMonster Kappa\nverwechselt",
  ["_GolemDexEntry"] = "Sein Felsenkörper\nist extrem hart.\nEr übersteht\fmühelos Dynamit-\nExplosionen ohne\nSchaden",
  ["_GoodText"] = "gut!",
  ["_GotAwayText"] = "Gut entkommen!",
  ["_GotMapText"] = "{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_GotMonText"] = "{PLAYER} erhält\n{RAM:wNameBuffer}!",
  ["_GotOffBicycleText1"] = "{PLAYER} stieg vom",
  ["_GotOffBicycleText2"] = "{RAM:wStringBuffer} ab.",
  ["_GotOnBicycleText1"] = "{PLAYER} stieg aufs",
  ["_GotOnBicycleText2"] = "{RAM:wStringBuffer}!",
  ["_GravelerDexEntry"] = "Rollt Hänge hinab.\nEs überrollt jedes\nHindernis, ohne\fzu bremsen oder\ndie Richtung zu\nändern",
  ["_GreatlyFellText"] = "{SCROLL}stark",
  ["_GreatlyRoseText"] = "{SCROLL}stark",
  ["_GrewLevelText"] = "{RAM:wNameBuffer} erreicht\nLevel {NUM:wCurEnemyLevel, 1, 3}!",
  ["_GrimerDexEntry"] = "Lebt an dreckigen\nOrten. Ernährt\nsich von ver-\fseuchtem Schlamm\naus\nFabriken",
  ["_GroundRoseText"] = "Irgendwo hob sich\nder Boden!",
  ["_GrowlitheDexEntry"] = "Verteidigt sein\nRevier. Es bellt\nund beisst, um\fEindringlinge zu\nvertreiben",
  ["_GyaradosDexEntry"] = "In freier Wildbahn\nselten. Riesig und\nbösartig, kann es\fim Zorn ganze\nStädte\nzerstören",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\nPOKéMON-ARENA\vLEITER: {RAM:wGymLeaderName}\fSIEGREICHE\nTRAINER: {RIVAL}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\nPOKéMON-ARENA\vLEITER: {RAM:wGymLeaderName}\fSIEGREICHE\nTRAINER: {RIVAL}\v{PLAYER}",
  ["_HMCantDeleteText"] = "VM-Techniken kann\nman nicht löschen!",
  ["_HallOfFameOakText"] = "EICH: Ähem!\nGratuliere,\v{PLAYER}!\fDies ist die\nPOKéMON-RUHMES-\vHALLE!\fHier werden die\nChampions der\vPOKéMON-LIGA\vgeehrt!\fIhre POKéMON wer-\nden ebenfalls hier\vverewigt!\f{PLAYER}! Du hast\nhart gekämpft, um\vneuer Champion der\vLIGA zu werden!\fGlückwunsch,\n{PLAYER}! Du und\vdeine POKéMON seid\vnun in der RUHMES-\vHALLE!",
  ["_HasSubstituteText"] = "{USER}\nhat einen DELE-\vGATOR!",
  ["_HaunterDexEntry"] = "Da es durch Wände\ngleiten kann, sagt\nman, es stamme\faus einer anderen\nDimension",
  ["_HereYouGoText"] = "Bitte sehr!",
  ["_HiddenItemBagFullText"] = "Aber {PLAYER} hat\nkeinen Platz mehr\vfür andere Items!",
  ["_HisNameIsText"] = "Richtig! Jetzt\nfällt's mir ein!\vEr heisst {RIVAL}!",
  ["_HitWithRecoilText"] = "{USER}\nerleidet Rückstoß!",
  ["_HitXTimesText"] = "{NUM:wEnemyNumHits, 1, 1} Treffer!",
  ["_HitmonchanDexEntry"] = "Es scheint still-\nzustehen und feu-\nert doch blitz-\fschnelle Schläge\nab, unsichtbar\nfürs Auge",
  ["_HitmonleeDexEntry"] = "In Eile werden\nseine Beine immer\nlänger. Es läuft\fgeschmeidig mit\nextra langen\nSchritten",
  ["_HookedMonAttackedText"] = "Das angebissene\n{RAM:wEnemyMonNick}\vgreift an!",
  ["_HorseaDexEntry"] = "Schießt fliegende\nInsekten mit ge-\nzielten Tinten-\fstrahlen von der\nWasseroberfläche\nab",
  ["_HurtByBurnText"] = "{USER}\nleidet an der Ver-\vbrennung!",
  ["_HurtByLeechSeedText"] = "EGELSAMEN saugt\nan {USER}!",
  ["_HurtByPoisonText"] = "{USER}\nleidet am Gift!",
  ["_HurtItselfText"] = "Es verletzte sich\nvor Verwirrung\vselbst!",
  ["_HypnoDexEntry"] = "Beim Blickkontakt\nsetzt es PSI-At-\ntacken wie HYPNO-\fSE und KONFUSION\nein",
  ["_IceHealText"] = "{RAM:wNameBuffer} wurde\naufgetaut!",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick}\nmißachtet Befehle!",
  ["_IndigoPlateauHQText"] = "INDIGO PLATEAU\nPOKéMON-LIGA-SITZ",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "Ab hier trittst du\nnacheinander gegen\vdie TOP VIER an!\fBei einem Sieg\nöffnet sich die\vTür zum nächsten\vTRAINER!\vViel Glück!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Yo! Champion in\nspe!\fIn der POKéMON-\nLIGA musst du die\vTOP VIER nachein-\vander besiegen.\fVerlierst du, musst\ndu ganz von vorne\vanfangen! Jetzt\vgilt's! Pack es!",
  ["_IndigoPlateauStatuesText1"] = "INDIGO PLATEAU",
  ["_IndigoPlateauStatuesText2"] = "Das höchste Ziel\naller TRAINER!\vPOKéMON-LIGA-SITZ",
  ["_IndigoPlateauStatuesText3"] = "Die höchste\nPOKéMON-Instanz:\vPOKéMON-LIGA-SITZ",
  ["_IntoText"] = "\nsich zu {RAM:wNameBuffer}!",
  ["_IntroducePlayerText"] = "Zuerst, wie ist\ndein Name?",
  ["_IntroduceRivalText"] = "Das ist mein En-\nkel. Er ist schon\vimmer dein Riva-\vle gewesen.\f...Ähm, wie war\nnoch sein Name?",
  ["_IsConfusedText"] = "{USER}\nist verwirrt!",
  ["_IsEvolvingText"] = "Nanu? {RAM:wStringBuffer}\nentwickelt sich!",
  ["_IsFrozenText"] = "{USER}\nist eingefroren!",
  ["_IsItOKToTossItemText"] = "{RAM:wStringBuffer} wirklich\nwegwerfen?",
  ["_IsUnaffectedText"] = "{TARGET}\nbleibt unberührt!",
  ["_ItemUseBallText00"] = "Es wich dem BALL\naus!\fDieses POKéMON\nkann nicht gefan-\vgen werden!",
  ["_ItemUseBallText01"] = "Das POKéMON\nverfehlt!",
  ["_ItemUseBallText02"] = "Mist! Das POKéMON\nhat sich befreit!",
  ["_ItemUseBallText03"] = "Ohh! Es schien\nschon gefangen! ",
  ["_ItemUseBallText04"] = "Schade! Das war\nso knapp!",
  ["_ItemUseBallText05"] = "Prima!\n{RAM:wEnemyMonNick} wurde\vgefangen!",
  ["_ItemUseBallText06"] = "Neue POKéDEX-\nDaten zu\v{RAM:wEnemyMonNick}!",
  ["_ItemUseBallText07"] = "{RAM:wBoxMonNicks} wurde\nan BILLs PC\vübertragen!",
  ["_ItemUseBallText08"] = "{RAM:wBoxMonNicks} wurde\nan jemandes PC\vübertragen!",
  ["_ItemUseNoEffectText"] = "Es wird keine\nWirkung haben.",
  ["_ItemUseNotTimeText"] = "EICH: {PLAYER}!\nJetzt ist nicht\vder richtige Zeit-\vpunkt dafür! ",
  ["_ItemUseNotYoursToUseText"] = "Das gehört dir\nnicht!",
  ["_ItemUseText001"] = "{PLAYER} benutzt",
  ["_ItemUseText002"] = "{RAM:wStringBuffer}!",
  ["_ItemWasStoredText"] = "{RAM:wNameBuffer} wurde\nim PC gelagert.",
  ["_ItemfinderFoundItemText"] = "Ja! Der ITEM-\nSUCHER zeigt ein\vItem in der Nähe\van!",
  ["_ItemfinderFoundNothingText"] = "Nein! Der ITEM-\nSUCHER reagiert\vnicht.",
  ["_ItemsCantBeUsedHereText"] = "Items können hier\nnicht benutzt\vwerden.",
  ["_ItsABiteText"] = "Oh!\nEr beisst an!",
  ["_IvysaurDexEntry"] = "Wächst die Knolle\nauf dem Rücken,\nkann es wohl nicht\fmehr auf den Hin-\nterbeinen\nstehen",
  ["_JigglypuffDexEntry"] = "Leuchten seine\ngroßen Augen,\nsingt es ein ge-\fheimnisvolles\nLied, das Gegner\neinschläfert",
  ["_JolteonDexEntry"] = "Sammelt negative\nIonen aus der\nLuft, um Blitze\fmit 10000 Volt\nzu\nverschießen",
  ["_JustAMomentText"] = "Einen Moment.",
  ["_JynxDexEntry"] = "Wiegt beim Gehen\nverführerisch die\nHüften. Es bringt\fMenschen dazu,\nim Takt mit ihm zu\ntanzen",
  ["_KabutoDexEntry"] = "Ein POKéMON, das\naus einem Fossil\nvom einstigen\fMeeresgrund er-\nweckt\nwurde",
  ["_KabutopsDexEntry"] = "Seine glatte Form\nist ideal zum\nSchwimmen. Es\fschlitzt Beute auf\nund saugt sie\naus",
  ["_KabutopsFossilText"] = "KABUTOPS-Fossil\nEin urzeitliches,\vseltenes POKéMON.",
  ["_KadabraDexEntry"] = "Sendet spezielle\nAlphawellen aus,\ndie schon in der\fNähe Kopfschmer-\nzen\nverursachen",
  ["_KakunaDexEntry"] = "Kann sich kaum\nbewegen. Es här-\ntet nur seine\fSchale, um sich\nvor Feinden zu\nschützen",
  ["_KangaskhanDexEntry"] = "Das Junge verlässt\nden schützenden\nBeutel der Mutter\fkaum, bis es 3\nJahre alt\nist",
  ["_KeptGoingAndCrashedText"] = "{USER}\nlief weiter und\vstürzte!",
  ["_KinglerDexEntry"] = "Die große Schere\nhat 10000 PS an\nKraft, ist aber\fdurch ihre Größe\nschwer zu\nhandhaben",
  ["_KoffingDexEntry"] = "Es speichert vie-\nle Giftgase im\nKörper und neigt\fdazu, ohne Warnung\nzu\nexplodieren",
  ["_KrabbyDexEntry"] = "Die Scheren sind\nstarke Waffen und\ndienen der Balance\fbeim Seitwärts-\ngehen",
  ["_LancesRoomLanceAfterBattleText"] = "Unfaßbar, dass\nmeine Drachen ge-\vgen dich verloren\vhaben, {PLAYER}!\fDu bist jetzt der\nChampion der\vPOKéMON-LIGA!\f...Oder du wärst\nes, doch eine\vPrüfung wartet\vnoch auf dich.\fDu musst gegen\neinen weiteren\vTRAINER antreten!\vSein Name ist...\f{RIVAL}!\nEr schlug die TOP\vVIER vor dir!\fEr ist der wahre\nChampion der\vPOKéMON-LIGA!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Ich habe von\ndir gehört,\v{PLAYER}!\fIch führe die TOP\nVIER an! Nenn mich\vSIEGFRIED, den\vDrachen-TRAINER!\fDrachen sind\nmythische POKéMON!\fSie sind schwer zu\nfangen und aufzu-\vziehen, doch ihre\vKräfte sind über-\vlegen!\fSie sind nahezu\nunzerstörbar!\fNun, bist du be-\nreit zu verlieren?\fDeine LIGA-Heraus-\nforderung endet\vhier bei mir,\v{PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "Das war's!\fIch gestehe es un-\ngern, doch du bist\vein POKéMON-\vMeister!",
  ["_LaprasDexEntry"] = "Wurde fast bis zur\nAusrottung gejagt.\nEs kann Menschen\füber das Wasser\ntragen",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Der GEIST im\nPOKéMON-TURM ist\vfort!\fJemand muss seine\nruhelose Seele be-\vsänftigt haben!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Ich hasse diese\nfiesen ROCKETs!\fDie Mutter des ar-\nmen TRAGOSSO...\fSie starb auf der\nFlucht vor TEAM\vROCKET!",
  ["_LavenderCuboneHouseCuboneText"] = "TRAGOSSO: Kyarugu!",
  ["_LavenderMartBaldingGuyText"] = "Ich suche Items,\ndie POKéMON-Werte\vfür einen Kampf\verhöhen.\fX-ANGRIFF, X-AB-\nWEHR, X-TEMPO und\vX-SPEZIAL will\vich haben.\fWeisst du, wo es\nsie gibt?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Ich fand ein NUG-\nGET in den Bergen.\fIch hielt es für\nnutzlos, doch es\vbrachte ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Kennst du BELEBER?\nEr belebt besiegte\vPOKéMON wieder!",
  ["_LavenderPokecenterGentlemanText"] = "TEAM ROCKET tut\nalles für Gold!",
  ["_LavenderPokecenterGuyText"] = "TRAGOSSO trägt\neinen Schädel,\vnicht wahr?\fLeute zahlen viel\ndafür!",
  ["_LavenderPokecenterLittleGirlText"] = "Ich sah TRAGOSSOs\nMutter sterben,\vals sie vor TEAM\vROCKET floh!",
  ["_LavenderTownCooltrainerMText"] = "Diese Stadt ist\nals Grabstätte der\vPOKéMON bekannt.\fIm POKéMON-TURM\nwerden Trauer-\vfeiern abgehalten.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Glaubst du an\nGEISTER?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Hahaha, wohl\nnicht.\fDie weiße Hand auf\ndeiner Schulter\vist nicht echt.",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Wirklich? Es gibt\nalso Gläubige...",
  ["_LavenderTownPokemonHouseSignText"] = "Freiwilliges\nPOKéMON-HAUS\vLAVANDIA",
  ["_LavenderTownPokemonTowerSignText"] = "Mögen die Seelen\nder POKéMON ruhen\vPOKéMON-TURM",
  ["_LavenderTownSignText"] = "LAVANDIA\nDie edle Stadt\vin Violett",
  ["_LavenderTownSilphScopeSignText"] = "Neu: SILPH-SCOPE!\fMacht Unsichtbares\nsichtbar!\fSILPH CO.",
  ["_LavenderTownSuperNerdText"] = "Im POKéMON-TURM\nsind GEISTER er-\vschienen.\fWohl die Seelen\nder POKéMON, die\vdie ROCKETs töte-\vten.",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName} erlernt\n{RAM:wStringBuffer}!",
  ["_LickitungDexEntry"] = "Seine Zunge dehnt\nsich wie die eines\nChamäleons. Ihr\fLecken hinterlässt\nein Kribbeln",
  ["_LightScreenProtectedText"] = "{USER}\nist gegen Spezial-\vAngriffe ge-\vschützt!",
  ["_LinedUpText"] = " in Reihe!\nGewinn: {RAM:wStringBuffer} Münzen!",
  ["_LinkBattleLostText"] = "{PLAYER} verlor\ngegen {RAM:wTrainerName}!",
  ["_LinkCableHelpText1"] = "TRAINER-TIPS\fDas Link-Kabel\nbenutzen",
  ["_LinkCableHelpText2"] = "Welchen Abschnitt\nmöchtest du lesen?",
  ["_LinkCableInfoText1"] = "Hast du deinen\nGAME BOY mit einem\vanderen GAME BOY\vverbunden, sprich\vmit der Dame\vrechts in jedem\vPOKéMON-CENTER.",
  ["_LinkCableInfoText2"] = "Im KOLOSSEUM\nkämpfst du gegen\veinen Freund.",
  ["_LinkCableInfoText3"] = "Im TAUSCH-CENTER\nkannst du POKéMON\vtauschen.",
  ["_LinkCanceledText"] = "Die Verbindung\nwurde getrennt.",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\nfaulenzt lieber.",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Du bist besser als\ngedacht! Geh nur\vweiter!\fDas war nur ein\nVorgeschmack auf\vdie POKéMON-LIGA!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Willkommen bei\nder POKéMON-LIGA!\fIch bin LORELEI\nvon den TOP VIER!\fBei Eis-POKéMON\nmacht mir niemand\vetwas vor!\fEisattacken sind\nmächtig!\fEingefroren sind\ndeine POKéMON mir\vausgeliefert!\fHahaha!\nBist du bereit?",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Eine Stimme:\nLauf nicht weg!",
  ["_LoreleisRoomLoreleiEndBattleText"] = "Was fällt\ndir ein!",
  ["_LoweredItsHeadText"] = "\nsenkt den Kopf!",
  ["_MachampDexEntry"] = "Mit seinen star-\nken Muskeln wirft\nes Schläge, die\fOpfer bis zum\nHorizont schleu-\ndern können",
  ["_MachokeDexEntry"] = "Sein Muskelkörper\nist so stark, dass\nes einen Kraft-\fgürtel trägt, um\nseine Kräfte zu\nzügeln",
  ["_MachopDexEntry"] = "Stählt gerne seine\nMuskeln. Es trai-\nniert alle Kampf-\fkünste, um noch\nstärker zu\nwerden",
  ["_MadeWhirlwindText"] = "\nmacht Wirbelwind!",
  ["_MagazinesText"] = "POKéMON-Magazine!\fPOKéMON-Hefte!\fPOKéMON-Grafiken!",
  ["_MagikarpDexEntry"] = "In ferner Vergan-\ngenheit etwas\nstärker als seine\fjämmerlich schwa-\nchen Nachfahren\nvon heute",
  ["_MagmarDexEntry"] = "Sein Körper glüht\nstets orange. So\nkann es sich per-\ffekt in Flammen\nverstecken",
  ["_MagnemiteDexEntry"] = "Schwebt mit Anti-\nSchwerkraft. Er-\nscheint plötzlich\fund nutzt Attacken\nwie\nDONNERWELLE",
  ["_MagnetonDexEntry"] = "Besteht aus mehre-\nren verbundenen\nMAGNETILO. Er-\fscheint oft bei\nSonnenflecken-\nAktivität",
  ["_MankeyDexEntry"] = "Wird extrem\nschnell wütend.\nEben noch fried-\flich, tobt es im\nnächsten Moment\nwild umher",
  ["_MarowakDexEntry"] = "Der Knochen ist\nseine Hauptwaffe.\nEs wirft ihn ge-\fschickt wie einen\nBumerang auf\nGegner",
  ["_MartSignText"] = "Alles, was man an\nItems braucht!\vPOKéMON-MARKT",
  ["_MeowthDexEntry"] = "Liebt runde Ob-\njekte. Streift\nnachts durch\fStraßen und sucht\nnach verlorenem\nKleingeld",
  ["_MetapodDexEntry"] = "Solange die Scha-\nle weich ist, ist\nes verwundbar und\fsein zarter Körper\nungeschützt",
  ["_MewDexEntry"] = "So selten, dass\nviele Experten es\nfür ein Trugbild\fhalten. Nur wenige\nhaben es je\ngesehen",
  ["_MewtwoBattleText"] = "Mew!",
  ["_MewtwoDexEntry"] = "Wurde von einem\nForscher nach\nJahren grausamer\fGen- und DNS-\nExperimente\nerschaffen",
  ["_MimicLearnedMoveText"] = "{USER}\nerlernt\v{RAM:wNameBuffer}!",
  ["_MirrorMoveFailedText"] = "SPIEGELTRICK\nist gescheitert!",
  ["_MoltresDexEntry"] = "Der legendäre\nFeuervogel. Jeder\nFlügelschlag er-\fzeugt ein gleißen-\ndes Flammenmeer",
  ["_MonCannotLearnMachineMoveText"] = "{RAM:wNameBuffer} und\n{RAM:wStringBuffer} sind nicht\vkompatibel.\fEs kann {RAM:wStringBuffer}\nnicht erlernen.",
  ["_MonIsTakenOutText"] = "{RAM:wStringBuffer} wurde\nentnommen.\v{RAM:wStringBuffer} erhalten.",
  ["_MonWasReleasedText"] = "{RAM:wStringBuffer} wurde\nfreigelassen.\vMach's gut, {RAM:wStringBuffer}!",
  ["_MonWasStoredText"] = "{RAM:wStringBuffer} wurde in\nBox {RAM:wBoxNumString} abgelegt.",
  ["_MoneyForWinningText"] = "{PLAYER} erhält ¥{NUM:wAmountMoneyWon, 3 | LEADING_ZEROES | LEFT_ALIGN}\nfür den Sieg!",
  ["_MonsStatsFellText"] = "{TARGET}:\n{RAM:wStringBuffer}",
  ["_MonsStatsRoseText"] = "{USER}:\n{RAM:wStringBuffer}",
  ["_MoveDisabledText"] = "Die Attacke ist\nblockiert!",
  ["_MoveIsDisabledText"] = "{USER}:\n{RAM:wNameBuffer} ist\vblockiert!",
  ["_MoveNameText"] = "{RAM:wStringBuffer}!",
  ["_MoveNoPPText"] = "Keine AP mehr für\ndiese Attacke!",
  ["_MoveWasDisabledText"] = "{TARGET}:\n{RAM:wNameBuffer} wurde\vblockiert!",
  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "So warm! POKéMON\nknuddeln ist so\vschön!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Das ist wirklich\nMR.FUJIs Haus.\fEr ist so gütig!\fEr kümmert sich um\nverlassene und\vverwaiste POKéMON!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR.FUJI: Hat dir\nmeine FLÖTE\vgeholfen?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR.FUJI: {PLAYER}.\fOhne Liebe zu dei-\nnen POKéMON kann\vdie POKéDEX-Suche\vscheitern.\fDies mag dir auf\ndeiner Reise\vhelfen.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\fBeim Klang der\nPOKéFLÖTE erwa-\vchen schlafende\vPOKéMON sofort.\fSie wirkt bei al-\nlen schlafenden\vPOKéMON.",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Du musst dafür\nPlatz schaffen!",
  ["_MrFujisHouseMrFujiPokedexText"] = "POKéMON-Monats-\nheft: Große\vPreisziehung!\fDas Teilnahme-\nformular ist...\fWeg! Es wurde\nherausgetrennt!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_MrFujisHouseNidorinoText"] = "NIDORINO: Gaoo!",
  ["_MrFujisHousePsyduckText"] = "ENTON: Gwappa!",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "MR.FUJI betete\nallein für TRA-\vGOSSOs Mutter.",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Seltsam, MR.FUJI\nist nicht da.\vWo ist er nur?",
  ["_MrMimeDexEntry"] = "Wird es beim Pan-\ntomimespiel ge-\nstört, ohrfeigt es\fden Störer mit\nseinen breiten\nHänden",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "TM29 enthält\nPSYCHOKINESE!\fSie kann den SPE-\nZIAL-Wert des\vGegners senken.",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "Wo willst du das\ndenn hintun?",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Warte! Sag\nkein Wort!\fDu wolltest das\nhier!",
  ["_MtMoon1FBewareZubatSign"] = "Vorsicht! ZUBAT\nsaugt Blut!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Wie kommt man\nhier wieder raus?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Wow! Hier drin ist\nes viel größer,\vals ich dachte!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nVerloren!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Hier soll es sehr\nseltene Fossilien\vgeben.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Was? Ich warte\nhier auf meine\vFreunde.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ich habe verloren?",
  ["_MtMoon1FHikerAfterBattleText"] = "Kinder wie du\nhaben hier nichts\vverloren!",
  ["_MtMoon1FHikerBattleText"] = "WOW! Hast du mich\nerschreckt! Ach,\vnur ein Kind!",
  ["_MtMoon1FHikerEndBattleText"] = "Wow!\nSchon wieder!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Ich muss stärkere\nPOKéMON finden.",
  ["_MtMoon1FSuperNerdBattleText"] = "Was! Schleich dich\nnicht so an!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Meine POKéMON\ntaugen nichts!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Ich bin hier, um\nvor Mädchen anzu-\vgeben.",
  ["_MtMoon1FYoungster1BattleText"] = "Bist du auch zum\nErforschen hier?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Verlieren\nstinkt!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Ich sah sie! Die\nsind sicher von\vTEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Verdächtige Männer\nsind in der Höhle.\vUnd du?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Du hast\nmich erwischt!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT ist lästig!\nDoch gefangen ist\ves recht\vnützlich.",
  ["_MtMoon1FYoungster3BattleText"] = "Durch diese Höhle\ngeht's nach\vAZURIA CITY!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ich habe\nverloren.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Willst du das\nDOMFOSSIL?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Willst du das\nHELIXFOSSIL?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} erhält\ndas {RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Du machst mich\nwütend! TEAM\vROCKET setzt dich\vauf die schwarze\vListe!",
  ["_MtMoonB2FRocket1BattleText"] = "TEAM ROCKET fin-\ndet die Fossilien,\vbelebt sie wieder\vund verkauft sie!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Urgh!\nJetzt reicht's!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Verflixt! Meine\nKollegen werden\vdas nicht dulden!",
  ["_MtMoonB2FRocket2BattleText"] = "Wir, TEAM ROCKET,\nsind POKéMON-\vGangster!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ich habe\nversagt!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Findest du ein\nFossil, gib es her\vund verschwinde!",
  ["_MtMoonB2FRocket3BattleText"] = "Wir drehen hier\nein großes Ding!\vVerschwinde, Kind!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Du bist\nalso gut.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "POKéMON lebten\nhier lange vor\vden Menschen.",
  ["_MtMoonB2FRocket4BattleText"] = "Kleine Kinder\nsollen Erwachsene\vin Ruhe lassen!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Ich\nkoche!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "OK!\nIch teile!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "Na gut. Dann ist\ndas hier meins!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Weit weg, auf der\nZINNOBERINSEL,\vgibt es ein\vPOKéMON-LABOR.\fDort erforscht man\ndie Wiederbelebung\vvon Fossilien.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "He, stopp!\fIch fand diese\nFossilien! Beide\vgehören mir!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Schau, du hast\nkeinen Platz\vdafür.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Jeder nimmt eins!\nNicht gierig\vwerden!",
  ["_MtMoonPokecenterBenchGuyText"] = "Hast du zu viele\nPOKéMON, lagere\vsie am PC ein!",
  ["_MtMoonPokecenterGentlemanText"] = "TEAM ROCKET greift\nBürger von AZURIA\van...\fTEAM ROCKET ist\nständig in den\vNachrichten!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "MANN: Hallo! Ich\nhab' da ein Ange-\vbot nur für dich!\fDu bekommst ein\ntolles KARPADOR\vfür nur ¥500!\vWas sagst du?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Du brauchst mehr\nGeld als das!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "MANN: Ich gebe\nnichts zurück!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "Nein? Ich tue dir\ndamit doch nur\veinen Gefallen!",
  ["_MtMoonPokecenterYoungsterText"] = "Ich habe 6 POKé-\nBÄLLE am Gürtel.\fMan kann maximal\n6 POKéMON tragen.",
  ["_MukDexEntry"] = "Dick bedeckt mit\neinem üblen,\nfauligen Schlamm.\fEs ist so giftig,\ndass sogar seine\nSpuren Gift sind",
  ["_MultiHitText"] = "Der Gegner wurde\n{NUM:wPlayerNumHits, 1, 1} mal getroffen!",
  ["_Museum1FGamblerText"] = "Was für ein\nprächtiges\vFossil!",
  ["_Museum1FOldAmberText"] = "Der BERNSTEIN ist\nklar und golden!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "BERNSTEIN ist\nfossiles Harz.",
  ["_Museum1FScientist1ComeAgainText"] = "Komm bald wieder!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Hier schleicht\nsich keiner rein!\fAch, egal!\nWeisst du, was\vBERNSTEIN ist?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Du hast nicht\ngenug Geld.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Bitte geh auf\ndie andere Seite!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Nimm dir viel\nZeit zum Schauen!",
  ["_Museum1FScientist1ThankYouText"] = "Genau, ¥50!\nVielen Dank!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "Es gibt ein Labor,\ndas versucht,\vuralte POKéMON\vaus BERNSTEIN zu\verwecken.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Kinder zahlen ¥50\nEintritt.\fMöchtest du\nhereinkommen?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Psst! Prüf den\nALTBERNSTEIN!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} erhält\nALTBERNSTEIN!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Psst! Ich glaube,\ndieser BERNSTEIN\venthält POKéMON-\vDNA!\fEs wäre toll, wenn\nman daraus wieder\vPOKéMON erwecken\vkönnte!\fAber die Kollegen\nignorieren mich!\fDaher habe ich\neine Bitte!\fBring das in ein\nPOKéMON-LABOR zur\vUntersuchung!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Du hast keinen\nPlatz dafür!",
  ["_Museum1FScientist3Text"] = "Wir sind stolz auf\n2 Fossilien sehr\vseltener, uralter\vPOKéMON!",
  ["_Museum2FBrunetteGirlText"] = "Ich will ein\nPIKACHU! So süß!\fPapa soll mir\neins fangen!",
  ["_Museum2FGrampsText"] = "20. Juli 1969!\fDie erste Mond-\nlandung!\fIch kaufte einen\nFarbfernseher!",
  ["_Museum2FHikerText"] = "Ja, du kriegst\nbald ein PIKACHU!",
  ["_Museum2FMoonStoneSignText"] = "Meteorit, der auf\nden MONDBERG fiel.\v(MONDSTEIN?)",
  ["_Museum2FScientistText"] = "Wir haben nun eine\nWeltraumschau.",
  ["_Museum2FSpaceShuttleSignText"] = "SPACE SHUTTLE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "MONDSTEIN?\fWas ist daran so\nbesonders?",
  ["_MustRechargeText"] = "{USER}\nmuss sich erholen!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, ja?\nEin wirklich\vtadelloser Name!\fPass gut auf\n{RAM:wNameBuffer} auf!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Gut! Komm wieder,\nwann du willst!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, ja?\nEin ganz passab-\vler Spitzname!\fAber soll ich ihm\neinen schöneren\vNamen geben?\fWie wär's?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Dieses POKéMON\nheisst von nun an\v{RAM:wBuffer}!\fEin viel besserer\nName als vorher!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Hallo, hallo!\nIch bin der\vNAMENSBEWERTER!\fSoll ich die Namen\ndeiner POKéMON\vbewerten?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Gut! Wie sollen\nwir es nennen?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Welches POKéMON\nsoll ich ansehen?",
  ["_NeedYourPokemonText"] = "OK. Wir brauchen\ndein POKéMON.",
  ["_NewBadgeRequiredText"] = "Nein! Du brauchst\neinen neuen ORDEN.",
  ["_NewBicycleText"] = "Ein glänzendes,\nneues FAHRRAD!",
  ["_NidokingDexEntry"] = "Sein mächtiger\nSchweif zermalmt\ndie Beute, um-\fschlingt sie und\nbricht ihr die\nKnochen",
  ["_NidoqueenDexEntry"] = "Seine harten\nSchuppen bieten\nguten Schutz. Es\fnutzt seine Masse\nfür kraftvolle\nAttacken",
  ["_NidoranFDexEntry"] = "Klein, aber dank\ngiftiger Stacheln\ngefährlich. Das\fWeibchen hat\nkleinere Hörner\nals das Männchen",
  ["_NidoranMDexEntry"] = "Es spitzt seine\ngroßen Ohren bei\nGefahr. Je größer\fsein Horn, desto\nstärker ist sein\nGift",
  ["_NidorinaDexEntry"] = "Das Horn des\nWeibchens wächst\nlangsam. Es kämpft\flieber mit Krallen\nund Bissen als mit\ndem Horn",
  ["_NidorinoDexEntry"] = "Ein aggressives\nPOKéMON, das sehr\nschnell angreift.\fSein Kopfhorn\nsondert starkes\nGift ab",
  ["_NinetalesDexEntry"] = "Sehr klug und\nrachsüchtig. Wer\neinen Schweif\fpackt, riskiert\neinen Fluch von\n1000 Jahren",
  ["_NoCyclingAllowedHereText"] = "Radfahren ist\nhier verboten.",
  ["_NoEffectText"] = "Ohne Effekt!",
  ["_NoMonText"] = "Was? Hier gibt es\nkeine POKéMON!",
  ["_NoMoreRoomForItemText"] = "Kein Platz mehr\nfür ITEMs!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick}\nhat keine AP mehr!",
  ["_NoNibbleText"] = "Hier beisst\nnichts an!",
  ["_NoRoomToStoreText"] = "Kein Platz zum\nLagern von ITEMs.",
  ["_NoRunningText"] = "Nein! Vor einem\nTRAINER kann man\vnicht fliehen!",
  ["_NoSurfingHereText"] = "Hier kann man mit\n{RAM:wNameBuffer}\vnicht SURFEN!",
  ["_NoTrade1Text"] = "Ohhh!\nNa gut...",
  ["_NoTrade2Text"] = "Tja, wenn du\nnicht willst...",
  ["_NoTrade3Text"] = "Wie schade.",
  ["_NoWillText"] = "Da ist kein Wille\nzu kämpfen!",
  ["_NotEnoughCoinsSlotMachineText"] = "Nicht genug\nMünzen!",
  ["_NotHealthyEnoughText"] = "Nicht gesund\ngenug.",
  ["_NotThisTimeText"] = "Diesmal nicht!",
  ["_NotVeryEffectiveText"] = "Es ist nicht sehr\neffektiv...",
  ["_NothingHappenedText"] = "Nichts passiert!",
  ["_NothingHereText"] = "Sieht aus, als ob\nhier nichts ist.",
  ["_NothingStoredText"] = "Es ist nichts\ngelagert.",
  ["_NothingToCutText"] = "Es gibt nichts zu\nZERSCHNEIDEN!",
  ["_NothingToDepositText"] = "Du hast nichts\nzum Einlagern.",
  ["_OHKOText"] = "K.O. mit einem\nSchlag!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "Hier ist eine\nE-Mail!\f...\fAn alle POKéMON-\nTRAINER!\fDie Elite-TRAINER\nder POKéMON-LIGA\vfordern alle\vheraus!\fBringt eure besten\nPOKéMON mit und\vzeigt, was ihr\vkönnt!\fPOKéMON-LIGA HQ\nINDIGO PLATEAU\fPS: PROF. EICH,\nbesuchen Sie uns!\v...",
  ["_OakSpeechText1"] = "Hallo!\nWillkommen in der\vWelt der POKéMON!\fMein Name ist\nEICH! Alle nennen\vmich POKéMON-\vPROF.!",
  ["_OakSpeechText2A"] = "Diese Welt wird\nvon Wesen namens\vPOKéMON bewohnt!",
  ["_OakSpeechText2B"] = "\fFür manche sind\nPOKéMON Haus-\vtiere. Andere\vkämpfen mit ihnen.\fIch selbst...\fIch studiere\nPOKéMON von\vBerufs wegen.",
  ["_OakSpeechText3"] = "{PLAYER}!\fDeine eigene\nPOKéMON-Legende\vbeginnt jetzt!\fEine Welt voller\nTräume und Aben-\vteuer mit POKéMON\verwartet dich!\vLos geht's!",
  ["_OaksAideComeBackText"] = "Ach so.\fBei {NUM:hOaksAideRequirement, 1, 3} Arten komm\nwieder! Dann er-\vhältst du:\v{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideGotItemText"] = "{PLAYER} erhält:\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Super! Du hast {NUM:hOaksAideNumMonsOwned, 1, 3}\nArten POKéMON\vgefangen!\vGlückwunsch!\fHier, für dich!",
  ["_OaksAideHiText"] = "Hi! Kennst du mich\nnoch? Ich bin der\vASSISTENT von\vPROF. EICH!\fHast du {NUM:hOaksAideRequirement, 1, 3} Arten\nPOKéMON gefangen,\vbekommst du von\vmir:\v{RAM:wOaksAideRewardItemName}!\fAlso, {PLAYER}!\nHast du schon {NUM:hOaksAideRequirement, 1, 3}\vArten POKéMON\vgefangen?",
  ["_OaksAideNoRoomText"] = "Oh! Du hast wohl\nkeinen Platz für\vdas ITEM:\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Mal sehen...\nOh-oh! Du hast\verst {NUM:hOaksAideNumMonsOwned, 1, 3} Arten\vPOKéMON gefangen!\fDu brauchst {NUM:hOaksAideRequirement, 1, 3}\nArten für den\vPreis:\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "PROF. EICH ist DIE\nAutorität für\vPOKéMON!\fViele POKéMON-\nTRAINER schätzen\vihn sehr!",
  ["_OaksLabGivePokeballsExplanationText"] = "\fTaucht ein wildes\nPOKéMON auf, ist\ves Freiwild.\fWirf einen POKé-\nBALL danach und\vfang es!\fDas klappt aber\nnicht immer.\fEin gesundes\nPOKéMON kann\ventkommen. Du\vmusst Glück haben!",
  ["_OaksLabLastMonText"] = "Das letzte POKéMON\nvon PROF. EICH!",
  ["_OaksLabMonEnergeticText"] = "Dieses POKéMON\nist sehr munter!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "EICH: Besuch mich\ndoch mal wieder.\fIch will wissen,\nwie dein POKéDEX\vvorankommt.",
  ["_OaksLabOak1DeliverParcelText"] = "EICH: Oh, {PLAYER}!\fWie geht es meinem\nalten POKéMON?\fEs scheint dich\nsehr zu mögen.\fDu hast wohl\nTalent als\vPOKéMON-TRAINER!\fWas? Du hast\netwas für mich?\f{PLAYER} übergibt\nEICHS PAKET.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "EICH: Schön, dich\nzu sehen! Wie\vläuft es mit dem\vPOKéDEX? Zeig\vmal her!",
  ["_OaksLabOak1ParcelThanksText"] = "\fAh! Das ist der\nPOKéBALL, den ich\vbestellt hatte!\vDanke sehr!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "Überall warten\nPOKéMON auf dich,\v{PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "EICH: {PLAYER},\ntrainiere dein\vjunges POKéMON,\vindem es kämpft!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "EICH: Nur vom\nSehen bekommt man\vkeine genauen\vDaten zu POKéMON.\fDu musst sie\nfangen! Nimm die\vhier für wilde\vPOKéMON.\f{PLAYER} erhält 5\nPOKéBÄLLE!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "EICH: Nun,\n{PLAYER}, welches\vPOKéMON willst du?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "EICH: Taucht ein\nwildes POKéMON\vauf, kann dein\vPOKéMON kämpfen!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "EICH: Geduld!\n{RIVAL}, du be-\vkommst auch eins!",
  ["_OaksLabOakChooseMonText"] = "EICH: {RIVAL}?\nMoment mal...\fAch ja, richtig!\nIch bat dich her-\vzukommen! Warte!\fHier, {PLAYER}!\fEs sind 3 POKéMON\nhier!\fHaha!\fSie stecken in den\nPOKéBÄLLEN.\fAls junger Mann\nwar ich ein ernst-\vhafter TRAINER!\fJetzt bin ich alt.\nMir bleiben nur 3,\vaber eins gehört\vdir! Wähle!",
  ["_OaksLabOakDontGoAwayYetText"] = "EICH: He! Geh\nnoch nicht weg!",
  ["_OaksLabOakGotPokedexText"] = "EICH: {PLAYER} und\n{RIVAL}! Nehmt\vdie hier mit!\f{PLAYER} erhält\nPOKéDEX von EICH!",
  ["_OaksLabOakIHaveARequestText"] = "EICH: Ach ja! Ich\nhabe eine Bitte\van euch beide.",
  ["_OaksLabOakMyInventionPokedexText"] = "Auf dem Tisch\nliegt meine Er-\vfindung: POKéDEX!\fEr speichert Daten\nzu POKéMON, die\vman gesehen oder\vgefangen hat!\fEine Hi-Tech-\nEnzyklopädie!",
  ["_OaksLabOakThatWasMyDreamText"] = "Ein kompletter\nFührer über alle\vPOKéMON der\vWelt...\fDas war mein\nTraum!\fAber ich bin zu\nalt! Ich schaffe\ves nicht mehr!\fDrum sollt ihr\nzwei meinen Traum\verfüllen!\fAn die Arbeit,\nihr zwei!\fDies ist eine\ngroße Tat in der\vPOKéMON-Historie!",
  ["_OaksLabPokedexText"] = "Wie eine Enzyklo-\npädie, aber die\vSeiten sind leer!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} erhält\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Ja!\nBin ich gut oder\vwas?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Opa!\nIch habe es satt\vzu warten!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Ha, ich\nmuss nicht gierig\vsein wie du!\fNur zu, wähle\nzuerst, {PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Yo,\n{PLAYER}! Opa ist\vnicht da!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Opa!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "WAS?\nUnglaublich!\vIch habe das\vfalsche POKéMON\vgewählt!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Dann\nnehme ich das\vhier!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Warte,\n{PLAYER}! Testen\vwir unsere\vPOKéMON!\fKomm schon, ich\nfordere dich!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: Klar,\nOpa! Verlass dich\vauf mich!\f{PLAYER}, tut mir\nleid, aber dich\vbrauche ich nicht!\fIch weiß! Ich\nleihe mir die\vKARTE meiner\vSchwester!\fIch sag ihr, dass\ndu keine kriegst,\v{PLAYER}! Hahaha!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mein\nPOKéMON sieht\vviel stärker aus.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} erhält\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Okay!\nMein POKéMON soll\vkämpfen und hart\vwerden!\f{PLAYER}! Opa!\nRiech euch später!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: He!\nOpa! Was ist\vmit mir?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Warum\nhast du mich\vgerufen?",
  ["_OaksLabScientistText"] = "Ich bin PROF.\nEICHS ASSISTENT\vund erforsche\vPOKéMON.",
  ["_OaksLabThoseArePokeBallsText"] = "Das sind POKé-\nBÄLLE. Sie ent-\vhalten POKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "So! Du willst das\nPflanzen-POKéMON\vBISASAM?",
  ["_OaksLabYouWantCharmanderText"] = "So! Du willst das\nFeuer-POKéMON\vGLUMANDA?",
  ["_OaksLabYouWantSquirtleText"] = "So! Du willst das\nWasser-POKéMON\vSCHIGGY?",
  ["_OddishDexEntry"] = "Tagsüber steckt\nes sein Gesicht\nin den Boden.\fNachts streut es\numherwandernd\nseine Samen",
  ["_OhFineThenText"] = "Na schön.",
  ["_OlderFileWillBeErasedText"] = "Der ältere Spiel-\nstand wird über-\vschrieben. Okay?",
  ["_OmanyteDexEntry"] = "Längst ausgestor-\nben. In seltenen\nFällen kann es\faus Fossilien\ngenetisch erweckt\nwerden",
  ["_OmastarDexEntry"] = "Ein Ur-POKéMON,\ndas ausstarb, da\nsein schwerer\fPanzer die Jagd\nauf Beute unmög-\nlich machte",
  ["_OnceReleasedText"] = "Freigelassen ist\n{RAM:wStringBuffer} für\vimmer weg. OK?",
  ["_OneMoreGoSlotMachineText"] = "Noch eine\nRunde?",
  ["_OneTwoAndText"] = "1, 2 und...",
  ["_OnixDexEntry"] = "Während es wächst,\nwerden die Stein-\nteile des Körpers\fhart wie Diamant,\naber schwarz\ngefärbt",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ups! Du hast\nnicht genug Platz.",
  ["_OutOfCoinsSlotMachineText"] = "Mist!\nMünzen sind alle!",
  ["_OutOfSafariBallsText"] = "PA: Ding-dong!\fDeine SAFARIBÄLLE\nsind alle!",
  ["_PPIncreasedText"] = "{RAM:wStringBuffer}:\nAP wurden erhöht.",
  ["_PPMaxedOutText"] = "{RAM:wStringBuffer}:\nAP sind maximal.",
  ["_PPRestoredText"] = "AP aufgefrischt.",
  ["_PalletTownFisherText"] = "Technik ist un-\nglaublich!\fMan kann ITEMs\nund POKéMON nun\vals Daten per PC\vlagern und holen!",
  ["_PalletTownGirlText"] = "Ich ziehe auch\nPOKéMON groß!\fWenn sie stark\nsind, beschützen\vsie mich!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "EICH: He! Warte!\nGeh nicht raus!",
  ["_PalletTownOakItsUnsafeText"] = "EICH: Gefährlich!\nIm hohen Gras\vleben wilde\vPOKéMON!\fDu brauchst ein\neigenes POKéMON\vals Schutz.\vIch weiß!\fHier, komm mit\nmir!",
  ["_PalletTownOaksLabSignText"] = "EICHS POKéMON-\nFORSCHUNGSLABOR",
  ["_PalletTownPlayersHouseSignText"] = "{PLAYER}s Haus ",
  ["_PalletTownRivalsHouseSignText"] = "{RIVAL}s Haus ",
  ["_PalletTownSignText"] = "ALABASTIA\nHier beginnt\vdeine Reise!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\nist paralysiert!\vEs greift evtl.\vnicht an!",
  ["_ParasDexEntry"] = "Es gräbt und saugt\nan Baumwurzeln.\nDie Pilze auf dem\fRücken wachsen\ndurch Nährstoffe\ndes Wirts",
  ["_ParasectDexEntry"] = "Ein Wirt-Parasit-\nPaar, bei dem der\nPilz den Käfer-\fwirt beherrscht.\nEs mag feuchte\nOrte",
  ["_ParlyzHealText"] = "{RAM:wNameBuffer}:\nParalyse geheilt!",
  ["_PartyMenuBattleText"] = "Welches POKéMON\neinsetzen?",
  ["_PartyMenuItemUseText"] = "ITEM bei welchem\nPOKéMON anwenden?",
  ["_PartyMenuNormalText"] = "Wähle ein POKéMON.",
  ["_PartyMenuSwapMonText"] = "POKéMON wohin\nverschieben?",
  ["_PartyMenuUseTMText"] = "TM bei welchem\nPOKéMON anwenden?",
  ["_PersianDexEntry"] = "Sein Fell hat\nviele Bewunderer.\nAls Haustier ist\fes wegen seiner\nLaunen aber\nschwer zu halten",
  ["_PewterCityCooltrainerFText"] = "Man munkelt, dass\nPIEPI vom Mond\vstammen!\fSie erschienen,\nals der MONDSTEIN\vauf den MONDBERG\vfiel.",
  ["_PewterCityCooltrainerMText"] = "Hier gibt es kaum\nernste TRAINER!\fAlle sind wie\nKÄFERSAMMLER,\vaber ROCKO von\vMARMORIAS ARENA\vist voll dabei!",
  ["_PewterCityGymSignText"] = "MARMORIA CITY\nPOKéMON-ARENA\vLEITER: ROCKO\fDer felsenfeste\nPOKéMON-TRAINER!",
  ["_PewterCityMuseumSignText"] = "MARMORIA-MUSEUM\nDER WISSENSCHAFT",
  ["_PewterCityPokecenterGuyText"] = "Gähn!\fWenn PUMMELUFF\nsingt, werden\vPOKéMON müde...\f...Ich auch...\nSchnarch...",
  ["_PewterCityPoliceNoticeSignText"] = "ACHTUNG!\fDiebe stehlen\nPOKéMON-Fossilien\vam MONDBERG! Hin-\vweise bitte an die\vPOLIZEI MARMORIA!",
  ["_PewterCitySignText"] = "MARMORIA CITY\nGrau wie Stein",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Warst du schon im\nMUSEUM?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "Es ist gleich da!\nDer Eintritt kos-\vtet was, lohnt\vsich aber!\vBis dann!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Waren die Fossi-\nlien vom MONDBERG\vnicht toll?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Wirklich?\nDa musst du un-\vbedingt hin!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst!\nWeisst du, was ich\vhier mache?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Ich sprühe SCHUTZ,\num POKéMON aus\vmeinem Garten\vfernzuhalten!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Genau! Es ist\nharte Arbeit!",
  ["_PewterCityTrainerTipsText"] = "TIPPS FÜR TRAINER\fJedes POKéMON, das\nam Kampf teil-\vnimmt, erhält EP,\vegal wie kurz!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Wenn du das Zeug\ndazu hast, forde-\vre ROCKO heraus!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Du bist doch ein\nTRAINER? ROCKO\vsucht neue Heraus-\vforderer! Komm\vmit!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\fDas ist ein offi-\nzieller ORDEN der\vPOKéMON-LIGA!\fDie POKéMON des\nTrägers werden\vstärker!\fDie Technik BLITZ\nist nun jederzeit\veinsetzbar!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Es gibt alle Ar-\nten von TRAINERN\vauf der Welt!\fDu scheinst sehr\nbegabt zu sein\vals TRAINER!\fGeh zur ARENA in\nAZURIA und teste\vdein Können!",
  ["_PewterGymBrockPreBattleText"] = "Ich bin ROCKO!\nMARMORIAS ARENA-\vLEITER!\fIch glaube an\nsteinharte Vertei-\vdigung und Ent-\vschlossenheit!\fDarum sind meine\nPOKéMON alle vom\vTyp GESTEIN!\fWillst du mich\nnoch fordern?\vGut! Zeig mir\vdein Bestes!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ich habe\ndich unterschätzt.\fZum Beweis deines\nSieges, hier der\vFELSORDEN!\f{PLAYER} erhält\nden FELSORDEN!",
  ["_PewterGymBrockWaitTakeThisText"] = "Warte! Nimm das\nhier noch mit!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Du bist ziemlich\nstark, aber nicht\vso wie ROCKO!",
  ["_PewterGymCooltrainerMBattleText"] = "Stopp, Kleiner!\fDu bist noch\nLichtjahre von\vROCKO entfernt!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Mist!\fLichtjahre messen\nkeine Zeit, son-\vdern Entfernung!",
  ["_PewterGymGuideAdviceText"] = "Das 1. POKéMON in\nder POKéMON-LISTE\vkämpft im Match\vzuerst!\fÄndert man die\nReihenfolge, wer-\vden Kämpfe evtl.\veinfacher!",
  ["_PewterGymGuideBeginAdviceText"] = "Na gut! Legen\nwir los!",
  ["_PewterGymGuideFreeServiceText"] = "Der Service ist\ngratis! Legen\vwir los!",
  ["_PewterGymGuidePostBattleText"] = "Wusste ich's doch!\nDu hast das Zeug\vzum POKéMON-Champ!",
  ["_PewterGymGuidePreAdviceText"] = "Hiya! Ich sehe, du\nhast das Zeug zum\vPOKéMON-Champ!\fIch bin kein\nTRAINER, aber ich\vweiß, wie man\vgewinnt!\fIch bringe dich\nan die Spitze!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} erhält\nTM34!",
  ["_PewterGymTM34NoRoomText"] = "Du hast keinen\nPlatz dafür!",
  ["_PewterMartSuperNerdText"] = "Gutes kann gesche-\nhen, wenn man\vPOKéMON fleißig\vtrainiert, selbst\vdie schwachen!",
  ["_PewterMartYoungsterText"] = "Ein zwielichtiger\nAlter drehte mir\vein komisches\vFisch-POKéMON an!\fEs ist total\nschwach und hat\v¥500 gekostet!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, sitz!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Unser POKéMON ist\nein Fremdling und\vschwer zu lenken.\fEin Fremdling ist\nein POKéMON aus\veinem Tausch.\fEs wächst schnell,\nignoriert aber im\vKampf unerfahrene\vTRAINER!\fHätten wir doch\nein paar ORDEN...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Wuffwuff!",
  ["_PewterPokecenterGentlemanText"] = "Was!?\fTEAM ROCKET ist\nam MONDBERG? Hä?\vIch telefoniere!\fVerschwinde!",
  ["_PewterPokecenterJigglypuffText"] = "PUMMELUFF: Puu\npupuu!",
  ["_PewterSpeechHouseGamblerText"] = "POKéMON lernen\nbeim Wachsen neue\vTechniken!\fManche Attacken\nmuss der TRAINER\vaber beibringen!",
  ["_PewterSpeechHouseYoungsterText"] = "Verletzte oder\nschlafende POKéMON\vlassen sich leich-\vter fangen!\fAber sicher ist\ndas nicht!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} hebt\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} auf!",
  ["_PidgeotDexEntry"] = "Bei der Jagd\nfliegt es flach\nübers Wasser, um\fahnungslose Beute\nwie KARPADOR zu\nschnappen",
  ["_PidgeottoDexEntry"] = "Es verteidigt\nsein großes Re-\nvier vehement und\fhackt mit dem\nSchnabel auf Ein-\ndringlinge ein",
  ["_PidgeyDexEntry"] = "Oft in Wäldern zu\nsehen. Es schlägt\nam Boden mit den\fFlügeln und wir-\nbelt blendenden\nSand auf",
  ["_PikachuDexEntry"] = "Wenn sich mehrere\ndieser POKéMON\nsammeln, kann ihr\fStrom sich laden\nund Gewitter\nauslösen",
  ["_PinsirDexEntry"] = "Kann es die Beute\nnicht mit den\nZangen zermalmen,\fschleudert es sie\numher und wirft\nsie hart fort",
  ["_PlaySlotMachineText"] = "Ein Spielautomat!\nWillst du spielen?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} spielt\ndie POKéFLÖTE.",
  ["_PlayedFluteNoEffectText"] = "POKéFLÖTE\ngespielt.\fWas für eine\nflotte Melodie!",
  ["_PlayerBlackedOutText"] = "{PLAYER} hat keine\nPOKéMON mehr!\f{PLAYER} fiel in\nOhnmacht!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} hat keine\nPOKéMON mehr!\f{PLAYER} fiel in\nOhnmacht!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick} ",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick}\nwurde besiegt!",
  ["_PleaseWaitText"] = "OK, bitte warte\neinen Moment.",
  ["_PoisonedText"] = "{TARGET}\nwurde vergiftet!",
  ["_PokeCenterSignText"] = "POKéMON heilen!\nPOKéMON-CENTER",
  ["_PokemartAnythingElseText"] = "Kann ich sonst\nnoch was tun?",
  ["_PokemartBoughtItemText"] = "Bitte sehr!\nVielen Dank!",
  ["_PokemartBuyingGreetingText"] = "Lass dir Zeit.",
  ["_PokemartGreetingText"] = "Hallo!\nWas darf's sein?",
  ["_PokemartItemBagEmptyText"] = "Du hast nichts\nzu verkaufen.",
  ["_PokemartItemBagFullText"] = "Du kannst nichts\nmehr tragen.",
  ["_PokemartNotEnoughMoneyText"] = "Du hast nicht\ngenug Geld.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nDas macht dann\v¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}. OK?",
  ["_PokemartTellSellPriceText"] = "Dafür zahle ich\ndir ¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}.",
  ["_PokemartThankYouText"] = "Vielen Dank!",
  ["_PokemartUnsellableItemText"] = "Das kann ich\nnicht ankaufen.",
  ["_PokemonBooksText"] = "Vollgestopft mit\nPOKéMON-Büchern!",
  ["_PokemonCenterFarewellText"] = "Auf ein baldiges\nWiedersehen!",
  ["_PokemonCenterWelcomeText"] = "Willkommen im\nPOKéMON-CENTER!\fWir machen deine\nPOKéMON wieder\vtopfit!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\nwurde besiegt!",
  ["_PokemonFanClubBagFullText"] = "Mach dafür\nPlatz frei!",
  ["_PokemonFanClubChairFinalText"] = "Hallo, {PLAYER}!\fWillst du wieder\netwas über meine\vPOKéMON hören?\fNein? Schade!",
  ["_PokemonFanClubChairmanIntroText"] = "Ich leite den\nPOKéMON-Fanclub!\fIch habe über 100\nPOKéMON gesammelt!\fBei POKéMON bin\nich sehr penibel!\fAlso...\fBist du hier, um\nvon meinen POKé-\vMON zu hören?",
  ["_PokemonFanClubChairmanStoryText"] = "Gut!\nDann hör zu!\fMein liebstes\nGALLOPA...\fEs...süß...\nlieblich...klug...\vdazu...toll...\vfindest du?...\voh ja...es...\vumwerfend...\vsanft...\vich lieb es!\fEs umarmen...wenn\nes schläft...warm\vund kuschlig...\vspektakulär...\vhinreißend...\v...Ups! Wie spät\ves ist! Ich habe\vdich aufgehalten!\fDanke fürs Zu-\nhören! Das ist\vfür dich!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\fTausch das gegen\nein FAHRRAD ein!\fKeine Sorge, mein\nIBITAK FLIEGT\vmich überallhin!\fIch brauche also\nkein FAHRRAD!\fViel Spaß beim\nRadfahren!",
  ["_PokemonFanClubNoStoryText"] = "Oh. Komm wieder,\nwenn du meine\vGeschichte hören\vwillst!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Pah! Mein PIKACHU\nist doppelt so\vsüß wie das da!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Bewunderst du\nnicht den süßen\vSchweif meines\vPIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Unser Vorsitzender\nredet gern über\vPOKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Ach je!\fMein JUROB ist\nviel attraktiver!",
  ["_PokemonFanClubSeelFanNormalText"] = "Ich liebe mein\nJUROB einfach!\fEs quiekt, wenn\nich es umarme!",
  ["_PokemonFanClubSeelText"] = "JUROB: Kjuuu!",
  ["_PokemonFanClubSign1Text"] = "Hören wir anderen\nTRAINERN höflich\vzu!",
  ["_PokemonFanClubSign2Text"] = "Prahlt jemand,\nprahle zurück!",
  ["_PokemonFightingFitText"] = "Vielen Dank!\nDeine POKéMON\vsind topfit!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Ein Schlüssel? Ich\nweiß nicht, wovon\vdu redest.",
  ["_PokemonMansion1FScientistBattleText"] = "Wer bist du? Hier\nsollte niemand\vsein.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Autsch!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Noch nicht ganz!",
  ["_PokemonMansion1FSwitchPressedText"] = "Wer würde nicht?",
  ["_PokemonMansion1FSwitchText"] = "Ein Geheim-\nschalter!\fDrücken?",
  ["_PokemonMansion2FDiary1Text"] = "Tagebuch: 5. Juli\nGuyana,\vSüdamerika\fTief im Dschungel\nwurde ein neues\vPOKéMON entdeckt.",
  ["_PokemonMansion2FDiary2Text"] = "Tagebuch: 10. Juli\nWir tauften das\vneu entdeckte\vPOKéMON MEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Schalter öffnen\nund schließen ab-\vwechselnd Türen!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Ich komme nicht\nraus! Das alte\vHaus ist ein\veinziges Rätsel!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh nein!\nMeine Beute!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Noch nicht ganz!",
  ["_PokemonMansion2FSwitchPressedText"] = "Wer würde nicht?",
  ["_PokemonMansion2FSwitchText"] = "Ein Geheim-\nschalter!\fDrücken?",
  ["_PokemonMansion3FDiaryText"] = "Tagebuch: 6. Feb.\nMEW gebar.\fWir nannten das\nJunge MEWTU.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Du steckst fest?\nSpring dort doch\vrunter!",
  ["_PokemonMansion3FScientistBattleText"] = "Mein Mentor lebte\neinst hier.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Puh!\nÜberwältigend!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Wo mein Partner\nwohl hin ist?",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Dieser Ort ist,\nna ja, riesig!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Aua!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Hier liegen über-\nall Sachen herum.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh-oh. Wo bin\nich jetzt?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Auuu!",
  ["_PokemonMansionB1FDiaryText"] = "Tagebuch: 1. Sept.\nMEWTU ist viel zu\vstark.\fWir konnten seine\nWildheit nicht\vzügeln...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Mir gefällt es\nhier! Gut für\vmeine Studien!",
  ["_PokemonMansionB1FScientistBattleText"] = "Dieser Ort ist\nideal fürs Labor.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "Wofür\nwar das denn?",
  ["_PokemonSellingGreetingText"] = "Was möchtest du\nverkaufen?",
  ["_PokemonStuffText"] = "Wow! Jede Menge\nPOKéMON-Sachen!",
  ["_PokemonTower1FBaldingGuyText"] = "Ich bete für mein\nPIEPI.\fSchnief! Ich muss\nimmer weinen...",
  ["_PokemonTower1FChannelerText"] = "Ich bin eine\nSEHERIN! Geister\vtreiben Unfug!",
  ["_PokemonTower1FGirlText"] = "Mein FUKANO...\nWarum starbst du?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Kommst du zum\nGedenken?\vSei gesegnet!",
  ["_PokemonTower1FReceptionistText"] = "Der POKéMON-TURM\nwurde zum Geden-\vken an verstor-\vbene POKéMON\verbaut.",
  ["_PokemonTower2FChannelerText"] = "Selbst wir konn-\nten die GEISTER\vnicht erkennen!\fEin SILPH SCOPE\nkönnte sie wohl\ventlarven.",
  ["_PokemonTower2FRivalDefeatedText"] = "Was?\nDu Stinker!\fDabei war ich\nnoch nett zu dir!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Wie läuft's mit\ndem POKéDEX?\vIch habe gerade\vein TRAGOSSO\vgefangen!\fDas erwachsene\nKNOGGA finde ich\vnoch nicht!\fEs gibt wohl kei-\nne mehr! Na, ich\vmuss weiter!\vHabe noch viel\vvor, Kumpel!\fRiech dich später!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Sieh dir\ndeine schlappen\vPOKéMON an!\fTrainiere sie\nnoch etwas!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: He,\n{PLAYER}! Was\vmachst du hier?\vDeine POKéMON\vsehen nicht tot\vaus!\fIch kann sie we-\nnigstens besiegen!\vLos, Kumpel!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Die GEISTER lassen\nsich per SILPH\vSCOPE erkennen.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg...Awaa...\nHuhu...graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Hwa!\nIch bin gerettet!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Tut mir leid! Ich\nwar besessen!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke....\nKwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Hmm?\nWas mache ich da?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Meine Freunde wa-\nren auch besessen!",
  ["_PokemonTower3FChanneler3BattleText"] = "Weiche!\nBöser Geist!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Puh!\nDer Geist ist weg!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Ich muss geträumt\nhaben...",
  ["_PokemonTower4FChanneler1BattleText"] = "Ein GEIST! Nein!\nKwaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Wo\nist der GEIST?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Wir können die\nGEISTER nicht\videntifizieren.",
  ["_PokemonTower4FChanneler2BattleText"] = "Sei verflucht\nmit mir! Kwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Was!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Mögen die Seelen\nder POKéMON in\vFrieden ruhen...",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu...\nSchlag mich nicht!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Hä?\nWer? Was?",
  ["_PokemonTower5FChanneler1Text"] = "Komm, Kind! Ich\nschützte diesen\vOrt mit weißer\vMagie!\fHier kannst du\ndich ausruhen!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Ich war\nbesessen!",
  ["_PokemonTower5FChanneler2BattleText"] = "Gib...mir...\ndeine...Seele...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Huch!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ich war besessen!",
  ["_PokemonTower5FChanneler3BattleText"] = "Du...gehörst...\nbald...uns...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Was für ein\nAlbtraum!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Ich bin wieder\nbei Sinnen!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombies!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Ha?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Trotz meiner Aus-\nbildung erlag ich\vbösen Geistern!",
  ["_PokemonTower5FChanneler5BattleText"] = "Urgah...\nUrff....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Hui!",
  ["_PokemonTower5FPurifiedZoneText"] = "Gereinigte Schutz-\nzone betreten!\f{PLAYER}s POKéMON\nsind ganz geheilt!",
  ["_PokemonTower6FBeGoneText"] = "Verschwindet...\nEindringlinge...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Ich fühle mich\nblutarm und\vschwach...",
  ["_PokemonTower6FChanneler1BattleText"] = "Gebt...mir...\nBlut...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Stöhn!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "Das Haar fiel gar\nnicht aus! Es war\vein böser Geist!",
  ["_PokemonTower6FChanneler2BattleText"] = "Urff... Kwaah!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Etwas\nist ausgefallen!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Was geht hier\nnur vor?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\nke..ke...ke!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Kiii!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Der GEIST war die\nruhelose Seele von\vTRAGOSSOs Mutter!",
  ["_PokemonTower6FSoulWasCalmedText"] = "Die Mutterseele\nwurde besänftigt.\fSie ging hinüber\nins Jenseits!",
  ["_PokemonTower7FMrFujiRescueText"] = "MR.FUJI: Wie? Du\nwolltest mich\vretten?\fDanke. Aber ich\nbin aus freien\vStücken hier.\fIch wollte die\nSeele von TRAGOS-\vSOs Mutter beruhi-\vgen.\fKNOGGAs Geist ist\nwohl nun im Jen-\vseits.\fIch danke dir für\ndeine Anteilnahme!\fFolge mir zu mir\nnach Hause, dem\vPOKéMON-HAUS am\vFuße des Turms.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Das werde ich\nnicht vergessen!",
  ["_PokemonTower7FRocket1BattleText"] = "Was willst du?\nWarum bist du da?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Ich gebe auf!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "POKéMON sind nur\ngut, um Geld zu\vmachen!\fHalt dich aus\nunseren Geschäf-\vten raus!",
  ["_PokemonTower7FRocket2BattleText"] = "Der Alte kam und\nbeschwerte sich,\vdass wir nutzlose\vPOKéMON quälen!\fWir bereden das\nunter Erwachsenen!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Bitte!\nNicht mehr!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Damit kommst du\nnicht durch!",
  ["_PokemonTower7FRocket3BattleText"] = "Du rettest nie-\nmanden, Kleiner!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Leg dich nicht\nmit ROCKETs an!",
  ["_PoliwagDexEntry"] = "Mit den neuen\nBeinen kann es\nnicht laufen. Es\fschwimmt offenbar\nlieber, als stehen\nzu üben",
  ["_PoliwhirlDexEntry"] = "Lebt im und außer-\nhalb des Wassers.\nAn Land schwitzt\fes, um den Körper\nschleimig zu\nhalten",
  ["_PoliwrathDexEntry"] = "Schwimmt meister-\nhaft Kraul und\nBrust. Überholt\fmühelos die bes-\nten menschlichen\nSchwimmer",
  ["_PonytaDexEntry"] = "Seine Hufe sind\n10-mal härter als\nDiamant. Es kann\falles im Nu\nplatt trampeln",
  ["_PoofText"] = " Puff!",
  ["_PorygonDexEntry"] = "Ein POKéMON, das\nnur aus Program-\nmiercode besteht.\fEs bewegt sich\nfrei im Cyber-\nspace",
  ["_PotionText"] = "{RAM:wNameBuffer}:\n{NUM:wHPBarHPDifference, 2, 3} KP aufgefüllt!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PrimeapeDexEntry"] = "Immer wütend und\nsehr hartnäckig.\nEs verfolgt seine\fBeute so lange,\nbis es sie ge-\nfangen hat",
  ["_PsyduckDexEntry"] = "Es lullt Gegner\nmit leerem Blick\nein und setzt\fdann heimlich\npsychokinetische\nKräfte ein",
  ["_PushStartText"] = "Drücke START für\ndas MENÜ!",
  ["_RaichuDexEntry"] = "Sein langer\nSchweif dient als\nErdung und schützt\fes vor seiner\neigenen Hoch-\nspannung",
  ["_RaisePPWhichTechniqueText"] = "AP welcher Technik\nerhöhen?",
  ["_RanAwayScaredText"] = "{TARGET}\nfloh voller Angst!",
  ["_RanFromBattleText"] = "{USER} floh\naus dem Kampf!",
  ["_RapidashDexEntry"] = "Sehr ehrgeizig.\nEs jagt allem\nnach, was schnell\fist, in der Hoff-\nnung auf ein\nWettrennen",
  ["_RareCandyText"] = "{RAM:wNameBuffer} wächst\nauf Level {NUM:wCurEnemyLevel, 1, 3}!",
  ["_RaticateDexEntry"] = "Es hält mit den\nBarthaaren die\nBalance. Es wird\fwohl langsamer,\nwenn man sie ab-\nschneidet",
  ["_RattataDexEntry"] = "Beisst bei Angrif-\nfen alles. Klein\nund sehr flink,\fist es vielerorts\nein gewohnter\nAnblick",
  ["_RedBedroomSNESText"] = "{PLAYER} spielt\nam SNES!\v...Okay!\vZeit zu gehen!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMA: Wie schön!\nDu und deine\vPOKéMON seht\vprima aus!\vPass auf dich auf!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMA: Tja.\nAlle Jungen ver-\vlassen mal ihr\vZuhause. So war's\vim TV.\fPROF. EICH von\nnebenan sucht\vdich.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMA: {PLAYER}!\nDu solltest kurz\vausruhen.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "Ein Film im TV.\nVier Jungen wan-\vdern auf Bahn-\vgleisen.\fIch sollte auch\nlosgehen.",
  ["_RedsHouse1FTVWrongSideText"] = "Ups, die falsche\nSeite.",
  ["_ReflectGainedArmorText"] = "{USER}\nist nun gepanzert!",
  ["_RegainedHealthText"] = "{USER}\nerholt sich!",
  ["_ReleaseWhichMonText"] = "Welches POKéMON\nfreilassen?",
  ["_RepelWoreOffText"] = "SCHUTZ wirkt\nnicht mehr.",
  ["_RequireCoinCaseText"] = "Ein MÜNZKORB ist\nerforderlich!",
  ["_RestorePPWhichTechniqueText"] = "AP welcher Technik\nauffrischen?",
  ["_ReviveText"] = "{RAM:wNameBuffer}\nist wieder fit!",
  ["_RhydonDexEntry"] = "Sein panzerartiges\nFell erlaubt ihm\nsogar, in 3.600\fGrad heißer, ge-\nschmolzener Lava\nzu leben",
  ["_RhyhornDexEntry"] = "Seine Knochen sind\n1000-mal härter\nals menschliche.\fEs schleudert\nmühelos Anhänger\ndurch die Luft",
  ["_Rival1WinText"] = "{RIVAL}: Ja!\nBin ich gut oder\vwas?",
  ["_RivalDefeatedText"] = "NEIN!\nDas darf nicht\vsein! Du schlugst\vmeine Besten!\fNach all der Ar-\nbeit, um LIGA-\vChamp zu werden?\fMeine Herrschaft\nendet schon?\vDas ist unfair!",
  ["_RivalVictoryText"] = "Hahaha!\nIch hab gewonnen!\fIch bin zu gut für\ndich, {PLAYER}!\fRespekt, dass du\nbis zu mir kamst,\v{RIVAL}, dem\vPOKéMON-Genie!\fNetter Versuch,\nVerlierer! Hahaha!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ich sah hier ein\nMACHOLLO!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Iiik! Versuch im\nDunkeln ja nichts\vKomisches!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Es\nwar zu dunkel!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Du sahst so nied-\nlich und harmlos\vaus!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "So weit kam ich\nfür POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Meine\nPOKéMON sind alle!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Puh! Jetzt bin\nich verschwitzt!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Du hast POKéMON!\nFangen wir an!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "Du\nspielst hart!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Vorsicht vor ONIX!\nEs kann dich er-\vdrücken!",
  ["_RockTunnel1FHiker1BattleText"] = "Der Tunnel ist\nlang, Kleiner!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Doh!\nDu gewinnst!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Das schlafende\nPOKéMON auf ROUTE\v12 zwang mich zu\vdiesem Umweg.",
  ["_RockTunnel1FHiker2BattleText"] = "Hmm. Vielleicht\nhabe ich mich\vverirrt...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Ruhig! Was mache\nich? Wo geht es\vhier raus?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Du hast Talent\ngenug zum Wandern!",
  ["_RockTunnel1FHiker3BattleText"] = "Fremde wie du\nsollten mir Res-\vpekt erweisen!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Ich gebe auf!",
  ["_RockTunnel1FSignText"] = "FELSTUNNEL\nAZURIA CITY -\vLAVANDIA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Na gut, ich fange\nunterwegs ein\vZUBAT!",
  ["_RockTunnel1FSuperNerdBattleText"] = "POKéMON-Kampf!\nAchtung, los!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Spiel\nvorbei!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Ich will\nnach Hause!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Wanderer legen\nZweige als Weg-\vmarken aus.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "Ohhh! Ich gab\nmein Bestes!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Ich mag kleine\nPOKéMON, große\vsind zu gruselig!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Ich bin selten\nhier, aber kämpfen\vwerde ich!",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nVerloren!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Ich setze auf\nKraft, denn Denken\vhasse ich!",
  ["_RockTunnelB1FHiker1BattleText"] = "Hahaha! Schlägst\ndu meine Kraft?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Ups!\nDu bist stärker!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "In Bergen findet\nman oft POKéMON\vvom Typ GESTEIN.",
  ["_RockTunnelB1FHiker2BattleText"] = "Meine POKéMON-\nTechniken werden\vdich zum Weinen\vbringen!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Ich gebe auf!\nDu bist der bes-\vsere Techniker!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Ich trainiere mei-\nne POKéMON, um\vdich zu schlagen!",
  ["_RockTunnelB1FHiker3BattleText"] = "Zeig mir, was\ndu drauf hast!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Abge-\nschossen!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Wenn dein POKéDEX\nfertig ist, krieg\vich ihn dann?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Du hast einen\nPOKéDEX?\vIch will auch\veinen!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Mist!\nBin ich neidisch!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Kostümspieler ver-\nkleiden sich zum\vSpaß als POKéMON.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Kennst du dich mit\nKostümspielern\vaus?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Tja,\ndas war's dann.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Ich bin Künstler,\nkein Kämpfer.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Zu Hause zeichne\nich POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Puh!\nIch bin erschöpft!",
  ["_RockTunnelPokecenterFisherText"] = "Ich verkaufte ein\nnutzloses NUGGET\vfür ¥5000!",
  ["_RockTunnelPokecenterGentlemanText"] = "Die Elemente der\nPOKéMON machen\vsie stärker als\vmanche Typen und\vschwächer als\vandere!",
  ["_RockTunnelPokecenterGuyText"] = "Angeblich spuken\nGEISTER in\vLAVANDIA!",
  ["_RocketHide3AfterBattleText3"] = "Geh ruhig weiter!\nAber du brauchst\vden LIFTÖFFNER\vfür den Aufzug!",
  ["_RocketHideout3BattleText"] = "Von oben kam die\nNachricht, dass\vdu kommst!",
  ["_RocketHideout3EndBattleText3"] = "Was?\nVerloren? Nein!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Machst du dich\nüber TEAM ROCKET\vlustig?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Wer bist du? Wie\nkamst du hierher?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Autsch!\nBesiegt!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Damit kommst du\nnicht davon,\vBengel!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Du dringst hier\neinfach ein?",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Verbrannt!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "SILPH SCOPE?\nKeine Ahnung,\vwo das ist!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Eindringlings-\nalarm!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Ich\nschaffe es nicht!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, ich rede!\nNimm den Aufzug\vzu meinem BOSS!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Warum bist du\nhergekommen?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Das\ndarf nicht sein!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oje, der Kampf hat\ndie Tür geöffnet!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Hast du dich\nverlaufen, du\vkleine Ratte?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Warum...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "Das TEAM ROCKET-\nHQ hat 4 Keller-\vetagen. Kommst du\vbis zum BOSS?",
  ["_RocketHideoutB2FRocketBattleText"] = "BOSS sagt, mit dem\nSILPH SCOPE sieht\vman GEISTER!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "Ich\ngebe auf!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "SILPH SCOPE?\nDie Maschine, die\vder BOSS stahl.\vSie ist irgendwo\vhier.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Misch dich nicht\nin TEAM ROCKETs\vAngelegenheiten!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Uff!\nErledigt!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Du ziehst deine\nPOKéMON mit viel\vSorgfalt groß.\fEin Kind wie du\nwird nie ver-\vstehen, was ich\verreichen will.\fIch trete diesmal\nbeiseite!\fIch hoffe, wir\nsehen uns\vwieder...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Sieh an! Es ist\nbeachtlich, dass\vdu es bis hierher\vgeschafft hast!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "WAS!\nDas kann nicht\vsein!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Hast du etwas\ngegen TEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Ich kenne dich! Du\nhast unsere Pläne\vam MONDBERG\vvereitelt!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Schon wieder\nverbrannt!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "BOSS! Verzeih,\nich habe versagt!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Wie kannst du die\nSchönheit des\vBösen nicht sehen?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ayaya!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Oh nein! Ich habe\nden LIFTÖFFNER\vverloren!",
  ["_RocketHideoutB4FRocket3BattleText"] = "Der Aufzug geht\nnicht? Wer hat den\vLIFTÖFFNER?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "Nein!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Hier scheint ein\nSchlüssel nötig.",
  ["_RoseText"] = " steigt!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Hier schleichen\nein paar\vPOKéMANIACs herum.",
  ["_Route10CooltrainerF1BattleText"] = "Ich war schon oft\nin POKéMON-ARENEN.\vVerloren habe ich\vjedes Mal.",
  ["_Route10CooltrainerF1EndBattleText"] = "Ohh!\nWieder vermasselt!",
  ["_Route10CooltrainerF2AfterBattleText"] = "Die POKéMON hier\nsind so pummelig!\vEs soll ein rosa\vPOKéMON mit Blu-\vmenmuster geben!",
  ["_Route10CooltrainerF2BattleText"] = "Mir ist ganz\nschwindlig von\vdieser harten\vWanderung.",
  ["_Route10CooltrainerF2EndBattleText"] = "Das\nschaffe ich nicht!",
  ["_Route10Hiker1AfterBattleText"] = "Haha-ha-tschi!\nHa-tschi!\vSchnief! Schnauf!",
  ["_Route10Hiker1BattleText"] = "Ha-hahah-ah-ha!",
  ["_Route10Hiker1EndBattleText"] = "Ha-haha!\nIch lache nicht!\vHa-Heuschnupfen!\vHaha-ha-tschi!",
  ["_Route10Hiker2AfterBattleText"] = "Ich fühle mich\naufgebläht von\vder Bergluft!",
  ["_Route10Hiker2BattleText"] = "Ah! Die Bergluft\nist köstlich!",
  ["_Route10Hiker2EndBattleText"] = "Das\nklärt den Kopf!",
  ["_Route10PowerPlantSignText"] = "KRAFTWERK",
  ["_Route10RockTunnelSignText"] = "FELSTUNNEL",
  ["_Route10SuperNerd1AfterBattleText"] = "Zuhause habe ich\nnoch mehr seltene\vPOKéMON!",
  ["_Route10SuperNerd1BattleText"] = "Wow, bist du auch\nein POKéMANIAC?\vWillst du meine\vSammlung sehen?",
  ["_Route10SuperNerd1EndBattleText"] = "Pff!\nIch bin nicht\vsauer!",
  ["_Route10SuperNerd2AfterBattleText"] = "Ich mag dich\nnicht, du hast\vmich besiegt!",
  ["_Route10SuperNerd2BattleText"] = "Hi Kleiner! Willst\ndu meine POKéMON\vsehen?",
  ["_Route10SuperNerd2EndBattleText"] = "Oh nein!\nMeine POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "DIGDAS HÖHLE",
  ["_Route11Gambler1AfterBattleText"] = "POKéMON ist Leben!\nUnd Leben heisst\vzocken!",
  ["_Route11Gambler1BattleText"] = "Sieg, Pleite oder\nRemis!",
  ["_Route11Gambler1EndBattleText"] = "Autsch!\nNicht mein Tag!",
  ["_Route11Gambler2AfterBattleText"] = "In der POKéMON-\nWelt darf man kein\vFeigling sein!",
  ["_Route11Gambler2BattleText"] = "Wettkampf! Davon\nkriege ich nie\vgenug!",
  ["_Route11Gambler2EndBattleText"] = "Ich hatte\ndoch eine Chance!",
  ["_Route11Gambler3AfterBattleText"] = "Glückssache!\nReines Glück!",
  ["_Route11Gambler3BattleText"] = "Fwahaha! Ich habe\nnoch nie verloren!",
  ["_Route11Gambler3EndBattleText"] = "Meine\nerste Pleite!",
  ["_Route11Gambler4AfterBattleText"] = "Alles nur Glück.\nReine Glückssache.",
  ["_Route11Gambler4BattleText"] = "Ich habe noch nie\ngewonnen...",
  ["_Route11Gambler4EndBattleText"] = "Das war\nabzusehen...",
  ["_Route11Gate1FGuardText"] = "Fängst du viele\nPOKéMON, gehen\vdir die Namen\vaus, was?\fIn LAVANDIA lebt\nein Mann, der\vSpitznamen von\vPOKéMON bewertet.\fEr hilft dir auch\nbeim Umbenennen!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Du blickst durchs\nFernglas.\fWas für eine\nschöne Aussicht!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Du blickst durchs\nFernglas.\fEin großes POKéMON\nschläft auf einem\vWeg!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Es liegen ITEMs\nam Boden, die man\vnicht sehen kann.\fDer ITEMRADAR\nspürt ITEMs in\vdeiner Nähe auf.\fEr zeigt nicht,\nwo genau. Du\vmusst selbst\vsuchen!",
  ["_Route11Gate2FRightBinocularsText"] = "Du blickst durchs\nFernglas.\fVon AZURIA CITY\nnach LAVANDIA\vkommt man nur\vdurch den FELS-\vTUNNEL.",
  ["_Route11SuperNerd1AfterBattleText"] = "Sag es weiter:\nSpart Energie!",
  ["_Route11SuperNerd1BattleText"] = "Vorsicht!\nIch verlege hier\vKabel!",
  ["_Route11SuperNerd1EndBattleText"] = "Das war\nelektrisierend!",
  ["_Route11SuperNerd2AfterBattleText"] = "Na gut, zurück an\ndie Arbeit.",
  ["_Route11SuperNerd2BattleText"] = "Achtung, hier\nsind Stromkabel!",
  ["_Route11SuperNerd2EndBattleText"] = "Wow!\nDu Zündkerze!",
  ["_Route11Youngster1AfterBattleText"] = "Ich gab mein\nBestes! Ich bereue\vnichts!",
  ["_Route11Youngster1BattleText"] = "Los geht's, aber\nnicht schummeln!",
  ["_Route11Youngster1EndBattleText"] = "Häh?\nDas stimmt nicht!",
  ["_Route11Youngster2AfterBattleText5"] = "Was willst du?\nLass mich in Ruhe!",
  ["_Route11Youngster2BattleText"] = "Ich bin gerade\nerst TRAINER! Aber\vich kann gewinnen!",
  ["_Route11Youngster2EndBattleText"] = "Meine POKéMON\nkonnten es nicht!",
  ["_Route11Youngster3AfterBattleText"] = "Ein dickes POKéMON\nkommt manchmal von\vden Bergen runter.\fEs ist stark,\nwenn du es fängst.",
  ["_Route11Youngster3BattleText"] = "Ich bin der Beste\nin meiner Klasse!",
  ["_Route11Youngster3EndBattleText"] = "Mist!\nMeine POKéMON\vmüssen stärker\vwerden!",
  ["_Route11Youngster4AfterBattleText"] = "Ich suche mir\nbesser stärkere!",
  ["_Route11Youngster4BattleText"] = "Meine POKéMON\nsollten jetzt\vbereit sein!",
  ["_Route11Youngster4EndBattleText"] = "Zu viel,\nzu jung!",
  ["_Route12CooltrainerMAfterBattleText"] = "Ein MONDSTEIN\nhätte mein POKéMON\ventwickeln können!",
  ["_Route12CooltrainerMBattleText"] = "Hast du einen\nMONDSTEIN\vgefunden?",
  ["_Route12CooltrainerMEndBattleText"] = "Autsch!",
  ["_Route12Fisher1AfterBattleText"] = "Moment! Meine\nSchnur hängt fest!",
  ["_Route12Fisher1BattleText"] = "Ja! Hier hat\neiner angebissen!",
  ["_Route12Fisher1EndBattleText"] = "Tss!\nNur ein kleiner\vFisch!",
  ["_Route12Fisher2AfterBattleText"] = "Mit einer besseren\nANGEL finge ich\vbessere POKéMON!",
  ["_Route12Fisher2BattleText"] = "Nur Geduld!\nAngeln ist ein\vGeduldsspiel!",
  ["_Route12Fisher2EndBattleText"] = "Der\nist entwischt!",
  ["_Route12Fisher3AfterBattleText"] = "Bei POKéMON bist\ndu besser, aber im\vAngeln bin ich es!",
  ["_Route12Fisher3BattleText"] = "ANGEL-NARR\ngegen POKéMON-KID!",
  ["_Route12Fisher3EndBattleText"] = "Zu\nviel!",
  ["_Route12Fisher4AfterBattleText"] = "Schon gut.\nVerlieren macht\vmir nichts mehr\vaus.",
  ["_Route12Fisher4BattleText"] = "Ich würde lieber\narbeiten!",
  ["_Route12Fisher4EndBattleText"] = "Es ist\nnicht leicht...",
  ["_Route12Fisher5AfterBattleText"] = "Ich fange ständig\nKARPADOR, aber die\vsind so schwach!",
  ["_Route12Fisher5BattleText"] = "Man weiß nie, was\nman fangen könnte!",
  ["_Route12Fisher5EndBattleText"] = "Weg\nist er!",
  ["_Route12Gate1FGuardText"] = "Oben ist ein\nAussichtspunkt.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} erhält\nTM39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "TM39 ist die\nAttacke STERN-\vSCHAUER.\fSie trifft sehr\ngenau. Nutze sie\vin wichtigen\vKämpfen.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Du hast keinen\nPlatz dafür.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Die Asche meines\nPOKéMON ruht im\vPOKéMON-TURM.\fNimm diese TM.\nIch brauche sie\vnicht mehr...",
  ["_Route12Gate2FLeftBinocularsText"] = "Du blickst durchs\nFernglas.\fEin Mann angelt!",
  ["_Route12Gate2FRightBinocularsText"] = "Du blickst durchs\nFernglas.\fDas ist der\nPOKéMON-TURM!",
  ["_Route12SignText"] = "ROUTE 12\nNorden: LAVANDIA",
  ["_Route12SnorlaxCalmedDownText"] = "RELAXO beruhigt\nsich! Mit einem\vGähnen kehrt es\vin die Berge\vzurück!",
  ["_Route12SnorlaxText"] = "Ein schlafendes\nPOKéMON versperrt\vden Weg!",
  ["_Route12SnorlaxWokeUpText"] = "RELAXO wacht auf!\fEs greift voller\nWut an!",
  ["_Route12SportFishingSignText"] = "SPORTANGELGEBIET",
  ["_Route12SuperNerdAfterBattleText"] = "Wasser leitet\nStrom, also gib\vWasser-POKéMON\vStromschläge!",
  ["_Route12SuperNerdBattleText"] = "Elektrizität ist\nmein Fachgebiet!",
  ["_Route12SuperNerdEndBattleText"] = "Stecker gezogen!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Ich bin der Bruder\ndes ANGEL-GURUS!\fIch liiiebe das\nAngeln einfach!\fAngelst du auch\ngern?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\fAngeln ist eine\nLebensart!\fVom Meer bis zum\nFluss, zieh los\vund fang den\vganz Großen!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh nein!\fIch hätte ein\nGeschenk für dich,\vaber du hast\vkeinen Platz!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Großartig! Du\ngefällst mir!\fNimm dies und\nangle, Kleiner!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Wie\nenttäuschend...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Hallo, {PLAYER}!\fNutze die SUPER-\nANGEL an jedem\vGewässer! Du\vfängst so viele\vPOKéMON-Arten.\fVersuch es, wo\nimmer du kannst!",
  ["_Route13Beauty1AfterBattleText"] = "Wer ist wohl\nstärker, männliche\voder weibliche\vPOKéMON?",
  ["_Route13Beauty1BattleText"] = "Klar, ich spiele\nmit dir!",
  ["_Route13Beauty1EndBattleText"] = "Oh!\nDu kleiner Rüpel!",
  ["_Route13Beauty2AfterBattleText"] = "Ich weiß nichts\nüber POKéMON. Ich\vmag einfach die\vcoolen!",
  ["_Route13Beauty2BattleText"] = "Willst du mit mir\nPOKéMONen?",
  ["_Route13Beauty2EndBattleText"] = "Schon\nvorbei?",
  ["_Route13BikerAfterBattleText"] = "Verschwinde!",
  ["_Route13BikerBattleText"] = "Was glotzt\ndu so?",
  ["_Route13BikerEndBattleText"] = "Mist!\nGetriebeschaden!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Ich will eine gute\nTRAINERIN werden.\vIch übe fleißig.",
  ["_Route13CooltrainerF1BattleText"] = "Man sagt, ich sei\ngut für ein Kind!",
  ["_Route13CooltrainerF1EndBattleText"] = "Ohh!\nVerloren!",
  ["_Route13CooltrainerF2AfterBattleText"] = "Die ORDEN hast du\nvon ARENALEITERN.\vIch weiß es!",
  ["_Route13CooltrainerF2BattleText"] = "Wow! Deine ORDEN\nsind zu cool!",
  ["_Route13CooltrainerF2EndBattleText"] = "Nicht\ngenug!",
  ["_Route13CooltrainerF3AfterBattleText"] = "POKéMON müssen\nkämpfen, um hart\vzu werden!",
  ["_Route13CooltrainerF3BattleText"] = "Meine süßen POKé-\nMON möchten dich\vkennenlernen.",
  ["_Route13CooltrainerF3EndBattleText"] = "Wow!\nGlatt gewonnen!",
  ["_Route13CooltrainerF4AfterBattleText"] = "CARBON steigerte\ndas TEMPO meiner\vPOKéMON.",
  ["_Route13CooltrainerF4BattleText"] = "Ich fand CARBON\neinst in einer\vHöhle.",
  ["_Route13CooltrainerF4EndBattleText"] = "Voll\nvermasselt!",
  ["_Route13CooltrainerM1AfterBattleText"] = "Meine POKéMON\nwirken glücklich,\vobwohl sie ver-\vloren haben.",
  ["_Route13CooltrainerM1BattleText"] = "Meine Vogel-\nPOKéMON wollen\vsich prügeln!",
  ["_Route13CooltrainerM1EndBattleText"] = "Mein\nVogel-Team verlor?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Ich bin platt. Ich\nFLIEGE wohl heim.",
  ["_Route13CooltrainerM2BattleText"] = "Der Wind steht\ngünstig für mich!",
  ["_Route13CooltrainerM2EndBattleText"] = "Der Wind\nhat gedreht!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Könnte ich doch\nfliegen wie TAUBSI\vund TAUBOGA...",
  ["_Route13CooltrainerM3BattleText"] = "Ich setze immer\nauf Vogel-POKéMON!",
  ["_Route13CooltrainerM3EndBattleText"] = "Keine\nEnergie mehr!",
  ["_Route13SignText"] = "ROUTE 13\nNorden: SILENCE-\vBRÜCKE",
  ["_Route13TrainerTips1Text"] = "TIPS FÜR TRAINER\fSchau links von\ndiesem Pfosten!",
  ["_Route13TrainerTips2Text"] = "TIPS FÜR TRAINER\fMit SELECT ordnest\ndu ITEMs im ITEM-\vMenü neu!",
  ["_Route14Biker1AfterBattleText"] = "Was, was, was?\nWas willst du?",
  ["_Route14Biker1BattleText"] = "Na komm, na komm.\nLos geht's, los,\vlos, los!",
  ["_Route14Biker1EndBattleText"] = "Arrg! Verloren!\nVerzieh dich!",
  ["_Route14Biker2AfterBattleText"] = "POKéMON aufziehen\nist ätzend, Mann.",
  ["_Route14Biker2BattleText"] = "Perfekt! Ich muss\nZeit totschlagen!",
  ["_Route14Biker2EndBattleText"] = "Was?\nDu!?",
  ["_Route14Biker3AfterBattleText"] = "Cool, dass deine\nPOKéMON so stark\vgeworden sind!\fMacht ist Recht!\nDas weisst du doch!",
  ["_Route14Biker3BattleText"] = "Wir fahren hier\ndraußen, weil es\vmehr Platz gibt!",
  ["_Route14Biker3EndBattleText"] = "Hingelegt!",
  ["_Route14Biker4AfterBattleText"] = "Du weisst, wer ge-\nwinnen würde, du\vund ich, Mann\vgegen Mann!",
  ["_Route14Biker4BattleText"] = "POKéMON-Kampf?\nCool! Rambazamba!",
  ["_Route14Biker4EndBattleText"] = "Weg-\ngeblasen!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Du hast doch VMs?\nPOKéMON können\vdiese Attacken nie\vvergessen.",
  ["_Route14CooltrainerM1BattleText"] = "Bring POKéMON\ngute Attacken mit\vTMs bei!",
  ["_Route14CooltrainerM1EndBattleText"] = "Nicht\ngut genug!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Sie müssen bessere\nAttacken lernen.",
  ["_Route14CooltrainerM2BattleText"] = "Meine Vogel-POKé-\nMON sollten kampf-\vbereit sein.",
  ["_Route14CooltrainerM2EndBattleText"] = "Noch\nnicht bereit!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Attacken vom\ngleichen Typ ma-\vchen dein POKéMON\vnoch stärker.",
  ["_Route14CooltrainerM3BattleText"] = "TMs gibt es in\nPRISMANIA zu kau-\vfen! Aber VMs ha-\vben nur wenige!",
  ["_Route14CooltrainerM3EndBattleText"] = "Och,\nschade!",
  ["_Route14CooltrainerM4AfterBattleText"] = "Vogel-POKéMON\nsind meine große\vLiebe!",
  ["_Route14CooltrainerM4BattleText"] = "Hast du deinen\nVogel-POKéMON\vFLIEGEN beige-\vbracht?",
  ["_Route14CooltrainerM4EndBattleText"] = "In Flammen\nabgestürzt!",
  ["_Route14CooltrainerM5AfterBattleText"] = "Die 3 legendären\nPOKéMON sind alle\vRaubvögel.",
  ["_Route14CooltrainerM5BattleText"] = "Kennst du die\nlegendären\vPOKéMON?",
  ["_Route14CooltrainerM5EndBattleText"] = "Warum?\nWarum verlor ich?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Siegen, verlieren,\nauf Dauer ist es\vegal!",
  ["_Route14CooltrainerM6BattleText"] = "Ich hab keine\nLust, aber gut!\vLos geht's!",
  ["_Route14CooltrainerM6EndBattleText"] = "Ich\nwusste es!",
  ["_Route14SignText"] = "ROUTE 14\nWesten: FUCHSANIA\vCITY",
  ["_Route15Beauty1AfterBattleText"] = "Ich verzeihe dir!\nIch halte das aus!",
  ["_Route15Beauty1BattleText"] = "Oh, du bist ja\nein süßer Fratz!",
  ["_Route15Beauty1EndBattleText"] = "Du sahst auch\nso süß aus!",
  ["_Route15Beauty2AfterBattleText"] = "Ich gehe gern heim\nzu meinen POKéMON!",
  ["_Route15Beauty2BattleText"] = "Ich habe POKéMON,\nweil ich alleine\vlebe!",
  ["_Route15Beauty2EndBattleText"] = "Darum habe ich\nnicht gebeten!",
  ["_Route15Biker1AfterBattleText"] = "Man lebt nur ein-\nmal, drum lebe ich\vals Gesetzloser!\vTEAM ROCKET\vREGIERT!",
  ["_Route15Biker1BattleText"] = "He, Kleiner! Komm!\nDie sind ganz neu!",
  ["_Route15Biker1EndBattleText"] = "Warum\nnicht?",
  ["_Route15Biker2AfterBattleText"] = "Das mit dem Geld\nwar nur ein Witz!",
  ["_Route15Biker2BattleText"] = "Rück dein ganzes\nGeld raus, wenn du\vverlierst, Kind!",
  ["_Route15Biker2EndBattleText"] = "Das\nkann nicht sein!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Den Spitznamen ge-\ntauschter POKéMON\vkannst du nicht\vändern.\fNur der Original-\nTrainer kann das.",
  ["_Route15CooltrainerF1BattleText"] = "Ich teste das\nPOKéMON aus mei-\vnem neuen Tausch!",
  ["_Route15CooltrainerF1EndBattleText"] = "Nicht\ngut genug!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ich habe Angst vor\nROCKERn, die sehen\vhässlich und fies\vaus!",
  ["_Route15CooltrainerF2BattleText"] = "Du siehst sanft\naus, dich kann ich\vwohl besiegen!",
  ["_Route15CooltrainerF2EndBattleText"] = "Nein,\nfalsch!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Ich tausche POKé-\nMON mit meinen\vFreunden!",
  ["_Route15CooltrainerF3BattleText"] = "Was ist cool?\nPOKéMON tauschen!",
  ["_Route15CooltrainerF3EndBattleText"] = "Ich sagte\ntauschen!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Ich trainiere\nkünftig mit\vSchwächeren.",
  ["_Route15CooltrainerF4BattleText"] = "Willst du mit mei-\nnen POKéMON spie-\vlen?",
  ["_Route15CooltrainerF4EndBattleText"] = "Ich war\nzu ungeduldig!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Vielleicht tauge\nich nicht für\vKämpfe.",
  ["_Route15CooltrainerM1BattleText"] = "Wenn ich pfeife,\nkommen Vogel-\vPOKéMON her!",
  ["_Route15CooltrainerM1EndBattleText"] = "Au!\nWie tragisch!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Wusstest du? Atta-\ncken wie ERDBEBEN\vwirken nicht gegen\vVögel.",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? Meine Vögel\nzittern! Du bist\vwohl gut, was?",
  ["_Route15CooltrainerM2EndBattleText"] = "Genau,\nwie ich dachte!",
  ["_Route15Gate1FGuardText"] = "Arbeitest du an\neinem POKéDEX?\fProf. EICHs\nGEHILFE war hier.",
  ["_Route15Gate2FBinocularsText"] = "Du blickst durchs\nFernglas.\fDas sieht wie eine\nkleine Insel aus!",
  ["_Route15Gate2FOaksAideExpAllText"] = "Der EP-ALL gibt\nallen POKéMON bei\vdir EP, auch wenn\vsie nicht kämpfen.\fEr senkt aber die\nEP-Menge für je-\vdes POKéMON.\fBrauchst du ihn\nnicht, lagere ihn\vim PC ein.",
  ["_Route15SignText"] = "ROUTE 15\nWesten: FUCHSANIA\vCITY",
  ["_Route15UpstairsBinocularsText"] = "Du blickst durchs\nFernglas...\fEin großer, glän-\nzender Vogel\vfliegt aufs Meer\vhinaus.",
  ["_Route16Biker1AfterBattleText"] = "Wir hängen hier\nnur rum. Na und?",
  ["_Route16Biker1BattleText"] = "Was willst du?",
  ["_Route16Biker1EndBattleText"] = "Wag es ja nicht\nzu lachen!",
  ["_Route16Biker2AfterBattleText"] = "Vergiss es! Wer\nbraucht schon dein\vRAD!",
  ["_Route16Biker2BattleText"] = "Schickes RAD!\nRück es raus!",
  ["_Route16Biker2EndBattleText"] = "Ausge-\nknockt!",
  ["_Route16Biker3AfterBattleText"] = "Ich hasse Verlie-\nren! Hau bloß ab!",
  ["_Route16Biker3BattleText"] = "Komm raus und\nspiel, Mäuschen!",
  ["_Route16Biker3EndBattleText"] = "Du\nkleine Ratte!",
  ["_Route16Biker4AfterBattleText"] = "Nach FUCHSANIA\nkommst du von ORA-\vNIA auch über eine\vKüstenstraße.",
  ["_Route16Biker4EndBattleText"] = "Kawumm!",
  ["_Route16Biker5AfterBattleText"] = "Meine POKéMON\nsind wild! Sie\vzerfetzen Gegner!",
  ["_Route16Biker5BattleText"] = "Ich bin hungrig\nund gemein!",
  ["_Route16Biker5EndBattleText"] = "Böse,\nböse, böse!",
  ["_Route16Biker6AfterBattleText"] = "Ich schikaniere\ngern Leute mit\vmeinen fiesen\vPOKéMON!",
  ["_Route16Biker6BattleText"] = "Klar, ich bin\ndabei!",
  ["_Route16Biker6EndBattleText"] = "Mach mich\nnicht wütend!",
  ["_Route16CyclingRoadSignText"] = "Freu dich aufs\nGefälle! RADWEG",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "VM02 ist FLIEGEN.\nEs bringt dich in\vjede Stadt zurück.\fSetze es gut ein!",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "Du hast keinen\nPlatz dafür.",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER} erhält\nVM02!",
  ["_Route16FlyHouseBrunetteGirlText"] = "Oh, du hast mein\nVersteck gefunden!\fBitte verrate\nniemandem, dass\vich hier bin.\vDafür bekommst\vdu das hier!",
  ["_Route16FlyHouseFearowText"] = "IBITAK: Kjuiin!",
  ["_Route16Gate1FGamblerText"] = "Wie kamst du rein?\nGut gemacht!",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "Der RADWEG ist ein\nGefällekurs am\vMeer. Eine tolle\vStrecke.",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "Fußgänger sind auf\ndem RADWEG nicht\verlaubt!",
  ["_Route16Gate1FGuardWaitUpText"] = "Entschuldigung!\nBitte warte kurz!",
  ["_Route16Gate2FLeftBinocularsText"] = "Du blickst durchs\nFernglas.\fDas ist das PRIS-\nMANIA KAUFHAUS!",
  ["_Route16Gate2FLittleBoyText"] = "Ich mache eine\nTour mit meiner\vFreundin!",
  ["_Route16Gate2FLittleGirlText"] = "Wir machen zusam-\nmen eine Radtour!",
  ["_Route16Gate2FRightBinocularsText"] = "Du blickst durchs\nFernglas.\fDa ist ein langer\nWeg übers Wasser!",
  ["_Route16SignText"] = "ROUTE 16\nPRISMANIA CITY -\vFUCHSANIA CITY",
  ["_Route16SnorlaxReturnedToMountainsText"] = "Mit einem großen\nGähnen kehrt RE-\vLAXO in die Berge\vzurück!",
  ["_Route16SnorlaxWokeUpText"] = "RELAXO wacht auf!\fEs greift voller\nWut an!",
  ["_Route16Text7"] = "Ein schlafendes\nPOKéMON versperrt\vden Weg!",
  ["_Route16biker4BattleText"] = "He, du hast mich\nangerempelt!",
  ["_Route17Biker10AfterBattleText"] = "Ich brauche ein\nNickerchen!",
  ["_Route17Biker10BattleText"] = "Hau ab, Kleiner!\nIch bin erledigt!",
  ["_Route17Biker10EndBattleText"] = "Bist du jetzt\nzufrieden?",
  ["_Route17Biker1AfterBattleText"] = "Auf dem RADWEG\nliegen gute Sachen\vherum!",
  ["_Route17Biker1BattleText"] = "Kämpfe gegen Kids\nbringen kein Geld!",
  ["_Route17Biker1EndBattleText"] = "Ausge-\nbrannt!",
  ["_Route17Biker2AfterBattleText"] = "Ich könnte dich\nmit dem Bauch\vwegrempeln!",
  ["_Route17Biker2BattleText"] = "Was willst du,\nKleiner?",
  ["_Route17Biker2EndBattleText"] = "Wuhu!",
  ["_Route17Biker3AfterBattleText"] = "Ich liebe es,\nbergab zu rasen!",
  ["_Route17Biker3BattleText"] = "Fährst du nach\nFUCHSANIA?",
  ["_Route17Biker3EndBattleText"] = "Bruch-\nlandung!",
  ["_Route17Biker4AfterBattleText"] = "Suchst du das\nAbenteuer?",
  ["_Route17Biker4BattleText"] = "Wir sind ROCKER!\nHighway-Stars!",
  ["_Route17Biker4EndBattleText"] = "Abgeraucht!",
  ["_Route17Biker5AfterBattleText"] = "Mein VOLTOBAL fing\nich im verlassenen\vKRAFTWERK.",
  ["_Route17Biker5BattleText"] = "Lass dich von VOL-\nTOBAL elektri-\vsieren!",
  ["_Route17Biker5EndBattleText"] = "Geerdet!",
  ["_Route17Biker6AfterBattleText"] = "Manche POKéMON\nbrauchen wohl\vElement-STEINE zur\vEntwicklung.",
  ["_Route17Biker6BattleText"] = "Mein POKéMON will\nsich nicht ent-\vwickeln! Warum?",
  ["_Route17Biker6EndBattleText"] = "Na,\nwarte!",
  ["_Route17Biker7AfterBattleText"] = "Da habe ich sicher\nabgenommen!",
  ["_Route17Biker7BattleText"] = "Ich brauche etwas\nBewegung!",
  ["_Route17Biker7EndBattleText"] = "Puh!\nGutes Training!",
  ["_Route17Biker8AfterBattleText"] = "Sei bereit, für\ndeine Ideale zu\vkämpfen!",
  ["_Route17Biker8BattleText"] = "Sei ein Rebell!",
  ["_Route17Biker8EndBattleText"] = "Aaaargh!",
  ["_Route17Biker9AfterBattleText"] = "Bei dem Gefälle\nlenkt es sich\vschwer!",
  ["_Route17Biker9BattleText"] = "Schickes RAD!\nWie fährt es sich?",
  ["_Route17Biker9EndBattleText"] = "Mist!",
  ["_Route17CyclingRoadEndsSignText"] = "RADWEG\nDas Gefälle endet\vhier!",
  ["_Route17NoticeSign1Text"] = "Ein Hinweis!\fAchte auf wegge-\nworfene ITEMs!",
  ["_Route17NoticeSign2Text"] = "Ein Hinweis!\fWirf nicht das\nHandtuch, wirf\vlieber POKéBÄLLE!",
  ["_Route17SignText"] = "ROUTE 17\nPRISMANIA CITY -\vFUCHSANIA CITY",
  ["_Route17TrainerTips1Text"] = "TIPS FÜR TRAINER\fJedes POKéMON ist\neinzigartig.\fSelbst POKéMON\ngleichen Typs und\vLevels wachsen\vverschieden\vschnell.",
  ["_Route17TrainerTips2Text"] = "TIPS FÜR TRAINER\fHalte Knopf A oder\nB gedrückt, um am\vHang stehen zu\vbleiben.",
  ["_Route18CooltrainerM1AfterBattleText"] = "Hätte ich doch\nein RAD!",
  ["_Route18CooltrainerM1BattleText"] = "Ich durchsuche je-\ndes Grasfeld nach\vneuen POKéMON.",
  ["_Route18CooltrainerM1EndBattleText"] = "Tss!",
  ["_Route18CooltrainerM2AfterBattleText"] = "Am Wochenende\nsammle ich auch\vWasser-POKéMON!",
  ["_Route18CooltrainerM2BattleText"] = "Kurukkuu!\nWie gefällt dir\vmein Vogelruf?",
  ["_Route18CooltrainerM2EndBattleText"] = "Ich musste\ndich ärgern!",
  ["_Route18CooltrainerM3AfterBattleText"] = "Das ist mein Lieb-\nlingsrevier für\vdie POKéMON-Jagd!",
  ["_Route18CooltrainerM3BattleText"] = "Das ist mein Re-\nvier! Verschwinde!",
  ["_Route18CooltrainerM3EndBattleText"] = "Mist!",
  ["_Route18CyclingRoadSignText"] = "RADWEG\nKeine Fußgänger\verlaubt!",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "Der RADWEG geht ab\nhier nur bergauf.",
  ["_Route18Gate1FGuardExcuseMeText"] = "Entschuldigung!",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "Für den RADWEG\nbrauchst du ein\vFAHRRAD!",
  ["_Route18Gate2FLeftBinocularsText"] = "Du blickst durchs\nFernglas.\fALABASTIA liegt\nim Westen!",
  ["_Route18Gate2FRightBinocularsText"] = "Du blickst durchs\nFernglas.\fDort schwimmen\nLeute!",
  ["_Route18SignText"] = "ROUTE 18\nPRISMANIA CITY -\vFUCHSANIA CITY",
  ["_Route19CooltrainerM1AfterBattleText"] = "Danke, Kleiner!\nJetzt kann ich\vschwimmen gehen!",
  ["_Route19CooltrainerM1BattleText"] = "Erst aufwärmen,\ndann schwimmen!",
  ["_Route19CooltrainerM1EndBattleText"] = "Gut\naufgewärmt!",
  ["_Route19CooltrainerM2AfterBattleText"] = "Nimm dich vor\nTENTACHA in Acht!",
  ["_Route19CooltrainerM2BattleText"] = "Warte! Du be-\nkommst noch einen\vHerzinfarkt!",
  ["_Route19CooltrainerM2EndBattleText"] = "Uhh!\nIst das kalt!",
  ["_Route19SignText"] = "SEEROUTE 19\nFUCHSANIA CITY -\vSEESCHAUMINSELN",
  ["_Route19Swimmer1AfterBattleText"] = "Im Schwimmen\nschlage ich sogar\vPOKéMON!",
  ["_Route19Swimmer1BattleText"] = "Ich liebe Schwim-\nmen! Und du?",
  ["_Route19Swimmer1EndBattleText"] = "Bauch-\nklatscher!",
  ["_Route19Swimmer2AfterBattleText"] = "Ich sehe ein paar\nInseln!",
  ["_Route19Swimmer2BattleText"] = "Was liegt hinter\ndem Horizont?",
  ["_Route19Swimmer2EndBattleText"] = "Blub!",
  ["_Route19Swimmer3AfterBattleText"] = "Wasser-POKéMON\nmusst du angeln!",
  ["_Route19Swimmer3BattleText"] = "Ich wollte nach\nPOKéMON tauchen,\vaber es ging\vnicht!",
  ["_Route19Swimmer3EndBattleText"] = "Hilfe!",
  ["_Route19Swimmer4AfterBattleText"] = "Ich blicke aufs\nMeer, um zu ver-\vgessen!",
  ["_Route19Swimmer4BattleText"] = "Ich schaue aufs\nMeer, um zu ver-\vgessen!",
  ["_Route19Swimmer4EndBattleText"] = "Uhh!\nTraumatisch!",
  ["_Route19Swimmer5AfterBattleText"] = "Bis zu den SEE-\nSCHAUMINSELN ist\ves noch weit.",
  ["_Route19Swimmer5BattleText"] = "Oh, dein Gefährt\ngefällt mir! Krieg\vich es, wenn ich\vgewinne?",
  ["_Route19Swimmer5EndBattleText"] = "Oh!\nVerloren!",
  ["_Route19Swimmer6AfterBattleText"] = "Mein Freund wollte\nzu den SEESCHAUM-\vINSELN schwimmen.",
  ["_Route19Swimmer6BattleText"] = "Schwimmen: super!\nSonnenbrand: doof!",
  ["_Route19Swimmer6EndBattleText"] = "Schock!",
  ["_Route19Swimmer7AfterBattleText"] = "Ich habe einen\nKrampf! Blub,\vblub...",
  ["_Route19Swimmer7BattleText"] = "Diese Gewässer\nsind tückisch!",
  ["_Route19Swimmer7EndBattleText"] = "Uhh!\nGefährlich!",
  ["_Route19Swimmer8AfterBattleText"] = "LAPRAS ist so\ngroß, auf ihm\vbleibt man sicher\vtrocken.",
  ["_Route19Swimmer8BattleText"] = "Ich bin herge-\nschwommen und\vjetzt müde.",
  ["_Route19Swimmer8EndBattleText"] = "Ich bin\nerschöpft...",
  ["_Route1SignText"] = "ROUTE 1\nALABASTIA -\vVERTANIA CITY",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "Wir führen auch\nPOKéBÄLLE zum\vFangen von\vPOKéMON!",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_Route1Youngster1MartSampleText"] = "Hi! Ich arbeite in\neinem POKéMON-\vMARKT.\fEin praktischer\nLaden. Besuche uns\vin VERTANIA CITY.\fWeisst du was? Hier\nhast du eine\vGratisprobe!",
  ["_Route1Youngster1NoRoomText"] = "Du trägst zu viele\nSachen mit dir!",
  ["_Route1Youngster2Text"] = "Siehst du die Ab-\nsätze am Weg?\fEs kostet etwas\nMut, aber man kann\vhinunterspringen.\fSo bist du schnel-\nler zurück in\vALABASTIA.",
  ["_Route20CooltrainerMAfterBattleText"] = "Meine Vögel können\nmich nicht zurück-\vFLIEGEN!",
  ["_Route20CooltrainerMBattleText"] = "Ich ritt auf mei-\nnem Vogel-POKéMON\vher!",
  ["_Route20CooltrainerMEndBattleText"] = "Oh\nnein!",
  ["_Route20SeafoamIslandsSignText"] = "SEESCHAUMINSELN",
  ["_Route20Swimmer1AfterBattleText"] = "Könnte ich doch\nauf meinem POKéMON\vreiten.",
  ["_Route20Swimmer1BattleText"] = "Das Wasser ist\nhier seicht.",
  ["_Route20Swimmer1EndBattleText"] = "Platsch!",
  ["_Route20Swimmer2AfterBattleText"] = "Unter dieser Insel\nliegt eine riesige\vHöhle.",
  ["_Route20Swimmer2BattleText"] = "SEESCHAUM ist ein\nruhiger Zufluchts-\vort!",
  ["_Route20Swimmer2EndBattleText"] = "Hör auf!",
  ["_Route20Swimmer3AfterBattleText"] = "Willst du mit mir\ntreiben?",
  ["_Route20Swimmer3BattleText"] = "Ich treibe gern\nmit den Fischen!",
  ["_Route20Swimmer3EndBattleText"] = "Autsch!",
  ["_Route20Swimmer4AfterBattleText"] = "SEESCHAUM war\nfrüher eine ein-\vzige Insel!",
  ["_Route20Swimmer4BattleText"] = "Machst du auch\nUrlaub?",
  ["_Route20Swimmer4EndBattleText"] = "Gar kein\nErbarmen!",
  ["_Route20Swimmer5AfterBattleText"] = "Ich hätte meine\nPOKéMON stählen\vsollen statt mich!",
  ["_Route20Swimmer5BattleText"] = "Bewundere meinen\nstählernen Körper!",
  ["_Route20Swimmer5EndBattleText"] = "Schwächling!",
  ["_Route20Swimmer6AfterBattleText"] = "Auf POKéMON reiten\nsieht spaßig aus!",
  ["_Route20Swimmer6BattleText"] = "Warum reitest du\nauf einem POKéMON?\vKannst du nicht\vschwimmen?",
  ["_Route20Swimmer6EndBattleText"] = "Autsch!\nTorpediert!",
  ["_Route20Swimmer7AfterBattleText"] = "Werden meine Per-\nlen in AUSTOS wohl\vgrößer?",
  ["_Route20Swimmer7BattleText"] = "Mein Freund gab\nmir große Perlen!",
  ["_Route20Swimmer7EndBattleText"] = "Finger weg\nvon meinen Perlen!",
  ["_Route20Swimmer8AfterBattleText"] = "POKéMON haben eine\nverlassene Villa\vauf der ZINNOBER-\vINSEL besetzt!",
  ["_Route20Swimmer8BattleText"] = "Ich bin von der\nZINNOBERINSEL\vhergeschwommen!",
  ["_Route20Swimmer8EndBattleText"] = "Ich bin\nso enttäuscht!",
  ["_Route20Swimmer9AfterBattleText"] = "ZINNOBER ist eine\nVulkaninsel!",
  ["_Route20Swimmer9BattleText"] = "Auf ZINNOBER im\nWesten gibt es ein\vPOKéMON-LABOR.",
  ["_Route20Swimmer9EndBattleText"] = "Warte!",
  ["_Route21Fisher1AfterBattleText"] = "Ich fange nichts\nGescheites!",
  ["_Route21Fisher1BattleText"] = "Du willst wissen,\nob die Fische an-\vbeißen?",
  ["_Route21Fisher1EndBattleText"] = "Mist!",
  ["_Route21Fisher2AfterBattleText"] = "Ich fange anschei-\nnend nur KARPADOR!",
  ["_Route21Fisher2BattleText"] = "Was für ein Fang!\nWillst du es auch\vversuchen?",
  ["_Route21Fisher2EndBattleText"] = "Blödes\nKARPADOR!",
  ["_Route21Fisher3AfterBattleText"] = "Ich war nur sauer,\nweil ich nichts\vgefangen habe.",
  ["_Route21Fisher3BattleText"] = "He, verscheuch\nnicht die Fische!",
  ["_Route21Fisher3EndBattleText"] = "Tut mir leid!\nWar keine Absicht!",
  ["_Route21Fisher4AfterBattleText"] = "Oh, warte! Es hat\neiner angebissen!",
  ["_Route21Fisher4BattleText"] = "Leiste mir Gesell-\nschaft, bis einer\vanbeisst!",
  ["_Route21Fisher4EndBattleText"] = "Das\nvertrieb die Zeit.",
  ["_Route21Swimmer1AfterBattleText"] = "Ich mag die\nBerge auch!",
  ["_Route21Swimmer1BattleText"] = "Das Meer reinigt\nKörper und Seele!",
  ["_Route21Swimmer1EndBattleText"] = "Ayah!",
  ["_Route21Swimmer2AfterBattleText"] = "Ich sehe aus wie\nwas? Ein genoppter\vSchwimmreifen?\vVerzieh dich!",
  ["_Route21Swimmer2BattleText"] = "Was ist falsch\ndaran, dass ich\vschwimme?",
  ["_Route21Swimmer2EndBattleText"] = "Fieser\nTrick!",
  ["_Route21Swimmer3AfterBattleText"] = "Wo hast du deine\nPOKéMON gefangen?",
  ["_Route21Swimmer3BattleText"] = "Ich fing all meine\nPOKéMON im Meer!",
  ["_Route21Swimmer3EndBattleText"] = "Taucher!!\nAbtauchen!!",
  ["_Route21Swimmer4AfterBattleText"] = "Ich bin platt!\nAber Radrennen und\vMarathon stehen\vnoch aus!",
  ["_Route21Swimmer4BattleText"] = "Ich bin mitten in\neinem Triathlon!",
  ["_Route21Swimmer4EndBattleText"] = "Keuch...\nkeuch... keuch...",
  ["_Route21Swimmer5AfterBattleText"] = "Die Sonne hat mich\nkross gebraten!",
  ["_Route21Swimmer5BattleText"] = "Ahh! Spür die\nSonne und den\vWind!",
  ["_Route21Swimmer5EndBattleText"] = "Autsch!\nVerloren!",
  ["_Route22GateGuardGoRightAheadText"] = "Oh! Das ist der\nFELSORDEN!\vGeh nur weiter!",
  ["_Route22GateGuardICantLetYouPassText"] = "\fRegeln sind\nRegeln. Ich kann\vdich nicht durch-\vlassen.",
  ["_Route22GateGuardNoBoulderbadgeText"] = "Nur wirklich gute\nTRAINER dürfen\vhier durch.\fDu hast den FELS-\nORDEN noch nicht!",
  ["_Route22PokemonLeagueSignText"] = "POKéMON-LIGA\nHaupttor",
  ["_Route22Rival1DefeatedText"] = "Menno!\nDu hattest nur\vGlück!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Was?\nWieso habe ich 2\vPOKéMON?\fFang dir auch\nnoch mehr!",
  ["_Route22Rival2DefeatedText"] = "Was!?\fIch war nur\nunachtsam!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! Das ist\valles? Du bist\vlange nicht so\vgut wie ich!\fGeh trainieren!\nDu Loser!",
  ["_Route22RivalAfterBattleText1"] = "Die POKéMON-LIGA\nhat viele starke\vTRAINER, heisst es!\fIch muss mir was\nüberlegen, um an\vihnen vorbei-\vzukommen!\fTrödel nicht rum,\nstreng dich an!",
  ["_Route22RivalAfterBattleText2"] = "Das hat mich ge-\nlockert! Bereit\vfür die POKéMON-\vLIGA!\f{PLAYER}, du\nbrauchst mehr\vÜbung!\fAber he, das weisst\ndu ja! Ich bin\vweg. Man riecht\vsich!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: He!\n{PLAYER}!\fDu willst zur\nPOKéMON-LIGA?\fVergiss es! Du\nhast doch sicher\vkeine ORDEN!\fDie Wache lässt\ndich nicht durch!\fSind deine POKé-\nMON übrigens\vstärker geworden?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Was?\n{PLAYER}! Dass ich\vdich hier treffe!\fDu willst also zur\nPOKéMON-LIGA?\fDu hast auch alle\nORDEN gesammelt?\vNicht schlecht!\fDann verhaue ich\ndich, {PLAYER}, als\vAufwärmtraining\vfür die LIGA!\fKomm schon!",
  ["_Route23GoRightAheadText"] = "\fNa gut! Bitte,\ngeh nur weiter!",
  ["_Route23OhThatIsTheBadgeText"] = "Du darfst hier nur\ndurch, wenn du den\v{RAM:wNameBuffer} hast!\fOh! Das ist ja der\n{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "SIEGESSTRASSE-TOR\n- POKéMON-LIGA",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Du darfst hier nur\ndurch, wenn du den\v{RAM:wNameBuffer} hast!\fDu hast den\n{RAM:wNameBuffer}\vnoch nicht!\fOhne ihn kommst du\nnicht zur POKéMON-\vLIGA!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Ich gab mein Bes-\ntes und bereue\vnichts!",
  ["_Route24CooltrainerF1BattleText"] = "Ich bin die Nr. 4!\nSchon müde?",
  ["_Route24CooltrainerF1EndBattleText"] = "Ich habe auch\nverloren!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Ich gab alles,\nich bereue nichts!",
  ["_Route24CooltrainerF2BattleText"] = "Ich bin Nummer 2!\nNun wird es ernst!",
  ["_Route24CooltrainerF2EndBattleText"] = "Wie konnte ich\nverlieren?",
  ["_Route24CooltrainerM1DefeatedText"] = "Argh!\nDu bist gut!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "Sag mal, willst\ndu nicht TEAM\vROCKET beitreten?\fWir sind eine\nBande, die Böses\vmit POKéMON tut!\fWillst du dabei\nsein?\fBist du sicher?\fKomm, mach mit!\fIch sage, du\nsollst beitreten!\fOK, du brauchst\nÜberzeugung!\fIch mache dir ein\nAngebot, das du\vnicht ablehnst!",
  ["_Route24CooltrainerM1NoRoomText"] = "Du hast keinen\nPlatz mehr!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} erhält\nein {RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Glückwunsch!\nDu hast unsere 5\vTRAINER besiegt!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Mit deinem Talent\nkönntest du bei\vTEAM ROCKET ganz\vgroß rauskommen!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\fDu gewinnst einen\ntollen Preis!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Die Leute auf der\nBrücke haben mir\vAngst gemacht!",
  ["_Route24CooltrainerM2BattleText"] = "Ich sah deine Tat\nvom Gras aus!",
  ["_Route24CooltrainerM2EndBattleText"] = "Das\ndachte ich mir!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ich gab alles,\nich bereue nichts!",
  ["_Route24CooltrainerM3BattleText"] = "OK! Ich bin Nr.5!\nIch mach dich\vplatt!",
  ["_Route24CooltrainerM3EndBattleText"] = "Wow!\nZu stark!",
  ["_Route24Youngster1AfterBattleText"] = "Ich gab alles,\nich bereue nichts!",
  ["_Route24Youngster1BattleText"] = "Hier ist Nr.3!\nIch bin nicht\vleicht zu packen!",
  ["_Route24Youngster1EndBattleText"] = "Autsch!\nPlattgemacht!",
  ["_Route24Youngster2AfterBattleText"] = "Ich gab alles,\nich bereue nichts!",
  ["_Route24Youngster2BattleText"] = "Das ist die\nNUGGETBRÜCKE!\vBesiege uns 5\vTRAINER und du\vgewinnst einen\vtollen Preis!\fHast du das Zeug\ndazu?",
  ["_Route24Youngster2EndBattleText"] = "Wow!\nStarke Sache!",
  ["_Route25BillSignText"] = "STRANDHAUS\nHier wohnt BILL!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Wäre mein Freund\ndoch so gut wie\vdu!",
  ["_Route25CooltrainerF1BattleText"] = "Hi! Mein Freund\nist cool!",
  ["_Route25CooltrainerF1EndBattleText"] = "Ich war nicht\nin Form!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Du kommst vom\nMONDBERG? Krieg\vich ein PIEPI?",
  ["_Route25CooltrainerF2BattleText"] = "Meine Freundin\nhat ein süßes\vPOKéMON. Ich bin\vso neidisch!",
  ["_Route25CooltrainerF2EndBattleText"] = "Jetzt bin ich\nweniger neidisch!",
  ["_Route25CooltrainerMAfterBattleText"] = "Na ja. Meine\nFreundin tröstet\vmich schon.",
  ["_Route25CooltrainerMBattleText"] = "Ich bin cool.\nIch habe eine\vFreundin!",
  ["_Route25CooltrainerMEndBattleText"] = "Ach,\nMist...",
  ["_Route25Hiker1AfterBattleText"] = "Mist! Ein ZUBAT\nhat mich da\vdrin gebissen.",
  ["_Route25Hiker1BattleText"] = "Ich komme gerade\nvom MONDBERG,\vaber ich bin\vbereit!",
  ["_Route25Hiker1EndBattleText"] = "Du hast dich\nangestrengt!",
  ["_Route25Hiker2AfterBattleText"] = "Der Sammler hat\nviele seltene\vPOKéMON.",
  ["_Route25Hiker2BattleText"] = "Ich besuche einen\nPOKéMON-Sammler\vam Kap!",
  ["_Route25Hiker2EndBattleText"] = "Du hast\nmich erwischt.",
  ["_Route25Hiker3AfterBattleText"] = "Der Pfad unten\nist eine Abkürzung\vnach AZURIA CITY.",
  ["_Route25Hiker3BattleText"] = "Du willst zu\nBILL? Erst wird\vgekämpft!",
  ["_Route25Hiker3EndBattleText"] = "Du bist\nnicht übel.",
  ["_Route25Youngster1AfterBattleText"] = "Alle POKéMON\nhaben Schwächen.\vTrainiere am\vbesten viele\vverschiedene!",
  ["_Route25Youngster1BattleText"] = "Hiesige TRAINER\nkommen zum Üben\vher!",
  ["_Route25Youngster1EndBattleText"] = "Du bist\nganz passabel.",
  ["_Route25Youngster2AfterBattleText"] = "Auf der M.S.ANNE\nsah ich TRAINER\vaus aller Welt.",
  ["_Route25Youngster2BattleText"] = "Papa nahm mich\nzur Party auf der\vM.S.ANNE in\vORANIA CITY mit!",
  ["_Route25Youngster2EndBattleText"] = "Ich bin\nnicht sauer!",
  ["_Route25Youngster3AfterBattleText"] = "Ist dein POKéMON\nverwirrt oder\vschläft es,\vwechsle es aus!",
  ["_Route25Youngster3BattleText"] = "Ich wusste, dass\nwir kämpfen\vwürden!",
  ["_Route25Youngster3EndBattleText"] = "Ich wusste auch,\ndass ich verliere!",
  ["_Route2DiglettsCaveSignText"] = "DIGDAS HÖHLE",
  ["_Route2GateOaksAideFlashExplanationText"] = "Die VM BLITZ\nerhellt selbst\vdunkelste Höhlen.",
  ["_Route2GateYoungsterText"] = "Kann ein POKéMON\nBLITZ, kommst du\vdurch den\vFELSTUNNEL.",
  ["_Route2SignText"] = "ROUTE 2\nVERTANIA CITY -\vMARMORIA CITY",
  ["_Route2TradeHouseScientistText"] = "Ein besiegtes\nPOKéMON kann\vnicht kämpfen,\vaber noch Attacken\vwie ZERSCHNEIDER\vnutzen!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Starre nicht, wenn\ndu nicht kämpfen\vwillst!",
  ["_Route3CooltrainerF1BattleText"] = "Du hast mich\nangesehen, oder?",
  ["_Route3CooltrainerF1EndBattleText"] = "Du bist\ngemein!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Vermeide Kämpfe,\nindem du dich\vnicht sehen lässt!",
  ["_Route3CooltrainerF2BattleText"] = "Dein Blick eben,\nwie aufregend!",
  ["_Route3CooltrainerF2EndBattleText"] = "Sei nett!",
  ["_Route3CooltrainerF3AfterBattleText"] = "ROUTE 4 liegt am\nFuß des MONDBERGS.",
  ["_Route3CooltrainerF3BattleText"] = "Iiih! Hast du\nmich angefasst?",
  ["_Route3CooltrainerF3EndBattleText"] = "Das war's?",
  ["_Route3SignText"] = "ROUTE 3\nZUM MONDBERG",
  ["_Route3Text1"] = "Puh... Ich muss\nmich ausruhen...\vÄchz...\fDer Tunnel von\nAZURIA schlaucht\vganz schön!",
  ["_Route3Youngster1AfterBattleText"] = "Es gibt noch mehr\nPOKéMON als die\vim Wald!",
  ["_Route3Youngster1BattleText"] = "He! Wir trafen uns\nim VERTANIA WALD!",
  ["_Route3Youngster1EndBattleText"] = "Schon wieder\nverloren!",
  ["_Route3Youngster2AfterBattleText"] = "Lagerst du POKéMON\nauf dem PC? Jede\vBOX fasst 20\vPOKéMON!",
  ["_Route3Youngster2BattleText"] = "Hi! Ich mag kurze\nHosen! Bequem und\vluftig!",
  ["_Route3Youngster2EndBattleText"] = "Das glaube\nich nicht!",
  ["_Route3Youngster3AfterBattleText"] = "Ist eine BOX auf\ndem PC voll,\vwechsle einfach\vdie BOX!",
  ["_Route3Youngster3BattleText"] = "Bist du TRAINER?\nLass uns kämpfen!",
  ["_Route3Youngster3EndBattleText"] = "Mit neuen POKéMON\nhätte ich\vgewonnen!",
  ["_Route3Youngster4AfterBattleText"] = "Ich trage immer\nkurze Hosen, auch\vim Winter!",
  ["_Route3Youngster4BattleText"] = "He! Du trägst ja\ngar keine kurzen\vHosen!",
  ["_Route3Youngster4EndBattleText"] = "Verloren!\nVerloren!",
  ["_Route3Youngster5AfterBattleText"] = "Trainierte POKéMON\nsind stärker als\vwilde!",
  ["_Route3Youngster5BattleText"] = "Kämpfe gegen meine\nneuen POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "Ich bin\ngeliefert!",
  ["_Route4CooltrainerF1Text"] = "Autsch! Ich\nstolperte über\vein steinhartes\vKLEINSTEIN!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Hier gibt es wohl\nkeine Pilze mehr.\fIch glaube, ich\nhabe alle.",
  ["_Route4CooltrainerF2BattleText"] = "Ich hole mir mein\nPilz-POKéMON!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh! Mein süßes\nPilz-POKéMON!",
  ["_Route4MtMoonSignText"] = "MONDBERG\nTunneleingang",
  ["_Route4SignText"] = "ROUTE 4\nMONDBERG -\vAZURIA CITY",
  ["_Route5UndergroundPathSignText"] = "UNTERGRUNDWEG\nAZURIA CITY -\vORANIA CITY",
  ["_Route6CooltrainerAfterBattleText"] = "Flüster...\nflüster...",
  ["_Route6CooltrainerF1BattleText"] = "Verzeihung! Das\nist ein privates\vGespräch!",
  ["_Route6CooltrainerF1EndBattleText"] = "Argh! Ich hasse\nes zu verlieren!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Ich will stärker\nwerden! Was ist\vdein Geheimnis?",
  ["_Route6CooltrainerF2BattleText"] = "Ich? Na gut.\nIch spiele mit!",
  ["_Route6CooltrainerF2EndBattleText"] = "Es hat einfach\nnicht geklappt!",
  ["_Route6CooltrainerM1BattleText"] = "Wer ist da? Hör\nauf zu lauschen!",
  ["_Route6CooltrainerM1EndBattleText"] = "Ich kann einfach\nnicht gewinnen!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Zur Sicherheit\nsollte ich mehr\vPOKéMON mitnehmen.",
  ["_Route6CooltrainerM2BattleText"] = "Hm? Du willst mit\nmir reden?",
  ["_Route6CooltrainerM2EndBattleText"] = "Ich habe nicht\nangefangen!",
  ["_Route6UndergroundPathSignText"] = "UNTERGRUNDWEG\nAZURIA CITY -\vORANIA CITY",
  ["_Route6Youngster1AfterBattleText"] = "Ich mag Käfer,\nalso gehe ich in\vden VERTANIA WALD\vzurück.",
  ["_Route6Youngster1BattleText"] = "Hier gibt es kaum\nKäfer.",
  ["_Route6Youngster1EndBattleText"] = "Nein!\nDas gibt's nicht!",
  ["_Route6Youngster2AfterBattleText"] = "Sind meine POKéMON\nschwach? Oder bin\vich nur schlecht?",
  ["_Route6Youngster2BattleText"] = "Dich habe ich hier\nnie gesehen!\vBist du gut?",
  ["_Route6Youngster2EndBattleText"] = "Du bist\nzu gut!",
  ["_Route7UndergroundPathSignText"] = "UNTERGRUNDWEG\nPRISMANIA CITY -\vLAVANDIA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Ausgewachsene\nPOKéMON werden\vhässlich! Sie\vsollten sich nicht\ventwickeln!",
  ["_Route8CooltrainerF1BattleText"] = "Ich mag NIDORAN,\nalso sammle ich\vsie!",
  ["_Route8CooltrainerF1EndBattleText"] = "Warum? Warum??",
  ["_Route8CooltrainerF2AfterBattleText"] = "Ich finde TAUBSI\nund RATTFRATZ\vauch süß!",
  ["_Route8CooltrainerF2BattleText"] = "MAUZI ist so süß,\nmiau, miau, miau!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miau!",
  ["_Route8CooltrainerF3AfterBattleText"] = "Der Wächter von\nSAFFRONIA lässt\vuns nicht durch.\vSo gemein!",
  ["_Route8CooltrainerF3BattleText"] = "Wir sehen sicher\nalbern aus, wie\vwir hier stehen!",
  ["_Route8CooltrainerF3EndBattleText"] = "Sieh nur, was du\nangerichtet hast!",
  ["_Route8CooltrainerF4AfterBattleText"] = "PIEPI entwickelt\nsich angeblich\vdurch einen\vMONDSTEIN.",
  ["_Route8CooltrainerF4BattleText"] = "Welches POKéMON\nist süß, rund\vund flauschig?",
  ["_Route8CooltrainerF4EndBattleText"] = "Halt!\fSei nicht so fies\nzu meinem PIEPI!",
  ["_Route8Gambler1AfterBattleText"] = "Fortuna ist heute\nnicht mit mir!",
  ["_Route8Gambler1BattleText"] = "Also gut! Lass die\nWürfel rollen!",
  ["_Route8Gambler1EndBattleText"] = "Mist! Knapp\ndaneben!",
  ["_Route8Gambler2AfterBattleText"] = "Zocken und POKéMON\nsind wie Erdnüsse!\vMan kann nicht\vaufhören!",
  ["_Route8Gambler2BattleText"] = "Ich bin ein\nzockender\vVagabund!",
  ["_Route8Gambler2EndBattleText"] = "Der große Coup\nist geplatzt!",
  ["_Route8SuperNerd1AfterBattleText"] = "In der Schule bin\nich besser als\vhier!",
  ["_Route8SuperNerd1BattleText"] = "In POKéMON bist du\ngut, aber wie\vsteht's in Chemie?",
  ["_Route8SuperNerd1EndBattleText"] = "Autsch!\nKernschmelze!",
  ["_Route8SuperNerd2AfterBattleText"] = "Erst SLEIMA\nund...\vund... dann...",
  ["_Route8SuperNerd2BattleText"] = "Hier gewinnt man\nnur mit Strategie!",
  ["_Route8SuperNerd2EndBattleText"] = "Das ist\nunlogisch!",
  ["_Route8SuperNerd3AfterBattleText"] = "Wegen der Tore von\nSAFFRONIA sitzen\vwir hier fest.",
  ["_Route8SuperNerd3BattleText"] = "Schule macht Spaß,\nPOKéMON aber auch.",
  ["_Route8SuperNerd3EndBattleText"] = "Ich bleibe bei\nder Schule.",
  ["_Route8UndergroundSignText"] = "UNTERGRUNDWEG\nPRISMANIA CITY -\vLAVANDIA",
  ["_Route9CooltrainerF1AfterBattleText"] = "Du brauchst Licht,\num durch den\vdunklen Tunnel zu\vkommen.",
  ["_Route9CooltrainerF1BattleText"] = "Du hast POKéMON\ndabei! Du gehörst\vmir!",
  ["_Route9CooltrainerF1EndBattleText"] = "Du hast mich\ngetäuscht!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Du hast wirklich\nTalent! Viel\vGlück noch!",
  ["_Route9CooltrainerF2BattleText"] = "Sieh ja nicht auf\nmich herab!",
  ["_Route9CooltrainerF2EndBattleText"] = "Nein! Du bist\nzu stark!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Geh weiter!",
  ["_Route9CooltrainerM1BattleText"] = "Wer läuft denn da\nmit so schicken\vPOKéMON herum?",
  ["_Route9CooltrainerM1EndBattleText"] = "Ausgeknipst!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Willst du auch zum\nFELSTUNNEL?",
  ["_Route9CooltrainerM2BattleText"] = "Ich gehe durch den\nFELSTUNNEL nach\vLAVANDIA...",
  ["_Route9CooltrainerM2EndBattleText"] = "Ich kann nicht\nmithalten!",
  ["_Route9Hiker1AfterBattleText"] = "Du hattest echt\nMumm, dich mir zu\vstellen, was?",
  ["_Route9Hiker1BattleText"] = "Bwahaha! Prima!\nMir war eh\vlangweilig!",
  ["_Route9Hiker1EndBattleText"] = "Immer weiter so!\fOh, warte. Meine\nPOKéMON sind alle!",
  ["_Route9Hiker2AfterBattleText"] = "Hahaha! Kinder\nmüssen zäh sein!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nDu bist mir ein\vzäher Knirps!",
  ["_Route9Hiker2EndBattleText"] = "Was\nsoll das?",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nWir Naturburschen\vlachen immer!",
  ["_Route9Hiker3BattleText"] = "Hahahaha!\nKomm schon, Junge!",
  ["_Route9Hiker3EndBattleText"] = "Hahahaha! Du hast\nfair gewonnen!",
  ["_Route9SignText"] = "ROUTE 9\nAZURIA CITY -\vFELSTUNNEL",
  ["_Route9Youngster1AfterBattleText"] = "Ich muss mehr als\nKäfer sammeln, um\vstärker zu\vwerden...",
  ["_Route9Youngster1BattleText"] = "Ich stand täglich\nfrüh auf, um meine\vKokon-POKéMON\vaufzuziehen!",
  ["_Route9Youngster1EndBattleText"] = "WAS?\fAlles reine\nZeitverschwendung!",
  ["_Route9Youngster2AfterBattleText"] = "Wer Käfer-POKéMON\nnicht mag, der\vnervt mich!",
  ["_Route9Youngster2BattleText"] = "Los, meine Super-\nKäfer-POKéMON!",
  ["_Route9Youngster2EndBattleText"] = "Meine\nKäfer...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Du hast meine\narmen POKéMON\vverletzt!\fBring sie sofort\nin ein POKéMON-\vCENTER!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Diese POKéMON habe\nich in aller Welt\vgesammelt!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Oh nein! Dafür\nreiste ich um die\vganze Welt!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Sei nett zu\ndeinen Freunden!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Ich reise immer\nallein!\fMeine POKéMON sind\nmeine einzigen\vFreunde!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Meine, meine\nFreunde...",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Ich will allein\nsein! Raus!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Du Frechdachs! Wie\nkannst du hier\veindringen!",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Hmpf! Du\nfreches Kind!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Psst! Ich bin von\nder INTERPOL!\fIch bin TEAM\nROCKET auf der\vSpur!",
  ["_SSAnne1FRoomsGirl1Text"] = "Herr Ober, einmal\nKirschkuchen,\vbitte!",
  ["_SSAnne1FRoomsGirl2Text"] = "Wir machen eine\nWeltkreuzfahrt.",
  ["_SSAnne1FRoomsLittleGirlText"] = "Ich reise immer\nmit KNUDDELUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Eine Kreuzfahrt\nist elegant und\vgemütlich!",
  ["_SSAnne1FRoomsWigglytuffText"] = "KNUDDELUFF: Puup\npupuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Lass uns Freunde\nsein, OK?\fDann können wir\nPOKéMON tauschen!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Ich liebe POKéMON!\nDu auch?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow!\nDu bist klasse!",
  ["_SSAnne1FSailorText"] = "Die Passagiere\nsind unruhig!\fDie Gelangweilten\nfordern dich\vsicher heraus!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Isch bin\nle Kellner auf\vdiesem Schiff!\fIsch serviere\nIhnen gern alles,\vwas Sie wünschen!\fAh! Le starker,\nstiller Typ!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Ich hörte,\nein ZERSCHNEIDER-\vMeister sei an\vBord.\fAber er ist nur\nein seekranker,\valter Mann!\fZERSCHNEIDER an\nsich ist aber sehr\vnützlich!\fBesuch ihn mal!\nMan riecht sich!",
  ["_SSAnne2FRivalDefeatedText"] = "Hmpf!\fImmerhin ziehst du\ndeine POKéMON auf!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Bonjour!\n{PLAYER}!\fDass ich dich hier\ntreffe!\f{PLAYER}, bist du\nauch eingeladen?\fWie läuft's mit\ndeinem POKéDEX?\fIch habe schon 40\nArten gefangen!\fÜberall gibt es\nandere Arten!\fKrieche durch\nGrasflächen!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Bist du\netwa seekrank?\fReiß dich mal\nzusammen!",
  ["_SSAnne2FRoomsBeautyText"] = "Viele Leute werden\nwohl seekrank!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Der KAPITÄN sah\nrichtig krank und\vblass aus!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh, ich bewundere\ndeine starken\vPOKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Dich habe ich auf\nder Party nicht\vgesehen.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Immer mit\nder Ruhe!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Party?\fDie Party müsste\ninzwischen vorbei\vsein.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Sieh her, was ich\ngeangelt habe!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "Ich bin\nfertig!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "Vor 15 Jahren\nhätte ich\vgewonnen!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Der Wettstreit mit\nder Jugend hält\vmich jung.",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Guter Kampf! Ich\nfühle mich wieder\vjung!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Ich bevorzuge\nstarke und seltene\vPOKéMON.",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Was magst du mehr,\nstarke oder\vseltene POKéMON?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Hut ab\nvor dir!",
  ["_SSAnne2FRoomsGentleman3Text"] = "Auf all meinen\nReisen sah ich nie\vein POKéMON so\vschlafen wie\vdieses!\fEs war ungefähr\nso!",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ach ja, ich sah\nPOKéMON, die Leute\vübers Wasser\vtragen!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Warst du schon in\nder SAFARI-ZONE\vin FUCHSANIA CITY?\fDort gibt es viele\nseltene POKéMON!!",
  ["_SSAnne2FRoomsGrampsText"] = "Mit ZERSCHNEIDER\nfällen POKéMON\vkleine Büsche.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Papa und ich\nfinden die SAFARI-\vZONE spitze!",
  ["_SSAnne2FWaiterText"] = "Dieses Schiff ist\nein Luxusliner\vfür TRAINER!\fIn jedem Hafen\nfeiern wir Partys\vmit geladenen\vTRAINERN!",
  ["_SSAnne3FSailorText"] = "Unser KAPITÄN\nist ein Meister\vdes Schwerts!\fEr lehrt POKéMON\nsogar\vZERSCHNEIDER!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Ich wollte dich\nzu meinem Gehilfen\vmachen!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Hallo, Fremder!\nBleib zum Plausch!\fAlle meine POKéMON\nstammen aus dem\vMeer!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Mist! Der ist mir\nentwischt!",
  ["_SSAnneB1FRoomsMachokeText"] = "MASCHOK: Gwoh!\nGoggoh!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Haha! Willst du\nSeemann werden,\vKumpel?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Du weisst, was man\nüber Seeleute und\vKämpfe sagt!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Genau! Guter\nKampf, Kumpel!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Kennst du den\nANGEL-GURU in\vORANIA CITY?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Meine Seemanns-\nehre steht auf dem\vSpiel!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Dein Kampfgeist\nhat mich versenkt!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Unsere POKéMON\nfingen wir alle\vauf hoher See!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Wir Seeleute haben\nauch POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK, du bist\nnicht übel.",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Meeres-POKéMON\nleben im tiefen\vWasser. Du\vbrauchst eine\vANGEL!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Ich mag freche\nKinder wie dich!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Argh!\nVerloren!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Manchmal treiben\nQuallen ins\vSchiff.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Kumpel, wenn du\nverlierst, gehst\vdu über die\vPlanke!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh! Von einem\nKind besiegt!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Mein Kumpel\nMASCHOK ist\vsuperstark!\fSeine STÄRKE\nreicht, um Felsen\vzu bewegen!",
  ["_SSAnneBowCooltrainerMText"] = "Urgh. Mir ist\nübel.\fIch schnappe hier\netwas frische\vLuft.",
  ["_SSAnneBowSailor1Text"] = "Deckschrubben ist\nharte Arbeit!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Wie viele POKéMON-\nArten gibt es wohl\vinsgesamt?",
  ["_SSAnneBowSailor2BattleText"] = "He, Kumpel!\fTanzen wir ein\nTänzchen!",
  ["_SSAnneBowSailor2EndBattleText"] = "Du bist\nbeeindruckend!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Papa sagt, es gibt\n100 POKéMON-Arten.\vIch glaube, es\vsind mehr.",
  ["_SSAnneBowSailor3BattleText"] = "Ahoi! Bist du\nseekrank?",
  ["_SSAnneBowSailor3EndBattleText"] = "Ich war nur\nunachtsam!",
  ["_SSAnneBowSuperNerdText"] = "Die Party ist aus.\nDas Schiff legt\vbald ab.",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh nein! Du hast\nkeinen Platz\vdafür!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "KAPITÄN: Puh!\nDanke! Mir geht es\vviel besser!\fWillst du meine\nZERSCHNEIDER-\vTechnik sehen?\fIch würde sie dir\nzeigen, wäre mir\vnicht so übel...\fIch weiß! Nimm\ndoch das hier!\fBringe es deinem\nPOKéMON bei, dann\vsiehst du es\vjederzeit!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "KAPITÄN: Puh!\fJetzt, wo mir\nnicht mehr übel\vist, wird es wohl\vZeit.",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "KAPITÄN: Ooargh...\nMir ist elend...\vUrps! Seekrank...\f{PLAYER} massiert\nden Rücken des\vKAPITÄNS!\fRubbel...\nRubbel...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Wie man Seekrank-\nheit besiegt...\vDas liest der\vKAPITÄN!",
  ["_SSAnneCaptainsRoomTrashText"] = "Igitt! Hätte ich\nbloß nicht\vhineingesehen!",
  ["_SSAnneKitchenCook1Text"] = "He, mon petit!\nWir haben zu tun!\vAus dem Weg!",
  ["_SSAnneKitchenCook2Text"] = "Im Müll lag ein\nseltsamer Ball.",
  ["_SSAnneKitchenCook3Text"] = "Vor lauter Arbeit\nwird mir ganz\vschwindlig!",
  ["_SSAnneKitchenCook4Text"] = "Hmm-di-hmm-di-\nho...\fIch schäle jeden\nTag Kartoffeln!\vHmm-hmm...",
  ["_SSAnneKitchenCook5Text"] = "Kennst du RELAXO?\fEs frisst und\nschläft nur!",
  ["_SSAnneKitchenCook6Text"] = "Schnief...\nSchluchz...\fIch schäle immer\nnur Zwiebeln...\vSchnief...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ähem! Isch bin in\nder Tat le CHEF!\fLe Hauptgericht\nist",
  ["_SSTicketNoRoomText"] = "Du schleppst zu\nviel Zeug mit dir\vherum!",
  ["_SSTicketReceivedText"] = "{PLAYER} erhält\nein {RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Wildes {RAM:wEnemyMonNick}\nist wütend!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Wo ist bloß\nmein Freund ERIK\vhin?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Ich fange POKéMON\nals Geschenke für\vzu Hause!",
  ["_SafariZoneCenterRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneCenterTrainerTipsSignText"] = "TRAINER-TIPS\fDrücke START, um\ndie Restzeit zu\vprüfen!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ich habe ein\nCHANEIRA gefangen!\fDafür hat sich\nalles gelohnt!",
  ["_SafariZoneEastRestHouseScientistText"] = "Wie viele hast du\ngefangen? Ich bin\vvöllig erledigt!",
  ["_SafariZoneEastRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Puh! All der Spaß\nmacht müde!",
  ["_SafariZoneEastSignText"] = "ZENTRALAREAL\nNORDEN: AREAL 2",
  ["_SafariZoneEastTrainerTipsText"] = "TRAINER-TIPS\fDie Restzeit\nverstreicht nur\vbeim Laufen!",
  ["_SafariZoneEatingText"] = "Wildes {RAM:wEnemyMonNick}\nfrisst!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\fWir rufen dich\nüber Lautsprecher,\vwenn Zeit oder\vSAFARIBÄLLE\vausgehen!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "Guter Fang dabei?\nKomm bald wieder!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Viel Glück!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Schon fertig?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ups! Nicht genug\nGeld!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Komm bald\nwieder!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Bitte gib übrige\nSAFARIBÄLLE\vzurück.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Willkommen in der\nSAFARI-ZONE!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Das macht ¥500,\nbitte!\fHier nutzen wir\nnur einen ganz\vspeziellen\vPOKéBALL.\f{PLAYER} erhält\n30 SAFARIBÄLLE!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Für nur ¥500\nkannst du im Park\vPOKéMON fangen,\vso viele du magst!\fWillst du an der\nJagd teilnehmen?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Hi! Bist du zum\nersten Mal hier?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "Die SAFARI-ZONE\nhat 4 Areale.\fIn jedem Areal\ngibt es andere\vPOKéMON. Fange\vsie mit\vSAFARIBÄLLEN!\fSind Zeit oder\nSAFARIBÄLLE alle,\vist das Spiel für\vdich vorbei!\fÖffne vorher eine\nfreie POKéMON-BOX,\vdamit Platz für\vneue POKéMON ist!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Sorry, du bist\ndoch Stammgast!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Mein EVOLI wurde\nzu FLAMARA!\fDas EVOLI eines\nFreundes wurde\vaber ein AQUANA!\vWarum nur?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Geh zum tiefsten\nTeil der SAFARI-\vZONE. Dort winkt\vein Preis!",
  ["_SafariZoneNorthRestHouseScientistText"] = "ITEMS, die du hier\nfindest, darfst du\vbehalten.\fAber die Zeit\nreicht nicht, um\valle auf einmal\vzu holen!",
  ["_SafariZoneNorthRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneNorthSignText"] = "AREAL 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "TRAINER-TIPS\fDas GEHEIMHAUS\nist noch voraus!",
  ["_SafariZoneNorthTrainerTips2Text"] = "TRAINER-TIPS\fPOKéMON verstecken\nsich im hohen\vGras!\fScheuche sie im\nZickzacklauf auf!",
  ["_SafariZoneNorthTrainerTips3Text"] = "TRAINER-TIPS\fFinde das GEHEIM-\nHAUS und gewinne\veine gratis VM!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "VM03 ist SURFER!\fPOKéMON können\ndich damit übers\vWasser tragen!\fDiese VM nutzt\nsich nicht ab! Du\vkannst sie immer\vwieder verwenden!\fWas für ein Glück,\ndass du diesen\vtollen Preis\vgewinnst!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Du hast keinen\nPlatz für diesen\vtollen Preis!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Endlich!\fDu bist der erste\nGast im GEHEIM-\vHAUS!\fIch fürchtete\nschon, niemand\vwürde unseren\vPreis gewinnen.\fGlückwunsch!\nDu hast gewonnen!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "SUCHMELDUNG\fDer WÄRTER der\nSAFARI-ZONE hat\vseine GOLDZÄHNE\vverloren. Sie sind\vhier irgendwo.\fBelohnung geboten!\nKontakt: WÄRTER",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Mit KÖDERN lassen\nsich POKéMON\vleichter fangen.",
  ["_SafariZoneWestRestHouseScientistText"] = "Nach STEIN-Würfen\nfliehen POKéMON\vvielleicht, sind\vaber leichter zu\vfangen.",
  ["_SafariZoneWestRestHouseSignText"] = "RASTHAUS",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ich lief viel,\nsah aber kein\vPOKéMON, das ich\vwollte.",
  ["_SafariZoneWestSignText"] = "AREAL 3\nOSTEN: ZENTRUM",
  ["_SafariZoneWestTrainerTipsText"] = "TRAINER-TIPS\fGroße Erkundungs-\naktion!\fDie Suche nach\ndem GEHEIMHAUS!",
  ["_SaffronCityFightingDojoSignText"] = "KAMPF-DOJO",
  ["_SaffronCityGentlemanText"] = "Ich flog auf\nmeinem TAUBOSS\vher, als ich von\vSILPH las.\fSchon vorbei? Ich\nhabe den ganzen\vRummel verpasst.",
  ["_SaffronCityGymSignText"] = "SAFFRONIA CITY\nPOKéMON-ARENA\vLEITERIN: SABRINA\fMeisterin der\nPsycho-POKéMON!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "MR.PSYCHICs\nHAUS",
  ["_SaffronCityPidgeotText"] = "TAUBOSS: Bi bibii!",
  ["_SaffronCityPokecenterGuyText1"] = "Wären die TOP VIER\ndoch hier, um TEAM\vROCKET zu\vvermöbeln!",
  ["_SaffronCityPokecenterGuyText2"] = "TEAM ROCKET ist\nweg! Wir können\vwieder sicher\vraus! Wunderbar!",
  ["_SaffronCityRockerText"] = "Ich sah den\nROCKET-BOSS aus\vdem SILPH-Gebäude\vfliehen.",
  ["_SaffronCityRocket1Text"] = "Was willst du?\nVerschwinde!",
  ["_SaffronCityRocket2Text"] = "Der BOSS sagt, die\nStadt gehört uns!",
  ["_SaffronCityRocket3Text"] = "Geh aus\ndem Weg!",
  ["_SaffronCityRocket4Text"] = "SAFFRONIA gehört\nTEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Böse zu sein lässt\nmich richtig\vaufleben!",
  ["_SaffronCityRocket6Text"] = "Au! Pass doch auf,\nwo du hinläufst!",
  ["_SaffronCityRocket7Text"] = "Mit SILPH unter\nKontrolle nutzen\vwir POKéMON auf\vder ganzen Welt\vaus!",
  ["_SaffronCityRocket8Text"] = "Ich bin vom\nSicherheitsdienst.\fVerdächtige Kinder\nlasse ich nicht\vrein!",
  ["_SaffronCityRocket9Text"] = "...\nSchnarch...\fHa! Der macht ein\nNickerchen!",
  ["_SaffronCityScientistText"] = "Du hast TEAM\nROCKET ganz allein\vbesiegt? Toll!",
  ["_SaffronCitySignText"] = "SAFFRONIA CITY\nGoldene Stadt\vdes Handels",
  ["_SaffronCitySilphCoLatestProductSignText"] = "SILPHs neuestes\nProdukt!\fErscheinungstermin\nnoch offen...",
  ["_SaffronCitySilphCoSignText"] = "SILPH CO.\nBÜROGEBÄUDE",
  ["_SaffronCitySilphWorkerFText"] = "Jetzt strömen die\nLeute sicher nach\vSAFFRONIA zurück.",
  ["_SaffronCitySilphWorkerMText"] = "Ja! TEAM ROCKET\nist weg! Man kann\vwieder sicher\vraus!",
  ["_SaffronCityTrainerTips1Text"] = "TRAINER-TIPS\fHYPERHEILER heilt\nalle Leiden wie\vSchlaf und Brand.\fEr kostet etwas\nmehr, ist aber\vpraktischer.",
  ["_SaffronCityTrainerTips2Text"] = "TRAINER-TIPS\fDer neue SUPERBALL\nbietet bessere\vFangraten.\fProbiere ihn bei\nschwer fangbaren\vPOKéMON!",
  ["_SaffronGateGuardGeeImThirstyText"] = "Ich schiebe Wache.\nMann, habe ich\veinen Durst!\fHalt! Die Straße\nist gesperrt.",
  ["_SaffronGateGuardImParchedText"] = "Mannomann!\nBin ich durstig!\v...\vWas? Das Getränk\vist für mich?\vOh, danke!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Hi, danke für die\nkühlen Getränke!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\f...\nGluck gluck...\v...\vSchluck...\vDu willst nach\vSAFFRONIA CITY...\v...\vGeh ruhig durch.\vIch teile das mit\vden anderen\vWachen!",
  ["_SaffronGymChanneler1AfterBattleText"] = "Bei gleicher\nStärke siegt der\vstärkere Wille!\fWillst du SABRINA\nschlagen, denk nur\vans Siegen!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA ist jünger\nals ich, doch ich\vachte sie!",
  ["_SaffronGymChanneler1EndBattleText"] = "Nicht gut\ngenug!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Ich muss meinen\nPOKéMON bessere\vTechniken\vbeibringen!",
  ["_SaffronGymChanneler2BattleText"] = "POKéMON gleichen\nihren TRAINERN.\fDeine müssen dann\nja zäh sein!",
  ["_SaffronGymChanneler2EndBattleText"] = "Ich wusste\nes!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Ich wusste, dass\ndies geschehen\vwürde.",
  ["_SaffronGymChanneler3BattleText"] = "Du und ich, unsere\nPOKéMON werden\vkämpfen!",
  ["_SaffronGymChanneler3EndBattleText"] = "Ich habe doch\nverloren!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Psycho-Kräfte,\nwas?\fDamit würde ich am\nSpielautomaten\vabsahnen!",
  ["_SaffronGymGuideChampInMakingText"] = "Yo! Champ in spe!\fSABRINAs POKéMON\nnutzen Psycho-\vKräfte statt\vMuskeln!\fKampf-POKéMON sind\nschwach gegen\vPsycho-POKéMON!\fSie werden platt-\ngemacht, ehe sie\vzuschlagen können!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "Mit dem SUMPFORDEN\ngehorchen dir\vPOKéMON bis L70!\fStärkere POKéMON\nwerden wild und\vmissachten deine\vBefehle im Kampf!\fTrainiere deine\nPOKéMON nur nicht\vzu viel!\fWarte, nimm noch\ndiese TM mit!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Jeder hat Psycho-\nKräfte! Die Leute\vwissen es nur\vnicht!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Ich bin\nschockiert!\vAber verloren ist\vverloren.\fIch gebe zu, ich\nhabe zu wenig\vtrainiert!\fDu hast dir den\nSUMPFORDEN\vverdient!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} erhält\nTM46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Dein Beutel ist\nvoller ITEMS!",
  ["_SaffronGymSabrinaText"] = "Ich sah dein\nKommen voraus!\fIch habe seit\nmeiner Kindheit\vPsycho-Kräfte.\fZuerst lernte ich,\nLöffel mit Gedan-\vken zu verbiegen.\fIch kämpfe ungern,\ndoch wenn du\vwillst, zeige ich\vdir meine Kräfte!",
  ["_SaffronGymYoungster1AfterBattleText"] = "Psycho-POKéMON\nfürchten nur\vGeister und Käfer!",
  ["_SaffronGymYoungster1BattleText"] = "Macht dir unsere\nunsichtbare Kraft\vAngst?",
  ["_SaffronGymYoungster1EndBattleText"] = "Das habe ich nicht\nvorhergesehen!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA hat den\nKARATEMEISTER von\vnebenan besiegt!",
  ["_SaffronGymYoungster2BattleText"] = "Du weisst, Kraft\nallein reicht\vnicht!",
  ["_SaffronGymYoungster2EndBattleText"] = "Das darf nicht\nwahr sein!",
  ["_SaffronGymYoungster3AfterBattleText"] = "Früher gab es 2\nARENEN in\vSAFFRONIA.\fDas KAMPF-DOJO\nnebenan verlor\vseinen ARENA-\vStatus, als wir\vsie vermöbelten!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA ist jung,\naber auch unsere\vLEITERIN!\fDu kommst nicht so\nleicht zu ihr!",
  ["_SaffronGymYoungster3EndBattleText"] = "Meine Konzentra-\ntion war dahin!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Genau! Ich las\ndeine Gedanken\vper Telepathie!",
  ["_SaffronGymYoungster4BattleText"] = "Die ARENA von\nSAFFRONIA ist für\vPsycho-Kräfte\vberühmt!\fDu willst zu\nSABRINA!\vIch spüre es!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "BELEBER ist teuer,\nbelebt aber kampf-\vunfähige POKéMON!",
  ["_SaffronMartSuperNerdText"] = "TOP-SCHUTZ hält\nschwache POKéMON\vlänger fern als\vSUPERSCHUTZ!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Danke für deinen\nBrief. Hoffentlich\vsehen wir uns\vbald!\fHe! Lies nicht\nmeinen Brief!",
  ["_SaffronPidgeyHousePaperText"] = "Ich bekam ein\nAP-PLUS geschenkt.\fEs erhöht die AP\nvon Attacken!",
  ["_SaffronPidgeyHousePidgeyText"] = "TAUBSI: Kurukkoo!",
  ["_SaffronPidgeyHouseYoungsterText"] = "Die IMITATORIN ist\nsüß! Ich schenke\vihr eine\vPOKéPUPPE!",
  ["_SaffronPokecenterBeautyText"] = "POKéMON wachsen\nje nach Art ver-\vschieden schnell.",
  ["_SaffronPokecenterGentlemanText"] = "SILPH CO. ist sehr\nberühmt. Darum kam\vTEAM ROCKET her!",
  ["_SandshrewDexEntry"] = "Gräbt sich in\ntrockenen Gegenden\nfern von Wasser\ftief ein. Kommt\nnur zur Nahrungs-\nsuche hervor",
  ["_SandslashDexEntry"] = "Rollt sich bei\nGefahr zu einer\nstachligen Kugel\fzusammen und kann\nso angreifen oder\nfliehen",
  ["_SaveOptionText"] = "Die Option SICHERN\nfindest du im\vMENÜ.",
  ["_SavingEnergyText"] = "{USER}\nspart Energie!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} ist\nstarr vor Angst!",
  ["_ScytherDexEntry"] = "Mit Ninja-Tempo\nund Wendigkeit\ntäuscht es vor,\fes wäre mehr\nals nur eines\nvorhanden",
  ["_SeadraDexEntry"] = "Schwimmt rückwärts\ndurch schnelles\nSchlagen seiner\fflügelartigen\nFlossen und des\nstarken Schwanzes",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Gyaoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "Felsbrocken können\nden Wasserlauf\vändern!",
  ["_SeafoamIslandsB4FDangerSignText"] = "GEFAHR\nStarke Strömung!",
  ["_SeakingDexEntry"] = "Zur Laichzeit im\nHerbst schwimmen\nsie kraftvoll\fFlüsse und Bäche\nhinauf",
  ["_SeelDexEntry"] = "Das Horn auf\nseinem Kopf ist\nsehr hart. Es\fdient dazu, dickes\nEis zu\ndurchbrechen",
  ["_SentToBoxText"] = "Kein Platz mehr\nfür POKéMON!\v{RAM:wBoxMonNicks} kam in\vPOKéMON-BOX\v{RAM:wStringBuffer} auf dem PC!",
  ["_ShallWeHealYourPokemonText"] = "Sollen wir deine\nPOKéMON heilen?",
  ["_ShellderDexEntry"] = "Die harte Schale\nwehrt jede Attacke\nab. Verwundbar ist\fes nur, wenn die\nSchale offen\nsteht",
  ["_ShroudedInMistText"] = "{USER}\nist nebelverhüllt!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Argh!! Schon\nwieder verloren!?",
  ["_SilphCo10FPorygonText"] = "Auf dem Monitor\nsind POKéMON!",
  ["_SilphCo10FRocketAfterBattleText"] = "Netter Versuch!\nDer Sitzungssaal\vist einen Stock\vhöher!",
  ["_SilphCo10FRocketBattleText"] = "Willkommen im 10.\nStock! Schön, dass\vdu da bist!",
  ["_SilphCo10FRocketEndBattleText"] = "Ich bin\nsprachlos!",
  ["_SilphCo10FScientistAfterBattleText"] = "Zufrieden, mich\nbesiegt zu haben?\vDann geh heim!",
  ["_SilphCo10FScientistBattleText"] = "Schluss mit den\nalbernen Spielen!",
  ["_SilphCo10FScientistEndBattleText"] = "Kein Continue\nmehr übrig!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Waaaah!\vIch habe Angst!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Bitte verrate\nnicht, dass ich\vgeweint habe!",
  ["_SilphCo11FBeautyText"] = "SEKRETÄRIN: Danke,\ndass du uns alle\vgerettet hast!\fWir bewundern\ndeinen Mut.",
  ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nMan sieht sich!\fDer PRÄSIDENT und\nich besprechen ein\vwichtiges\vGeschäft.\fMisch dich nicht\nin die Welt der\vErwachsenen ein...\fSonst lernst du\nechten Schmerz\vkennen!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Verflucht! Du hast\nunsere Pläne für\vSILPH ruiniert!\fDoch TEAM ROCKET\nwird niemals\vuntergehen!\f{PLAYER}! Vergiss\nnie: Alle POKéMON\vexistieren für\vTEAM ROCKET!\fIch muss gehen,\ndoch ich kehre\vzurück!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Du willst also zu\nmeinem BOSS?",
  ["_SilphCo11FRocket1BattleText"] = "Stehen bleiben!\nKeine Bewegung!",
  ["_SilphCo11FRocket1EndBattleText"] = "Nicht...\nBitte!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Sieh dich vor!\nMein BOSS mag\vseine POKéMON\vhart!",
  ["_SilphCo11FRocket2BattleText"] = "Halt! Hast du\neinen Termin bei\vmeinem BOSS?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nVernichtet!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRÄSIDENT: Das\nkann man nirgends\vkaufen!\fEs ist unser\ngeheimer Prototyp,\vder MEISTERBALL!\fEr fängt jedes\nPOKéMON ohne\vAusnahme!\fBehalte ihn aber\nlieber für dich!",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Du hast keinen\nPlatz dafür.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} erhält\neinen {RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRÄSIDENT: Danke,\ndass du SILPH\vgerettet hast!\fIch werde nie\nvergessen, dass du\vuns in der Not\vgeholfen hast!\fIch muss dir\nirgendwie danken!\fIch bin reich und\nkann dir alles\vgeben!\fHier, das ist\nvielleicht etwas!",
  ["_SilphCo1FLinkReceptionistText"] = "Willkommen!\fDer PRÄSIDENT ist\nim Sitzungssaal\vim 11. Stock!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Rautenförmige\nFelder sind\vTeleport-Blöcke!\fHightech-\nTransporter!",
  ["_SilphCo2FRocket1BattleText"] = "Kinder haben hier\nkeinen Zutritt!",
  ["_SilphCo2FRocket1EndBattleText"] = "Hart!",
  ["_SilphCo2FRocket2AfterBattleText"] = "SILPH CO. wird mit\nTEAM ROCKET\vfusionieren!",
  ["_SilphCo2FRocket2BattleText"] = "He, Kind! Was\nmachst du hier?",
  ["_SilphCo2FRocket2EndBattleText"] = "Vermasselt!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Ich arbeite für\nSILPH und für\vTEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "Hilfe! Ich arbeite\nbei SILPH.",
  ["_SilphCo2FScientist1EndBattleText"] = "Woher wusstest du,\ndass ich ein\vROCKET bin?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Findest du durch\ndas Labyrinth\vhier?",
  ["_SilphCo2FScientist2BattleText"] = "Zutritt verboten!\nGeh nach Hause!",
  ["_SilphCo2FScientist2EndBattleText"] = "Du bist gut.",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "TM36 enthält\nFINALE!\fEs ist stark, aber\ndas POKéMON wird\vselbst besiegt!\vSei vorsichtig.",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Du hast keinen\nPlatz dafür.",
  ["_SilphCo3FRocketAfterBattleText"] = "Ein Tipp? Türen\nöffnest du mit\veiner KEYCARD!",
  ["_SilphCo3FRocketBattleText"] = "Leg dich nicht\nmit uns an, Kind!",
  ["_SilphCo3FRocketEndBattleText"] = "Ich gebe\nauf!",
  ["_SilphCo3FScientistAfterBattleText"] = "Hmpf...\fTEAM ROCKET wollte\nmich für meine\vHilfe POKéMON\verforschen lassen!",
  ["_SilphCo3FScientistBattleText"] = "Ich stehe mehr zu\nTEAM ROCKET als\vzu SILPH!",
  ["_SilphCo3FScientistEndBattleText"] = "Du hast mich\nvoll erwischt!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Ich arbeite bei\nSILPH. Was soll\vich nur tun?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Du und\ndeine POKéMON habt\vuns gerettet!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Fwahahaha! Mein\nBOSS wollte diesen\vLaden schon lange!",
  ["_SilphCo4FRocket1BattleText"] = "TEAM ROCKET hat\ndas Kommando bei\vSILPH CO.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Argh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Das muss der BOSS\nim 11. Stock\verfahren!",
  ["_SilphCo4FRocket2BattleText"] = "Eindringling\ngesichtet!",
  ["_SilphCo4FRocket2EndBattleText"] = "Wer\nbist du?",
  ["_SilphCo4FScientistAfterBattleText"] = "Die Türen sind\nelektronisch\vverriegelt! Ein\vTÜRÖFFNER öffnet\vsie!",
  ["_SilphCo4FScientistBattleText"] = "Meine POKéMON\nsind meine treuen\vSoldaten!",
  ["_SilphCo4FScientistEndBattleText"] = "Mist!\nIhr schwachen\vPOKéMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Psst! Siehst du\nnicht, dass ich\vmich verstecke?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Was? TEAM ROCKET\nist weg?",
  ["_SilphCo5FPokemonReport1Text"] = "Ein POKéMON-\nBERICHT!\fDas POKéMON-LABOR\nschuf PORYGON,\vdas erste\vvirtuelle POKéMON.",
  ["_SilphCo5FPokemonReport2Text"] = "Ein POKéMON-\nBERICHT!\fÜber 160 POKéMON-\nTechniken sind\vbestätigt.",
  ["_SilphCo5FPokemonReport3Text"] = "Ein POKéMON-\nBERICHT!\f4 POKéMON ent-\nwickeln sich nur\vbeim Tausch per\vLink-Kabel.",
  ["_SilphCo5FRockerAfterBattleText"] = "Du bist erst im\n5. Stock. Zum\vBOSS ist es noch\vweit!",
  ["_SilphCo5FRockerBattleText"] = "Waaas? Hier\nsollten keine\vKinder sein!",
  ["_SilphCo5FRockerEndBattleText"] = "Ach du\nmeine Güte!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Es ist nicht\nklug, sich mit\vTEAM ROCKET\vanzulegen!",
  ["_SilphCo5FRocket1BattleText"] = "Ich hörte, ein\nKind läuft hier\vherum.",
  ["_SilphCo5FRocket1EndBattleText"] = "Bumm!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Da fällt mir ein:\fSMOGON entwickelt\nsich zu SMOGMOG!",
  ["_SilphCo5FRocket2BattleText"] = "Zeig TEAM ROCKET\netwas Respekt!",
  ["_SilphCo5FRocket2EndBattleText"] = "Hust...\nHust...",
  ["_SilphCo5FScientistAfterBattleText"] = "Wir arbeiteten am\nultimativen POKé-\vBALL, der alles\vfängt!",
  ["_SilphCo5FScientistBattleText"] = "Hier erforschen\nwir die POKéBALL-\vTechnologie!",
  ["_SilphCo5FScientistEndBattleText"] = "Mist!\nVerflixt!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "TEAM ROCKET ist\nin Aufruhr wegen\veines Eindring-\vlings. Das bist\vdu, oder?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "TEAM ROCKET ist\nweg! Du bist\vunser Held!\vDanke!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Egal! Meine\nBrüder werden\vmich rächen!",
  ["_SilphCo6FRocket1BattleText"] = "Ich bin einer der\n4 ROCKET-BRÜDER!",
  ["_SilphCo6FRocket1EndBattleText"] = "Flamme\naus!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Wer für Gerech-\ntigkeit steht,\vverrät das Böse!",
  ["_SilphCo6FRocket2BattleText"] = "Du wagst es, TEAM\nROCKET zu\vverraten?",
  ["_SilphCo6FRocket2EndBattleText"] = "Du\nVerräter!",
  ["_SilphCo6FScientistAfterBattleText"] = "TIKSI-FILIALE?\nDie liegt im\vrussischen\vNiemandsland!",
  ["_SilphCo6FScientistBattleText"] = "Dieser miese\nPRÄSIDENT!\fEr hätte mich nie\nin die TIKSI-\vFILIALE schicken\vdürfen!",
  ["_SilphCo6FScientistEndBattleText"] = "Verflixt!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Er tut mir so\nleid, ich muss ihn\vheiraten!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Sieh ihn dir an!\nSo ein Feigling!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "TEAM ROCKET will\nmit POKéMON die\vWelt erobern!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "TEAM ROCKET floh\ndeinetwegen!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Nun, zurück an\ndie Arbeit!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "Die ROCKETs kamen\nund besetzten das\vGebäude!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Sie hatten es\nwohl auf SILPHs\vPOKéMON-Produkte\vabgesehen.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Arbeite bei\nSILPH, wenn du\vgrößer bist!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Ojemine!\nHilf mir bitte!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Wir haben uns\nverlobt! Hehe!",
  ["_SilphCo7FRivalDefeatedText"] = "Oho! Du bist also\nbereit für den\vROCKET-BOSS!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Nun, {PLAYER}!\fIch ziehe weiter\nund voran!\fMein POKéDEX\nzeigt mir, was\vstark ist und wie\vsich alles ent-\vwickelt!\fIch gehe zur\nPOKéMON LIGA und\vwerfe die TOP\vVIER raus!\fIch werde der\nstärkste TRAINER\vder Welt!\f{PLAYER}, viel\nGlück! Streng\vdich an! Man\vriecht sich!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Wo warst\ndu so lange,\v{PLAYER}?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Wie soll\nich es sagen?\fDu bist nicht gut\ngenug, um mit den\vGroßen zu\vspielen!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Hahaha!\nIch wusste, du\vtauchst auf, wenn\vich hier warte!\fTEAM ROCKET hat\ndich wohl aufge-\vhalten! Ist mir\vegal!\fIch sah dich in\nSAFFRONIA CITY,\vdrum wollte ich\vsehen, ob du\vbesser wurdest!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Du findest meinen\nBOSS nicht durch\vbloßes Herum-\vlaufen!",
  ["_SilphCo7FRocket1BattleText"] = "Oho! Ich rieche\neine kleine\vRatte!",
  ["_SilphCo7FRocket1EndBattleText"] = "Licht\naus!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Egal. Meine\nBrüder zahlen es\vdir heim!",
  ["_SilphCo7FRocket2BattleText"] = "Ich bin einer der\n4 ROCKET-BRÜDER!",
  ["_SilphCo7FRocket2EndBattleText"] = "Argh! Brüder,\nich verlor!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Geh heim, bevor\nmein BOSS sauer\vwird!",
  ["_SilphCo7FRocket3BattleText"] = "Ein Kind als Ein-\ndringling? Das\vmusst du sein!",
  ["_SilphCo7FRocket3EndBattleText"] = "Na gut!\nIch verlor!",
  ["_SilphCo7FScientistAfterBattleText"] = "Für dein Alter\nbist du ein guter\vTRAINER!",
  ["_SilphCo7FScientistBattleText"] = "Hehe!\fDu hieltst mich\nfür einen SILPH-\vAngestellten?",
  ["_SilphCo7FScientistEndBattleText"] = "Ich bin\nerledigt!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Hallo! Du\nbist kein ROCKET!\vDu willst uns\vretten? Danke!\fZum Dank sollst\ndu dieses POKéMON\vbekommen.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Der ROCKET-BOSS\nist im Sitzungs-\vsaal! Geht es dem\vPRÄSIDENTEN gut?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "Das ist LAPRAS.\nEs ist sehr klug.\fWir hielten es im\nLabor, aber bei\vdir ist es besser\vaufgehoben!\fDu wirst sicher\nein guter TRAINER\vfür LAPRAS sein!\fEs schwimmt gut.\nEs nimmt dich\vgerne mit!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Endlich gerettet!\nDanke!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "TEAM ROCKET war\nhinter dem\vMEISTERBALL her,\vder jedes POKéMON\vfängt!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Wegen TEAM ROCKET\nstoppten wir das\vMEISTERBALL-\vProjekt.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Es wäre schlimm,\nwenn TEAM ROCKET\vSILPH oder unsere\vPOKéMON bekäme!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Du hast TEAM\nROCKET ganz\vallein verjagt?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Du! Hier ist es\nsehr gefährlich!\vDu willst mich\vretten? Unmöglich!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Endlich sicher!\nOh, danke!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Kehr um, oder ich\nrufe Verstärkung!",
  ["_SilphCo8FRocket1BattleText"] = "Bis hierhin und\nnicht weiter!",
  ["_SilphCo8FRocket1EndBattleText"] = "Nicht genug\nMumm!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Ich überlasse\ndich meinen\vBrüdern!",
  ["_SilphCo8FRocket2BattleText"] = "Ich bin einer der\n4 ROCKET-BRÜDER!",
  ["_SilphCo8FRocket2EndBattleText"] = "Uff!\nOh, Brüder!",
  ["_SilphCo8FScientistAfterBattleText"] = "Und? Wie gefällt\ndir das Labyrinth\vim SILPH-GEBÄUDE?",
  ["_SilphCo8FScientistBattleText"] = "Du machst uns\nnur Probleme!",
  ["_SilphCo8FScientistEndBattleText"] = "Was?\nIch verlor?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "Ob SILPH wohl\nam Ende ist...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Danke für die\nRettung!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Wäre ich in\ndeinem Alter\vTRAINER\vgeworden...",
  ["_SilphCo9FRocket1BattleText"] = "Deine POKéMON\nscheinen dich zu\vlieben, Kleiner!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "Meine Brüder\nwerden mich\vrächen!",
  ["_SilphCo9FRocket2BattleText"] = "Ich bin einer der\n4 ROCKET-BRÜDER!",
  ["_SilphCo9FRocket2EndBattleText"] = "Warg! Brüder,\nich verlor!",
  ["_SilphCo9FScientistAfterBattleText"] = "Schwächen auszu-\nnutzen wirkt!\vDenk an die\vElement-Typen!",
  ["_SilphCo9FScientistBattleText"] = "Deine POKéMON\nhaben Schwächen!\vDie nutze ich\vaus!",
  ["_SilphCo9FScientistEndBattleText"] = "Du hast mich\nvermöbelt!",
  ["_SkyAttackGlowingText"] = "\nglüht!",
  ["_SlowbroDexEntry"] = "Das MUSCHAS an\nFLEGMONs Schweif\nsoll sich von den\fEssensresten des\nWirts ernähren",
  ["_SlowpokeDexEntry"] = "Unglaublich lahm\nund träge. Es\nbraucht 5 Sek.,\fum Schmerz bei\neinem Angriff zu\nspüren",
  ["_SnorlaxDexEntry"] = "Sehr faul. Frisst\nund schläft nur.\nJe runder es\fwird, desto\nträger wird es\nauch",
  ["_SoYouWantPrizeText"] = "Du willst also\n{RAM:wNameBuffer}?",
  ["_SorryNeedMoreCoinsText"] = "Du brauchst mehr\nMünzen. Sorry!",
  ["_SpearowDexEntry"] = "Frisst Käfer im\nGras. Es muss mit\nden kurzen\fFlügeln schnell\nschlagen, um zu\nfliegen",
  ["_SquirtleDexEntry"] = "Nach der Geburt\nschwillt sein\nRücken zu einem\fPanzer an. Sprüht\nkräftig Schaum\naus dem Maul",
  ["_StarmieDexEntry"] = "Sein Kern glüht\nin den 7 Farben\ndes Regenbogens.\fManche schätzen\nden Kern als\nJuwel",
  ["_StartSlotMachineText"] = "Start!",
  ["_StartedSleepingEffect"] = "{USER}\nschlief ein!",
  ["_StaryuDexEntry"] = "Rätselhaftes\nPOKéMON. Es kann\nverlorene Glieder\fim Kampf mühelos\nregenerieren",
  ["_StatusChangesEliminatedText"] = "Alle STATUS-\nVeränderungen\vaufgehoben!",
  ["_StoppedEvolvingText"] = "Was? {RAM:wStringBuffer}\nhört auf, sich zu\ventwickeln!",
  ["_StrengthsAndWeaknessesText"] = "Jeder POKéMON-Typ\nhat Stärken und\vSchwächen gegen\vandere.",
  ["_SubstituteBrokeText"] = "{TARGET}s\nDELEGATOR brach!",
  ["_SubstituteText"] = "Es erschuf einen\nDELEGATOR!",
  ["_SubstituteTookDamageText"] = "Der DELEGATOR\nnahm Schaden für\v{TARGET}!",
  ["_SuckedHealthText"] = "Sog Energie von\n{TARGET} ab!",
  ["_SuperEffectiveText"] = "Das ist sehr\neffektiv!",
  ["_SurfingGotOnText"] = "{PLAYER} steigt\nauf {RAM:wNameBuffer}!",
  ["_SurfingNoPlaceToGetOffText"] = "Hier kann man\nnicht absteigen!",
  ["_SwitchOnText"] = "Schalter an!",
  ["_TM21ExplanationText"] = "\fTM21 enthält\nMEGASAUGER.\fDie Hälfte des\nSchadens heilt\vdein POKéMON!",
  ["_TM24ExplanationText"] = "\fTM24 enthält\nDONNERBLITZ!\fBring ihn einem\nElektro-POKéMON\vbei!",
  ["_TM34ExplanationText"] = "\fEine TM enthält\neine Technik, die\vPOKéMON erlernen\vkönnen!\fEine TM geht nur\neinmal! Wähle das\vPOKéMON also mit\vBedacht!\fTM34 enthält\nGEDULD!\fDein POKéMON\nsteckt Schaden\vein und zahlt ihn\vdoppelt zurück!",
  ["_TM46ExplanationText"] = "\fTM46 ist PSYWELLE!\nStarke Psycho-\vWellen fügen\vSchaden zu!",
  ["_TangelaDexEntry"] = "Der ganze Körper\nist von Ranken\numhüllt, die See-\ftang ähneln. Sie\nzittern, wenn es\nläuft",
  ["_TaurosDexEntry"] = "Hat es ein Ziel,\nstürmt es wild\nlos und peitscht\fsich dabei mit\nseinen langen\nSchweifen",
  ["_TeachMachineMoveText"] = "Sie enthielt\n{RAM:wStringBuffer}!\fEinem POKéMON\n{RAM:wStringBuffer}\vbeibringen?",
  ["_TentacoolDexEntry"] = "Treibt in seich-\nten Meeren. Wer\nes versehentlich\fangelt, wird oft\nmit ätzender\nSäure bestraft",
  ["_TentacruelDexEntry"] = "Die Tentakel sind\nmeist kurz. Zur\nJagd streckt es\fsie aus, um Beute\nzu fangen und zu\nlähmen",
  ["_TextIDErrorText"] = "{NUM:hTextID, 1, 2} FEHLER.",
  ["_Thanks1Text"] = "Hey, danke!",
  ["_Thanks2Text"] = "Danke!",
  ["_Thanks3Text"] = "Danke, Kumpel!",
  ["_ThrashingAboutText"] = "{USER}\ntobt herum!",
  ["_ThrewAwayItemText"] = "{RAM:wNameBuffer}\nweggeworfen.",
  ["_ThrewBaitText"] = "{PLAYER} wirft\neinen KÖDER.",
  ["_ThrewRockText"] = "{PLAYER} wirft\neinen STEIN.",
