  ["_TradeWavesFarewellText"] = "{RAM:wLinkEnemyTrainerName} winkt\nzum Abschied, als",
  ["_TradeWentToText"] = "{RAM:wStringBuffer} ging\nzu {RAM:wLinkEnemyTrainerName}.",
  ["_TradeWillTradeText"] = "{RAM:wLinkEnemyTrainerName} tauscht\n{RAM:wNameBuffer}",
  ["_TradedForText"] = "{PLAYER} tauschte\n{RAM:wInGameTradeGiveMonName} gegen\v{RAM:wInGameTradeReceiveMonName}!",
  ["_TradeforText"] = "gegen {PLAYER}s\n{RAM:wStringBuffer}.",
