  ["_TransformedText"] = "{USER}\nverwandelt sich\vin {RAM:wNameBuffer}!",
  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName} will\n{RAM:wStringBuffer}\verlernen!\fAber {RAM:wLearnMoveMonName}\nkann nur 4\vAttacken lernen!\fEine alte Attacke\nfür {RAM:wStringBuffer}\vvergessen?",
  ["_TurnPageText"] = "Umblättern?",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick} dreht\nsich weg!",
  ["_TurnedOnPC1Text"] = "{PLAYER} schaltet\nden PC ein.",
  ["_TurnedOnPC2Text"] = "{PLAYER} schaltet\nden PC ein.",
  ["_UnaffectedText"] = "{TARGET}\nbleibt unberührt!",
  ["_UndergroundPathRoute6GirlText"] = "Im UNTERGRUNDWEG\nverlieren Leute\voft ihre Sachen.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Ich will im Kauf-\nhaus in PRISMANIA\veinkaufen, aber...\fDort sind so\nviele finstere\vGestalten.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Der UNTERGRUNDWEG\nführt unter\vSAFFRONIA durch\vnach LAVANDIA.\fWillst du nach\nAZURIA CITY, geh\vins Gebäude\vgegenüber.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Du willst in\nPRISMANIA CITY\veinkaufen?\fGeh raus und\ndann nach Westen!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "TEAM ROCKET hatte\nein Versteck in\vPRISMANIA CITY?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Bei PRISMANIA\nCITY soll ein\vmüdes POKéMON\vaufgetaucht sein.",
  ["_UndergroundPathRoute8GirlText"] = "Das Kaufhaus in\nPRISMANIA hat\veine große\vAuswahl!",
  ["_UnleashedEnergyText"] = "{USER}\nsetzt Energie\vfrei!",
  ["_UnusedBenchGuyText1"] = "Ich wünschte, ich\nkönnte POKéMON\vfangen.",
  ["_UnusedBenchGuyText2"] = "All der Spaß\nmacht müde...",
  ["_UnusedBenchGuyText3"] = "SILPHs Manager\nversteckt sich in\vder SAFARI-ZONE.",
  ["_UnveiledGhostText"] = "Das SILPHSCOPE\nenthüllt den\vGEIST!",
  ["_UseNextMonText"] = "Nächstes POKéMON\neinsetzen?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} setzt\nZERSCHNEIDER ein!",
  ["_UsedInsteadText"] = "stattdessen,\v",
  ["_UsedMove1Text"] = "\nsetzt ",
  ["_UsedMove2Text"] = "\nsetzt ",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer} setzt\nSTÄRKE ein.",
  ["_VaporeonDexEntry"] = "Lebt am Wasser.\nDie Flosse am\nlangen Schweif\fwird oft mit der\neiner Meerjungfrau\nverwechselt",
  ["_VendingMachineText1"] = "Ein Automat!\nHier ist die\vAuswahl!",
  ["_VendingMachineText4"] = "Ups, zu wenig\nGeld!",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer}\nkommt heraus!",
  ["_VendingMachineText6"] = "Kein Platz mehr\nfür Sachen!",
  ["_VendingMachineText7"] = "Kein Durst!",
  ["_VenomothDexEntry"] = "Die staubartigen\nSchuppen auf den\nFlügeln zeigen\fmit Farben seine\nGiftarten an",
  ["_VenonatDexEntry"] = "Lebt im Schatten\nhoher Bäume und\nfrisst Insekten.\fNachts wird es\nvon Licht ange-\nzogen",
  ["_VenusaurDexEntry"] = "Die Blume blüht,\nwenn sie Sonnen-\nenergie tankt.\fEs wandert stets\nauf der Suche\nnach Sonnenlicht",
  ["_VermilionCityBeautyText"] = "Wir achten auf\ndie Umwelt!\fSLEIMA soll sich\nin Giftschlamm\vvermehren!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Hast du die M.S.\nANNE im Hafen\vgesehen?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "Die M.S. ANNE ist\nalso ausgelaufen!\fIn etwa einem\nJahr kehrt sie\vzurück.",
  ["_VermilionCityGambler2Text"] = "Ich baue auf\ndiesem Grundstück\vein Gebäude.\fMein POKéMON\nstampft den Boden\vfest.",
  ["_VermilionCityGymSignText"] = "ORANIA CITY\nPOKéMON-ARENA\vLEITER: MAJOR BOB\fDer blitzende\nAmerikaner!",
  ["_VermilionCityHarborSignText"] = "ORANIA-HAFEN",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\fEin MACHOLLO\nstampft den Boden\vflach.",
  ["_VermilionCityMachopText"] = "MACHOLLO: Guoh!\nGogogoh!",
  ["_VermilionCityNoticeSignText"] = "ACHTUNG!\fROUTE 12 ist evtl.\ndurch ein schla-\vfendes POKéMON\vblockiert.\fUmweg durch den\nFELSTUNNEL nach\vLAVANDIA nehmen.\fPOLIZEI ORANIA",
  ["_VermilionCityPokemonFanClubSignText"] = "POKéMON-FANCLUB\nAlle POKéMON-Fans\vwillkommen!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Willkommen an\nBord der M.S.\vANNE!\fVerzeihung, hast\ndu ein Ticket?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} zeigt\ndas BOOTSTICKET!\fPrima! Willkommen\nauf der M.S. ANNE!",
  ["_VermilionCitySailor1ShipSetSailText"] = "Das Schiff ist\nausgelaufen.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Willkommen auf\nder M.S. ANNE!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} hat kein\nBOOTSTICKET.\fTut mir leid!\fOhne Ticket\nkommst du nicht\van Bord.",
  ["_VermilionCitySailor2Text"] = "Die M.S. ANNE ist\nein berühmtes\vLuxusschiff.\fWir besuchen\nORANIA einmal\vim Jahr.",
  ["_VermilionCitySignText"] = "ORANIA CITY\nHafen der schönen\vSonnenuntergänge",
  ["_VermilionGymGentlemanAfterBattleText"] = "Die Tür geht\nnicht auf?\fMAJOR BOB war\nschon immer\vvorsichtig!",
  ["_VermilionGymGentlemanBattleText"] = "Beim Militär war\nMAJOR BOB mein\vstrenger Chef!",
  ["_VermilionGymGentlemanEndBattleText"] = "Stopp!\nDu bist sehr gut!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Puh! Der Kampf\nwar elektrisie-\vrend!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Yo! Champ in spe!\fMAJOR BOB hat\neinen Spitznamen:\vDer blitzende\vAmerikaner!\fEr ist Experte\nfür Elektro-\vPOKéMON!\fVogel- und Wasser-\nPOKéMON sind in\vGefahr! Vorsicht\vvor Paralyse!\fMAJOR BOB ist\nsehr vorsichtig!\fDu musst einen\nCode knacken, um\vzu ihm zu kommen!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Ein kleiner Rat,\nKleiner!\fElektrizität ist\nmächtig!\fAber gegen Boden-\nPOKéMON ist sie\vnutzlos!",
  ["_VermilionGymLTSurgePreBattleText"] = "Hey, Kleiner! Was\nwillst du hier?\fIm Kampf über-\nlebst du nicht\vlange! Sicher!\fElektro-POKéMON\nhaben mich im\vKrieg gerettet!\fSie haben meine\nFeinde paraly-\vsiert!\fGenau das mache\nich mit dir!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Wow!\fDu hast es echt\ndrauf, Kleiner!\fNa gut, nimm den\nDONNERORDEN!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Yo, Kleiner, mach\nPlatz im Beutel!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "Der DONNERORDEN\nerhöht den TEMPO-\vWert deiner\vPOKéMON!\fMit ihm können\nsie jederzeit\vFLIEGEN nutzen!\fDu bist was Be-\nsonderes! Nimm\vdas hier!",
  ["_VermilionGymSailorAfterBattleText"] = "MAJOR BOB nutzt\nDoppelschlösser!\vEin Tip:\fÖffnest du das 1.\nSchloss, ist das\v2. gleich daneben!",
  ["_VermilionGymSailorBattleText"] = "Das ist kein Ort\nfür Kinder!",
  ["_VermilionGymSailorEndBattleText"] = "Wow! Du hast mich\nüberrascht!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, ich rede!\fMAJOR BOB hat die\nSchalter in etwas\vversteckt!",
  ["_VermilionGymSuperNerdBattleText"] = "Ich bin ein\nLeichtgewicht,\vaber gut mit\vStrom!",
  ["_VermilionGymSuperNerdEndBattleText"] = "Durchgebrannt!",
  ["_VermilionGymTrashFailText"] = "Nichts, hier ist\nnur Müll.\vHey! Die Elektro-\vSchlösser wurden\vzurückgesetzt!",
  ["_VermilionGymTrashSuccessText1"] = "Hey! Unter dem\nMüll ist ein\vSchalter!\vLeg ihn um!\fDas 1. Elektro-\nSchloss ist offen!",
  ["_VermilionGymTrashSuccessText2"] = "Hey! Noch ein\nSchalter unter\vdem Müll!\vLeg ihn um!",
  ["_VermilionGymTrashSuccessText3"] = "Das 2. Elektro-\nSchloss ist offen!\fDie Motortür\nöffnet sich!",
  ["_VermilionGymTrashText"] = "Nichts, hier ist\nnur Müll.",
  ["_VermilionMartCooltrainerFText"] = "POKéMON können\ngut oder böse\vsein. Es hängt\vvom TRAINER ab.",
  ["_VermilionMartCooltrainerMText"] = "Böse Menschen\nmißbrauchen\vPOKéMON für\vVerbrechen.\fTEAM ROCKET han-\ndelt mit seltenen\vPOKéMON.\fSie setzen auch\nPOKéMON aus, die\vsie für nutzlos\vhalten.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Ich bin der\nANGEL-GURU!\fIch liiiebe das\nAngeln!\fAngelst du auch\ngerne?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\fAngeln ist eine\nLebensart!\fOb Meer oder\nFluss, zieh los\vund angle den\vganz Großen!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Hallo, {PLAYER}!\fBeißen die\nFische gut?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh nein!\fDu hast keinen\nPlatz für mein\vGeschenk!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Prima! Du ge-\nfällst mir!\fNimm dies und\nangle damit!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Wie ent-\ntäuschend...",
  ["_VermilionPidgeyHouseLetterText"] = "Liebes PIPPI, ich\nhoffe, wir sehen\vuns bald.\fSAFFRONIA hat\nwohl Probleme mit\vTEAM ROCKET.\fORANIA scheint\nsicher zu sein.",
  ["_VermilionPidgeyHousePidgeyText"] = "TAUBSI: Kurukkuu!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mein TAUBSI soll\neinen Brief nach\vSAFFRONIA im\vNorden fliegen!",
  ["_VermilionPokecenterFishingGuruText"] = "Selbst auf glei-\nchem Level können\vPOKéMON ganz ver-\vschieden stark\vsein.\fEin vom TRAINER\ntrainiertes ist\vstärker als ein\vwildes POKéMON.",
  ["_VermilionPokecenterGuyText"] = "Höhere Level\nmachen POKéMON\vzwar stärker...\fDoch jedes hat\nSchwächen gegen\vbestimmte Typen.\fEs gibt also kein\nunbesiegbares\vPOKéMON.",
  ["_VermilionPokecenterSailorText"] = "Mein POKéMON war\nvergiftet! Es\vfiel unterwegs in\vOhnmacht!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Ich wollte nie\ngegen jemanden\vverlieren!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Ob du wohl gut\ngenug für mich\vbist?",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ich habe\nverloren!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Ich gebe zu, du\nbist besser!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Du bist gut! Mal\nsehen, wie gut\vgenau!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Ich hatte\neine Chance...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Du hast dir die\nSIEGESSTRASSE\vverdient!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Komm her!\nIch vermöble\vdich!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Ich wurde\nvermöbelt!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Kommst du nicht\nweiter, verschie-\vbe ein paar\vFelsen!",
  ["_VictoryRoad2FHikerBattleText"] = "Die SIEGESSTRASSE\nist die letzte\vPrüfung für\vTRAINER!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiyah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL} kam auch\nhier durch!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah, du willst die\nTOP VIER heraus-\vfordern?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Du hast\nmich erwischt!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Bei POKéMON-\nWissen schlage\vich dich!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Wer hier durch-\nkommt, darf zu\vden TOP VIER!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Nein!\nUnglaublich!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Viele TRAINER\ngeben hier auf.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "Ist die SIEGES-\nSTRASSE zu hart?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Gut\ngemacht!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Du hast mir ge-\nzeigt, wie gut\vich war!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Ich zeige dir,\nwie gut du bist!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Ich bin\nwütend!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Harte Kämpfe\nmachen dich\vstärker!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "TRAINER leben für\ndie Suche nach\vstarken Gegnern!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nSo stark!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Du hast GIOVANNI\nvon TEAM ROCKET\vbesiegt?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Ich hörte Gerüch-\nte über ein\vWunderkind!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Die Gerüchte\nstimmten!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Alle TRAINER hier\nwollen zur\vPOKéMON LIGA!\vSei vorsichtig!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Nur Auserwählte\nkommen hier\vdurch!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Ich glaube\nes nicht!",
  ["_VictreebelDexEntry"] = "Soll in großen\nKolonien tief im\nDschungel leben,\fdoch niemand\nkehrte je von\ndort zurück",
  ["_VileplumeDexEntry"] = "Je größer die\nBlütenblätter,\ndesto giftiger\fder Pollen. Der\ngroße Kopf ist\nsehr schwer",
  ["_ViridianBlackboardBurnText"] = "Verbrennung senkt\nStärke und Tempo\vund fügt laufend\vSchaden zu.\fSie bleibt nach\ndem Kampf.\fNutze FEUERHEILER\ndagegen!",
  ["_ViridianBlackboardFrozenText"] = "Ein gefrorenes\nPOKéMON kann sich\vnicht bewegen!\fEs bleibt auch\nnach dem Kampf\vgefroren.\fEISHEILER taut\nPOKéMON auf!",
  ["_ViridianBlackboardPoisonText"] = "Bei Vergiftung\nsinken die KP\vstetig.\fGift bleibt nach\ndem Kampf beste-\vhen.\fEin GEGENGIFT\nheilt Vergiftung!",
  ["_ViridianBlackboardPrlzText"] = "Paralyse lässt\nAttacken oft\vfehlschlagen!\fSie bleibt nach\ndem Kampf beste-\vhen.\fPARA-HEILER\nhilft dagegen!",
  ["_ViridianBlackboardSleepText"] = "Ein schlafendes\nPOKéMON kann\vnicht angreifen!\fEs schläft auch\nnach dem Kampf\vweiter.\fAUFWECKER weckt\nes wieder auf!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} erhält\nTM42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "TM42 enthält\nTRAUMFRESSER...\v...Schnarch...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Du hast schon zu\nviele Sachen.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Diese POKéMON-\nARENA ist immer\vzu.\fWer wohl der\nLEITER ist?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Der LEITER der\nVERTANIA-ARENA\vist zurück!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Ach, Opa! Sei\nnicht so gemein!\vEr hatte noch\vkeinen Kaffee.",
  ["_ViridianCityGirlWhenIGoShopText"] = "Zum Einkaufen in\nMARMORIA CITY muss\vich durch den\vVERTANIA-WALD.",
  ["_ViridianCityGymLockedText"] = "Die ARENA-Türen\nsind verschlos-\vsen...",
  ["_ViridianCityGymSignText"] = "VERTANIA CITY\nPOKéMON-ARENA",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, jetzt hatte\nich meinen Kaffee\vund fühle mich\vprima!\fKlar kannst du\ndurch!\fHast du es\neilig?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Du benutzt also\neinen POKéDEX.\fFängst du ein\nPOKéMON, wird der\vPOKéDEX automa-\vtisch ergänzt.\fWas? Du weisst\nnicht, wie man\vPOKéMON fängt?\fDann zeige ich\nes dir mal.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Hier kommst du\nnicht durch!\fDies ist Privat-\ngrundstück!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Zeit ist Geld...\nGeh nur weiter.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Zuerst musst du\ndas POKéMON\vschwächen.",
  ["_ViridianCityPokecenterGuyText"] = "POKéMON-CENTER\nheilen müde und\vverletzte\vPOKéMON!",
  ["_ViridianCitySignText"] = "VERTANIA CITY\nDas ewig grüne\vParadies",
  ["_ViridianCityTrainerTips1Text"] = "TRAINER-TIPS\fFange POKéMON und\nerweitere deine\vSammlung!\fJe mehr du hast,\ndesto leichter\vwird das Kämpfen!",
  ["_ViridianCityTrainerTips2Text"] = "TRAINER-TIPS\fDie Attacken der\nPOKéMON sind\vdurch AP begrenzt.\fRuhe im POKéMON-\nCENTER füllt die\vAP wieder auf!",
  ["_ViridianCityYoungster1Text"] = "Die POKéBALLs an\ndeinem Gürtel!\vDu hast POKéMON!\fToll, dass man sie\nüberall dabei-\vhaben und nutzen\vkann!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Du willst etwas\nüber die 2 Rau-\vpen-POKéMON\vwissen?",
  ["_ViridianForestLeavingSignText"] = "ENDE DES\nVERTANIA-WALDS\vMARMORIA CITY\vVORAUS",
  ["_ViridianForestNorthGateGrampsText"] = "Sind dir die\nBüsche am Weg-\vrand aufgefallen?\fEine besondere\nPOKéMON-Attacke\vkann sie fällen.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Viele POKéMON le-\nben nur in Wäl-\vdern und Höhlen.\fSuche überall,\num verschiedene\vzu finden!",
  ["_ViridianForestSouthGateGirlText"] = "Gehst du in den\nVERTANIA-WALD?\vVorsicht, er ist\vein Labyrinth!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTFRATZ ist\nklein, aber sein\vBiß ist übel!\vHast du eins?",
  ["_ViridianForestTrainerTips1Text"] = "TRAINER-TIPS\fWer Kämpfen aus-\nweichen will,\vmeidet hohes\vGras!",
  ["_ViridianForestTrainerTips2Text"] = "TRAINER-TIPS\fKontaktiere PROF.\nEICH per PC, um\vden POKéDEX be-\vwerten zu lassen!",
  ["_ViridianForestTrainerTips3Text"] = "TRAINER-TIPS\fPOKéMON anderer\nTRAINER stehlen\vverboten!\vFange nur wilde\vPOKéMON!",
  ["_ViridianForestTrainerTips4Text"] = "TRAINER-TIPS\fSchwäche POKéMON\nvor dem Fangen!\fBei vollen KP\nentkommen sie\vleicht!",
  ["_ViridianForestUseAntidoteSignText"] = "Bei Gift hilft\nGEGENGIFT! Gibt\ves im POKéMON-\vMARKT!",
  ["_ViridianForestYoungster1Text"] = "Ich bin mit\nFreunden hier!\fSie sind auf\nPOKéMON-Kämpfe\vaus!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Psst! Du ver-\nscheuchst die\vKäfer!",
  ["_ViridianForestYoungster2BattleText"] = "Hey! Du hast\nPOKéMON! Los,\vlaß uns kämpfen!",
  ["_ViridianForestYoungster2EndBattleText"] = "Nein! RAUPY\nreicht nicht!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Mist! Ich fange\nmir stärkere!",
  ["_ViridianForestYoungster3BattleText"] = "Yo! Als POKéMON-\nTRAINER darfst du\vnicht kneifen!",
  ["_ViridianForestYoungster3EndBattleText"] = "Was? Ich habe\nkeine POKéMON\vmehr!",
  ["_ViridianForestYoungster4AfterBattleText"] = "Manchmal findet\nman Sachen auf\vdem Boden!\fIch suche, was\nich verloren\vhabe!",
  ["_ViridianForestYoungster4BattleText"] = "Hey, warte!\nWozu die Eile?",
  ["_ViridianForestYoungster4EndBattleText"] = "Ich gebe auf!\nDu bist gut!",
  ["_ViridianForestYoungster5Text"] = "Meine POKéBALLs\nzum Fangen sind\valle!\fNimm immer ein\npaar extra mit!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Du brauchst\nPower, um mit\vunserem LEITER\vmitzuhalten!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Heh! Dir geht\nwohl langsam die\vPuste aus!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Mir ging die\nPuste aus!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Der LEITER wird\nmich schelten!",
  ["_ViridianGymCooltrainerM2BattleText"] = "Wahre Talente\nsiegen mit Stil!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Ich habe den\nHalt verloren!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Nur wer unseren\nARENALEITER be-\vsiegt, darf zur\vPOKéMON LIGA!",
  ["_ViridianGymCooltrainerM3BattleText"] = "Die VERTANIA-\nARENA war lange\vzu, doch unser\vLEITER ist\vzurück!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Ich wurde\nbesiegt?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "Der ERDORDEN lässt\nPOKéMON jeden\vLevels gehorchen!\fEr beweist deine\nMeisterschaft als\vPOKéMON-TRAINER!\fMit ihm kannst du\nan der POKéMON\vLIGA teilnehmen!\fEr ist mein Ge-\nschenk für deine\vLIGA-Heraus-\vforderung!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Nach dieser Nie-\nderlage kann ich\vmeinen Leuten\vnicht begegnen!\vTEAM ROCKET ist\vfür immer am\vEnde!\fIch widme mein\nLeben nun dem\vStudium der\vPOKéMON!\fWir sehen uns\neines Tages\vwieder! Leb wohl!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha! Dies\nist mein Ver-\vsteck!\fHier wollte ich\nTEAM ROCKET neu\verstehen lassen!\fDoch du hast mich\nwieder gestellt!\vNun gut! Diesmal\vhalte ich mich\vnicht zurück!\fNoch einmal\ntriffst du auf\vGIOVANNI, den\vgrößten TRAINER!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha!\nEin wahrhaft in-\vtensiver Kampf!\vDu hast gewonnen!\vZum Beweis: der\vERDORDEN!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} erhält\nTM27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\fTM27 ist GEOWALL!\nBesiegt POKéMON\vmit nur einem\vTreffer!\fIch machte sie,\nals ich hier noch\vdie ARENA führte,\vvor langer Zeit...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Du hast dafür\nkeinen Platz!",
  ["_ViridianGymGuidePostBattleText"] = "Nicht zu fassen!\nGIOVANNI war der\vARENALEITER\vhier?",
  ["_ViridianGymGuidePreBattleText"] = "Yo! Champ in spe!\fSelbst ich kenne\ndie Identität des\vLEITERs nicht!\fEr ist der här-\nteste aller\vARENALEITER!\fDie TRAINER hier\nmögen wohl Boden-\vPOKéMON!",
  ["_ViridianGymHiker1AfterBattleText"] = "Ich bin noch\nnicht würdig!",
  ["_ViridianGymHiker1BattleText"] = "Grrroar! Ich\nsteigere mich in\vRage!",
  ["_ViridianGymHiker1EndBattleText"] = "Wargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Könnten meine\nPOKéMON Karate\vso gut wie ich...",
  ["_ViridianGymHiker2BattleText"] = "Karate ist die\nultimative\vKampfkunst!",
  ["_ViridianGymHiker2EndBattleText"] = "Atcho!",
  ["_ViridianGymHiker3AfterBattleText"] = "POKéMON LIGA?\nDu? Werd nicht\vübermütig!",
  ["_ViridianGymHiker3BattleText"] = "Ich bin der\nKARATE-KÖNIG!\vDein Schicksal\vliegt bei mir!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Kennst du die\nIdentität unseres\vLEITERs?",
  ["_ViridianGymRocker1BattleText"] = "POKéMON und ich\nmachen wunderbare\vMusik zusammen!",
  ["_ViridianGymRocker1EndBattleText"] = "Ihr seid in per-\nfekter Harmonie!",
  ["_ViridianGymRocker2AfterBattleText"] = "Warte! Ich war\nnur unachtsam!",
  ["_ViridianGymRocker2BattleText"] = "Deine POKéMON\nwerden vor meiner\vPeitsche kuschen!",
  ["_ViridianGymRocker2EndBattleText"] = "Autsch!\nPeitschenhieb!",
  ["_ViridianMartClerkParcelQuestText"] = "Du kennst doch\nPROF. EICH?\fSeine Bestellung\nkam an. Bringst\vdu sie ihm?\f{PLAYER} erhält\nEICHs PAKET!",
  ["_ViridianMartClerkSayHiToOakText"] = "Okay! Grüß PROF.\nEICH von mir!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Hey! Du kommst\naus ALABASTIA?",
  ["_ViridianMartCooltrainerMText"] = "Nein! Die TRÄNKE\nsind ausverkauft.",
  ["_ViridianMartYoungsterText"] = "Dieser Laden hat\nviele GEGENGIFTE.",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Spitznamen aus-\nzudenken macht\vSpaß, ist aber\vschwer.\fEinfache Namen\nmerkt man sich\vam besten.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Mein Papi liebt\nPOKéMON auch.",
  ["_ViridianNicknameHouseSpearowText"] = "HABI: Tetwiet!",
  ["_ViridianNicknameHouseSpearySignText"] = "HABITAK\nName: HABI",
  ["_ViridianPokecenterCooltrainerMText"] = "In jeder Stadt\ngibt es ein\vPOKéMON-CENTER.\fSie verlangen\nnicht mal Geld!",
  ["_ViridianPokecenterGentlemanText"] = "Du kannst den PC\nin der Ecke be-\vnutzen.\fDie Empfangsdame\nsagte es mir. So\vnett!",
  ["_ViridianSchoolBlackboardText1"] = "Die Tafel be-\nschreibt STATUS-\vVeränderungen im\vKampf.",
  ["_ViridianSchoolBlackboardText2"] = "Welchen Eintrag\nwillst du lesen?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Puh! Ich versuche,\nmeine Notizen\vauswendig zu\vlernen.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Okay!\fLies dir die\nTafel genau\vdurch!",
  ["_ViridianSchoolNotebookText1"] = "Das Heft ange-\nsehen!\fErste Seite...\fPOKéBALLs dienen\nzum Fangen von\vPOKéMON.\fBis zu 6 POKéMON\nkann man dabei-\vhaben.\fWer POKéMON auf-\nzieht und kämpfen\vlässt, heisst\vPOKéMON-TRAINER.",
  ["_ViridianSchoolNotebookText2"] = "Zweite Seite...\fGesunde POKéMON\nsind schwer zu\vfangen. Schwäche\vsie erst!\fGift, Verbrennung\nund anderes\vwirken gut!",
  ["_ViridianSchoolNotebookText3"] = "Dritte Seite...\fPOKéMON-TRAINER\nsuchen andere für\vPOKéMON-Kämpfe.\fIn POKéMON-ARENEN\nwird ständig\vgekämpft.",
  ["_ViridianSchoolNotebookText4"] = "Vierte Seite...\fZiel der TRAINER\nist es, die 8 be-\vsten ARENALEITER\vzu besiegen.\fDann erhält man\ndas Recht auf...\fDie TOP VIER der\nPOKéMON LIGA!",
  ["_ViridianSchoolNotebookText5"] = "MÄDCHEN: Hey!\nSieh nicht in\vmeine Notizen!",
  ["_VitaminNoEffectText"] = "Es hätte keine\nWirkung.",
  ["_VitaminStatRoseText"] = "{RAM:wNameBuffer}:\n{RAM:wStringBuffer} stieg.",
  ["_VoltorbDexEntry"] = "Lebt meist in\nKraftwerken. Wird\nleicht mit einem\fPOKéBALL ver-\nwechselt und hat\nviele geschockt",
  ["_VulpixDexEntry"] = "Bei der Geburt\nhat es nur einen\nSchweif. Dieser\fspaltet sich mit\ndem Alter von der\nSpitze her",
  ["_WannaTrade1Text"] = "Ich suche\n{RAM:wInGameTradeGiveMonName}! Tauschst\fdu eins gegen\n{RAM:wInGameTradeReceiveMonName}? ",
  ["_WannaTrade2Text"] = "Hallo! Willst du\ndein {RAM:wInGameTradeGiveMonName}\fgegen {RAM:wInGameTradeReceiveMonName}\ntauschen?",
  ["_WannaTrade3Text"] = "Hi! Hast du\n{RAM:wInGameTradeGiveMonName}?\fTauschst du es\ngegen {RAM:wInGameTradeReceiveMonName}?",
  ["_WardensHouseDisplayMerchandiseText"] = "Alte POKéMON-\nArtikel.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "POKéMON-Fotos\nund Fossilien.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} gibt dem\nWÄRTER die GOLD-\vZÄHNE!",
  ["_WardensHouseWardenGibberish1Text"] = "WÄRTER: Hif fuff\nhefifoo!\fHa lof ha feef ee\nhafahi ho. Heff\vhee fwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
  ["_WardensHouseWardenGibberish3Text"] = "Ha? He ohay heh\nha hoo ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "WÄRTER: VM04\nlehrt STÄRKE!\fDamit können\nPOKéMON außerhalb\vvon Kämpfen Fel-\vsen verschieben.\fAch ja, hast du\ndas GEHEIMHAUS in\vder SAFARI-ZONE\vgefunden?\fDort gewinnst\ndu eine VM!\fEs soll die sel-\ntene SURFER-VM\vsein.",
  ["_WardensHouseWardenHM04NoRoomText"] = "Dein Beutel ist\nvollgestopft!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "\fDer WÄRTER setzt\nseine Zähne ein!",
  ["_WardensHouseWardenThanksText"] = "WÄRTER: Danke,\nKleiner! Niemand\vverstand ein Wort\vvon mir.\fSo konnte ich\nnicht arbeiten.\vNimm dies für\vdeine Mühe.",
  ["_WarpToLastPokemonCenterText"] = "Warp zum letzten\nPOKéMON-CENTER.",
  ["_WartortleDexEntry"] = "Lauert oft im\nWasser auf Beute.\nBeim schnellen\fSchwimmen halten\ndie Ohren das\nGleichgewicht",
  ["_WasBlownAwayText"] = "{TARGET}\nwurde weggefegt!",
  ["_WasSeededText"] = "{TARGET}\nwurde bepflanzt!",
  ["_WeedleDexEntry"] = "Lebt oft in Wäl-\ndern und frisst\nBlätter. Es hat\feinen spitzen\nGiftstachel am\nKopf",
  ["_WeepinbellDexEntry"] = "Es verschießt\nGIFTPUDER, um den\nGegner zu lähmen,\fund erledigt ihn\ndann mit einem\nSchwall SÄURE",
  ["_WeezingDexEntry"] = "Wo sich zwei\nGiftgase treffen,\nkönnen 2 SMOGON\füber Jahre zu\neinem SMOGMOG\nverschmelzen",
